        self.last_comparator_status = None
        self.last_comparator_value = None

        try:
            self.bus = smbus2.SMBus(busnum)
            if debug:
                logger.debug(f"Opened I2C bus {busnum}")
        except FileNotFoundError:
            logger.error(f"I2C bus {busnum} not found. Please enable I2C in raspi-config.")
            raise
        except PermissionError:
            logger.error(f"Permission denied on I2C bus {busnum}. Run as root or add user to i2c group.")
            raise
        except Exception as e:
            logger.error(f"Failed to open I2C bus {busnum}: {e}")
            raise

    def _write_register(self, register, value):
        """Writes a 16-bit value to the specified register."""
        try:
            self.bus.write_i2c_block_data(self.address, register, [(value >> 8) & 0xFF, value & 0xFF])
        except OSError as e:
            logger.error(f"I2C write error to register 0x{register:02X}: {e}")
            raise

    def _read_register(self, register):
        """Reads a 16-bit value from the specified register."""
        try:
            result = self.bus.read_i2c_block_data(self.address, register, 2)
            return (result[0] << 8) | result[1]
        except OSError as e:
            logger.error(f"I2C read error from register 0x{register:02X}: {e}")
            raise

