import smbus
import time
import signal
import sys

# ADS1115 constants
ADS1115_ADDRESS = 0x48
ADS1115_REG_CONVERSION = 0x00
ADS1115_REG_CONFIG = 0x01

# Config: single-shot, AIN0 vs GND, 4.096 V, 128 SPS
ADS1115_CONFIG = 0xC083

# Voltage divider parameters
VOLTAGE_DIVIDER_RATIO = 2.0
FULL_BATTERY_VOLTAGE = 4.2
EMPTY_BATTERY_VOLTAGE = 3.0

# Global flag for graceful shutdown
_running = True

def signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c_bus(bus_number=1):
    try:
        bus = smbus.SMBus(bus_number)
        return bus
    except FileNotFoundError:
        print(f"Error: I2C bus {bus_number} not found. Enable I2C via raspi-config.")
        return None
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {bus_number}. Run as root or add user to 'i2c' group.")
        return None
    except Exception as e:
        print(f"Error initializing I2C bus {bus_number}: {e}")
        return None

def configure_ads1115(bus, address=ADS1115_ADDRESS):
    try:
        # Write config: single-shot, AIN0 vs GND, 4.096 V, 128 SPS
        bus.write_i2c_block_data(address, ADS1115_REG_CONFIG, [(ADS1115_CONFIG >> 8) & 0xFF, ADS1115_CONFIG & 0xFF])
        return True
    except OSError as e:
        print(f"Error configuring ADS1115 at 0x{address:02X}: {e}")
        return False

def read_raw_ads1115(bus, address=ADS1115_ADDRESS):
    try:
        # Trigger a single-shot conversion
        bus.write_i2c_block_data(address, ADS1115_REG_CONFIG, [(ADS1115_CONFIG >> 8) & 0xFF, ADS1115_CONFIG & 0xFF])
        time.sleep(0.01)  # Wait for conversion to complete (128 SPS -> ~7.8 ms, 10 ms is safe)

        # Read 2 bytes from conversion register
        data = bus.read_i2c_block_data(address, ADS1115_REG_CONVERSION, 2)
        raw = (data[0] << 8) | data[1]

        # Convert to signed 16-bit integer
        if raw >= 0x8000:
            raw -= 0x10000
        return raw
    except OSError as e:
        print(f"Error reading ADS1115: {e}")
        return None

def calculate_battery_voltage(raw_value, voltage_divider_ratio=VOLTAGE_DIVIDER_RATIO):
    if raw_value is None:
        return None
    # ADS1115 is 16-bit signed; full scale is 4.096 V
    measured_voltage = (raw_value / 32767.0) * 4.096
    battery_voltage = measured_voltage * voltage_divider_ratio
    return battery_voltage

def calculate_battery_percentage(battery_voltage, full_battery_voltage=FULL_BATTERY_VOLTAGE, empty_battery_voltage=EMPTY_BATTERY_VOLTAGE):
    if battery_voltage is None:
        return None
    percentage = ((battery_voltage - empty_battery_voltage) / (full_battery_voltage - empty_battery_voltage)) * 100
    return max(0.0, min(100.0, percentage))

def display_battery_status(battery_voltage, battery_percentage):
    if battery_voltage is not None and battery_percentage is not None:
        print(f"Battery Voltage: {battery_voltage:.2f} V | Charge: {battery_percentage:.2f}%")
    else:
        print("Failed to read battery data.")

def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = initialize_i2c_bus(1)
    if bus is None:
        sys.exit(1)

    try:
        while _running:
            if not configure_ads1115(bus):
                time.sleep(1)
                continue

            raw_value = read_raw_ads1115(bus)
            battery_voltage = calculate_battery_voltage(raw_value)
            battery_percentage = calculate_battery_percentage(battery_voltage)

            # Only update display if percentage changed by more than 1%
            if battery_percentage is not None:
                if battery_percentage != display_battery_status.battery_percentage:
                    display_battery_status(battery_voltage, battery_percentage)

            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus:
            bus.close()
            print("I2C bus closed.")

if __name__ == "__main__":
    display_battery_status.battery_percentage = None
    main()

