    _safe_set_pwm_duty(255)


def _safe_set_pwm_value(value: int) -> None:
    _safe_set_pwm_duty(value)


def _safe_set_direction_ccw() -> None:
    _safe_set_direction(CCW)


def _safe_set_direction_cw() -> None:
    _safe_set_direction(CW)


