import time
import signal
import sys
import logging
from typing import Optional, Tuple

import RPi.GPIO as GPIO
from Adafruit_ADS1x15 import ADS1015
from adafruit_lsm303_accel import LSM303_Accel
from adafruit_lsm303dlh_mag import LSM303DLH_Mag

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
DIR_PIN = 20
STEP_PIN = 21
CW = 1
CCW = 0
MS0_PIN = 14
MS1_PIN = 15

PWM_FREQ = 500          # Hz
ADC_GAIN = 1             # PGA gain 1 -> +/-4.096 V full-scale
ADC_MAX = 32767          # 16-bit signed max positive value

I2C_BUS = 1
I2C_ACCEL_ADDR = 0x18
I2C_MAG_ADDR = 0x1E

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("stepper_control")

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_pwm: Optional[GPIO.PWM] = None
_running = True


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def _cleanup():
    global _pwm
    if _pwm is not None:
        try:
            _pwm.stop()
        except Exception:
            pass
        _pwm = None
    try:
        GPIO.cleanup()
    except Exception:
        pass
    log.info("GPIO cleaned up.")


def _safe_gpio_setup(pin: int, mode: int) -> None:
    try:
        GPIO.setup(pin, mode)
    except Exception as exc:
        log.error("GPIO.setup(pin=%d, mode=%d) failed: %s", pin, mode, exc)
        raise


def _safe_gpio_output(pin: int, value: bool) -> None:
    try:
        GPIO.output(pin, value)
    except Exception as exc:
        log.error("GPIO.output(pin=%d, value=%s) failed: %s", pin, value, exc)
        raise


def _safe_gpio_set_pwm(pin: int, freq: int, duty: int) -> None:
    global _pwm
    try:
        if _pwm is not None:
            _pwm.stop()
        _pwm = GPIO.PWM(pin, freq)
        _pwm.start(duty)
    except Exception as exc:
        log.error("GPIO.PWM(pin=%d, freq=%d, duty=%d) failed: %s", pin, freq, duty, exc)
        _pwm = None
        raise


def _safe_ads_read(adc: ADS1015, channel: int) -> Optional[int]:
    try:
        return adc.read_adc(channel, gain=ADC_GAIN)
    except Exception as exc:
        log.error("ADS1015 read_adc(channel=%d) failed: %s", channel, exc)
        return None


def _safe_accel_read(accel: LSM303_Accel) -> Optional[Tuple[float, float, float]]:
    try:
        return accel.acceleration
    except Exception as exc:
        log.error("LSM303 accelerometer read failed: %s", exc)
        return None


def _safe_mag_read(mag: LSM303DLH_Mag) -> Optional[Tuple[float, float, float]]:
    try:
        return mag.magnetic
    except Exception as exc:
        log.error("LSM303 magnetometer read failed: %s", exc)
        return None


def _safe_mag_heading(mag: LSM303DLH_Mag) -> Optional[float]:
    try:
        return mag.heading
    except Exception as exc:
        log.error("LSM303 heading read failed: %s", exc)
        return None


def _safe_set_pwm_duty(duty: int) -> None:
    if _pwm is not None:
        try:
            _pwm.ChangeDutyCycle(duty)
        except Exception as exc:
            log.error("PWM.ChangeDutyCycle(%d) failed: %s", duty, exc)
            _pwm = None


def _safe_set_microstep(ms0: int, ms1: int) -> None:
    _safe_gpio_output(MS0_PIN, ms0)
    _safe_gpio_output(MS1_PIN, ms1)


def _safe_set_direction(direction: int) -> None:
    _safe_gpio_output(DIR_PIN, direction)


def _safe_set_step() -> None:
    _safe_gpio_output(STEP_PIN, GPIO.HIGH)
    time.sleep(0.001)
    _safe_gpio_output(STEP_PIN, GPIO.LOW)
    time.sleep(0.001)


def _safe_set_pwm_zero() -> None:
    _safe_set_pwm_duty(0)


def _safe_set_pwm_max() -> None:
    _safe_set_pwm_duty(255)


def _safe_set_pwm_value(value: int) -> None:
    _safe_set_pwm_duty(value)


def _safe_set_direction_ccw() -> None:
    _safe_set_direction(CCW)


def _safe_set_direction_cw() -> None:
    _safe_set_direction(CW)


