import time
import logging
import argparse
import threading
import queue
import spidev
import RPi.GPIO as GPIO

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.running = False
        self.stop_event = threading.Event()

        if self.sensor_type == "digital":
            if not self.gpio_pins:
                raise ValueError("gpio_pins must be provided for digital sensor")
            self.gpio_pin = self.gpio_pins[0]
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        elif self.sensor_type == "analog":
            if not self.channels:
                raise ValueError("channels must be provided for analog sensor")
            self.channel = self.channels[0]
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
            except Exception as e:
                raise RuntimeError(f"Failed to initialize SPI: {e}")
        else:
            raise ValueError("Invalid sensor type")

    def read_digital(self):
        try:
            return GPIO.input(self.gpio_pin)
        except Exception as e:
            logging.error(f"Error reading digital sensor {self.sensor_id}: {e}")
            return None

    def read_analog(self):
        try:
            adc = self.spi.xfer2([1, (8 + self.channel) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            logging.error(f"Error reading analog sensor {self.sensor_id}: {e}")
            return None

    def detect_event(self):
        if self.sensor_type == "digital":
            reading = self.read_digital()
            if reading is not None and reading == 1:
                return True
        elif self.sensor_type == "analog":
            reading = self.read_analog()
            if reading is not None and reading >= self.threshold:
                return True
        return False

    def log_event(self):
        if self.log_queue:
            try:
                self.log_queue.put(f"Event detected by sensor {self.sensor_id}")
            except Exception as e:
                logging.error(f"Error logging event for sensor {self.sensor_id}: {e}")

    def run(self):
        self.running = True
        while self.running and not self.stop_event.is_set():
            try:
                if self.detect_event():
                    self.log_event()
                time.sleep(1 / self.sample_rate)
            except Exception as e:
                logging.error(f"Error in sensor {self.sensor_id} loop: {e}")
                time.sleep(1)

    def stop(self):
        self.running = False
        self.stop_event.set()
        if self.spi:
            try:
                self.spi.close()
            except Exception:
                pass

    def cleanup(self):
        if self.sensor_type == "digital":
            try:
                GPIO.cleanup(self.gpio_pin)
            except Exception:
                pass

def main():
    parser = argparse.ArgumentParser(description="Sound sensor monitoring system")
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"])
    parser.add_argument("--threshold", type=int, required=True)
    parser.add_argument("--sample_rate", type=float, required=True)
    parser.add_argument("--log_file", required=True)
    parser.add_argument("--gpio_pins", nargs="+", type=int)
    parser.add_argument("--channels", nargs="+", type=int)
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", nargs="+", required=True)
    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
    log_queue = queue.Queue()

    sensors = []
    for sensor_id in args.sensor_ids:
        try:
            sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed, log_queue)
            sensors.append(sensor)
        except Exception as e:
            logging.error(f"Failed to create sensor {sensor_id}: {e}")

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=sensor.run)
        threads.append(thread)
        thread.start()

    try:
        while True:
            try:
                message = log_queue.get(timeout=1)
                logging.info(message)
            except queue.Empty:
                pass
    except KeyboardInterrupt:
        logging.info("Shutting down...")
    finally:
        for sensor in sensors:
            sensor.stop()
            sensor.cleanup()
        for thread in threads:
            thread.join()

if __name__ == "__main__":
    main()

