import signal
import sys
import time
import math
import numpy as np
import pigpio

try:
    from adafruit_lsm303_accel import LSM303_Accel
    from adafruit_lsm303dlh_mag import LSM303DLH_Mag
    from adafruit_ads1x15.ads1015 import ADS1015
    from adafruit_ads1x15.analog_in import AnalogIn
except ImportError as exc:
    print(f"Missing required library: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-lsm303-accel adafruit-circuitpython-lsm303dlh-mag adafruit-circuitpython-ads1x15", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Pin / timing constants
# ---------------------------------------------------------------------------
MOTOR_DIR_PIN = 20
MOTOR_STEP_PIN = 21
MOTOR_RESOLUTION_PINS = (14, 15)          # MS0 / MS1
MOTOR_STEPS_PER_REV = 200
MOTOR_PPR = 64
PWM_FREQUENCY = 500                       # Hz
SAMPLE_COUNT = 1648
SAMPLE_INTERVAL = 1.0                     # seconds
LOOP_HZ = 1.0
ADC_CHANNELS = (0, 1, 2, 3)

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_pi = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


def _cleanup():
    """Release hardware resources on exit."""
    global _pi
    if _pi is not None and _pi.connected:
        try:
            _pi.hardware_PWM(MOTOR_STEP_PIN, PWM_FREQUENCY, 0)
        except Exception:
            pass
        try:
            _pi.write(MOTOR_DIR_PIN, 0)
        except Exception:
            pass
        for pin in MOTOR_RESOLUTION_PINS:
            try:
                _pi.write(pin, 0)
            except Exception:
                pass
        _pi.stop()


def _safe_init_sensor(name, factory, **kwargs):
    """Initialize a sensor, returning None on failure."""
    try:
        return factory(**kwargs)
    except Exception as exc:
        print(f"Error initializing {name}: {exc}", file=sys.stderr)
        return None


def _safe_read_adc(channel, adc, pin):
    """Read a single ADC channel, returning None on error."""
    try:
        return adc.read_voltage(channel)
    except Exception as exc:
        print(f"Error reading ADC channel {channel}: {exc}", file=sys.stderr)
        return None


def _safe_read_accel(mag, accel):
    """Read magnetometer and accelerometer, returning (mag, accel) or (None, None)."""
    try:
        mag_x, mag_y, mag_z = mag.magnetic
    except Exception as exc:
        print(f"Error reading magnetometer: {exc}", file=sys.stderr)
        return None, None
    try:
        acc_x, acc_y, acc_z = accel.acceleration
    except Exception as exc:
        print(f"Error reading accelerometer: {exc}", file=sys.stderr)
        return None, None
    return (mag_x, mag_y, mag_z), (acc_x, acc_y, acc_z)


def _safe_read_adc_all(adc, pins):
    """Read all ADC channels; return None on any error."""
    try:
        return tuple(adc.read_voltage(ch) for ch in ADC_CHANNELS)
    except Exception as exc:
        print(f"Error reading ADC channels: {exc}", file=sys.stderr)
        return None


def _calculate_angles(mag, acc):
    """Compute XZ, YZ inclination angles and compass heading in degrees."""
    mag_x, mag_y, mag_z = mag
    acc_x, acc_y, acc_z = acc

    try:
        inclination_xz = math.degrees(math.atan2(acc_z, math.sqrt(acc_x * acc_x + acc_y * acc_y)))
        inclination_yz = math.degrees(math.atan2(acc_x, math.sqrt(acc_y * acc_y + acc_z * acc_z)))
    except Exception as exc:
        print(f"Error calculating inclination angles: {exc}", file=sys.stderr)
        inclination_xz = inclination_yz = None

    try:
        heading = math.degrees(math.atan2(mag_y, mag_x))
        if heading < 0:
            heading += 360.0
    except Exception as exc:
        print(f"Error calculating compass heading: {exc}", file=sys.stderr)
        heading = None

    return inclination_xz, inclination_yz, heading


def _calculate_efficiency(sample_buffer):
    """Perform FFT-based validation and return efficiency percentage."""
    try:
        fft_data = np.fft.fft(sample_buffer)
        power_spectrum = np.abs(fft_data)
        total_energy = np.sum(power_spectrum)
        if total_energy == 0:
            return 0.0
        return (power_spectrum[0] + power_spectrum[1]) / total_energy * 100.0
    except Exception as exc:
        print(f"Error calculating efficiency: {exc}", file=sys.stderr)
        return 0.0


def _set_motor_speed(pi, duty_cycle):
    """Set motor PWM duty cycle (0-255) from ADC channel 0 value."""
    duty = int(duty_cycle) if duty_cycle is not None else 0
    duty = max(0, min(255, duty))
    try:
        pi.hardware_PWM(MOTOR_STEP_PIN, PWM_FREQUENCY, duty * 10000)
    except Exception as exc:
        print(f"Error setting motor speed: {exc}", file=sys.stderr)


def main():
    global _pi

    # --- Initialize pigpio -------------------------------------------------
    try:
        _pi = pigpio.pi()
        if not _pi.connected:
            print("Error: pigpio daemon not connected. Is pigpiod running?", file=sys.stderr)
            sys.exit(1)
    except Exception as exc:
        print(f"Error initializing pigpio: {exc}", file=sys.stderr)
        sys.exit(1)

    # --- Configure motor pins ---------------------------------------------
    try:
        _pi.set_mode(MOTOR_DIR_PIN, pigpio.OUTPUT)
        _pi.set_mode(MOTOR_STEP_PIN, pigpio.OUTPUT)
        for pin in MOTOR_RESOLUTION_PINS:
            _pi.set_mode(pin, pigpio.OUTPUT)
        _pi.write(MOTOR_DIR_PIN, 0)
        _pi.write(MOTOR_RESOLUTION_PINS, (0, 0))
    except Exception as exc:
        print(f"Error configuring motor pins: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Initialize sensors ------------------------------------------------
    i2c = _safe_init_sensor("I2C bus", lambda: None)
    if i2c is None:
        _cleanup()
        sys.exit(1)

    mag = _safe_init_sensor("LSM303DLH magnetometer", LSM303DLH_Mag, i2c=i2c)
    accel = _safe_init_sensor("LSM303 accelerometer", LSM303_Accel, i2c=i2c)
    adc = _safe_init_sensor("ADS1015 ADC", ADS1015, address=0x48, i2c=i2c)

    if mag is None or accel is None or adc is None:
        _cleanup()
        sys.exit(1)

    # --- Main loop ---------------------------------------------------------
    sample_buffer = []
    try:
        while _running:
            # Read ADC channels
            adc_values = _safe_read_adc_all(adc, ADC_CHANNELS)
            if adc_values is None:
                time.sleep(SAMPLE_INTERVAL)
                continue

            # Append to sample buffer
            sample_buffer.append(adc_values[0])
            if len(sample_buffer) >= SAMPLE_COUNT:
                efficiency = _calculate_efficiency(sample_buffer)
                print(f"Efficiency: {efficiency:.2f}%")

                # Read sensors
                mag_data, acc_data = _safe_read_accel(mag, accel)
                if mag_data is None or acc_data is None:
                    time.sleep(SAMPLE_INTERVAL)
                    continue

                inclination_xz, inclination_yz, heading = _calculate_angles(mag_data, acc_data)
                print(f"Inclination XZ: {inclination_xz:.2f} deg, "
                      f"Inclination YZ: {inclination_yz:.2f} deg, "
                      f"Heading: {heading:.2f} deg")

                sample_buffer = []

            # Set motor speed from ADC channel 0
            _set_motor_speed(_pi, adc_values[0])

            time.sleep(SAMPLE_INTERVAL)

    except Exception as exc:
        print(f"Fatal error in main loop: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

