import io
import time
import json
import signal
import sys
import logging
from typing import Optional, Tuple

import numpy as np
from PIL import Image

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from gpiozero import OutputDevice
except ImportError:
    OutputDevice = None

try:
    from tflite_runtime.interpreter import Interpreter
except ImportError:
    Interpreter = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class BirdDetector:
    """Detects birds in images using TensorFlow Lite."""

    def __init__(self, model_path: str, label_path: str, threshold: float = 0.7):
        if Interpreter is None:
            raise RuntimeError("tflite_runtime is not installed.")
        self.interpreter = Interpreter(model_path=model_path)
        self.interpreter.allocate_tensors()
        self.threshold = threshold
        self.input_details = self.interpreter.get_input_details()
        self.output_details = self.interpreter.get_output_details()
        self.input_size = tuple(self.input_details[0]['shape'][1:3])

        with open(label_path, 'r') as f:
            self.labels = [line.strip() for line in f if line.strip()]

    def preprocess_image(self, image: Image.Image) -> np.ndarray:
        img = image.resize(self.input_size, Image.Resize.BILINEAR)
        img = img.convert('RGB')
        img = np.array(img, dtype=np.float32)
        img = (img - 127.5) / 127.5
        img = np.expand_dims(img, axis=0)
        return img

    def predict(self, image: Image.Image) -> Tuple[float, str]:
        img = self.preprocess_image(image)
        self.interpreter.set_tensor(self.input_details[0]['index'], img)
        self.interpreter.invoke()
        output_data = self.interpreter.get_tensor(self.output_details[0]['index'])
        results = np.squeeze(output_data)
        top_k = results.argsort()[-5:][::-1]
        for i in top_k:
            if results[i] >= self.threshold:
                return float(results[i]), self.labels[i]
        return 0.0, None


class BirdFeeder:
    """Controls a bird feeder door via GPIO."""

    def __init__(self, door_pin: int):
        if OutputDevice is None:
            raise RuntimeError("gpiozero is not installed.")
        self.door = OutputDevice(door_pin, active_high=True, initial_value=False)
        self.door_pin = door_pin

    def open_door(self):
        self.door.on()
        logger.info("Bird feeder door opened.")

    def close_door(self):
        self.door.off()
        logger.info("Bird feeder door closed.")

    def cleanup(self):
        self.close_door()
        self.door.close()


def indicate_bird(led_pin: int):
    """Indicate a bird sighting by blinking an LED."""
    if OutputDevice is None:
        logger.warning("gpiozero not installed; LED indication skipped.")
        return
    led = OutputDevice(led_pin, active_high=True, initial_value=False)
    try:
        led.on()
        time.sleep(1)
    finally:
        led.off()
        led.close()


def load_config(config_path: str) -> dict:
    try:
        with open(config_path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        logger.warning(f"Config file not found: {config_path}. Using defaults.")
        return {}
    except json.JSONDecodeError as e:
        logger.error(f"Invalid JSON in config file: {e}. Using defaults.")
        return {}


def signal_handler(signum, frame, camera: Optional['Picamera2'] = None, feeder: Optional['BirdFeeder'] = None):
    logger.info(f"Signal {signum} received; shutting down.")
    if feeder is not None:
        feeder.cleanup()
    if camera is not None:
        camera.stop()
        camera.close()
    sys.exit(0)


def main():
    config = load_config('config.json')
    led_pin = config.get('gpio_led', 17)
    door_pin = config.get('gpio_door_control', None)
    model_path = config.get('model_path', 'model.tflite')
    label_path = config.get('label_path', 'labels.txt')

    if Picamera2 is None:
        logger.error("picamera2 is not installed.")
        return

    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(
            main={"size": (224, 224), "format": "RGB888"}
        ))
        camera.start()
    except Exception as e:
        logger.error(f"Failed to initialize camera: {e}")
        return

    try:
        detector = BirdDetector(model_path, label_path)
    except Exception as e:
        logger.error(f"Failed to load model: {e}")
        camera.stop()
        camera.close()
        return

    feeder = None
    if door_pin is not None:
        try:
            feeder = BirdFeeder(door_pin)
        except Exception as e:
            logger.error(f"Failed to initialize feeder: {e}")
            camera.stop()
            camera.close()
            return

    signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, camera, feeder))
    signal.signal(signal.SIGTERM, lambda s, f: signal_handler(s, f, camera, feeder))

    try:
        while True:
            try:
                frame = camera.capture_array()
                if frame is None:
                    logger.warning("Captured empty frame.")
                    time.sleep(0.1)
                    continue
                image = Image.fromarray(frame)
                confidence, label = detector.predict(image)
                if label == 'bird':
                    logger.info(f"Bird detected with confidence {confidence:.2f}")
                    indicate_bird(led_pin)
                    if feeder is not None:
                        feeder.open_door()
                        time.sleep(2)
                        feeder.close_door()
                time.sleep(0.1)
            except Exception as e:
                logger.error(f"Error during processing: {e}")
                time.sleep(0.1)
    finally:
        if feeder is not None:
            feeder.cleanup()
        camera.stop()
        camera.close()


if __name__ == '__main__':
    main()

