import io
import time
import json
import signal
import threading
import logging
import queue
import cv2
import numpy as np
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DEFAULT_CONFIG = {
    "camera_resolution": [640, 480],
    "camera_framerate": 30,
    "motion_detection_threshold": 25,
    "queue_size_limit": 10,
    "gpio_pin": 17,
    "led_activation_duration": 2,
    "camera_warmup_time": 2
}

class MotionDetectionSystem:
    def __init__(self, config_path):
        self.config = self._load_config(config_path)
        self.camera_resolution = tuple(self.config["camera_resolution"])
        self.camera_framerate = self.config["camera_framerate"]
        self.motion_detection_threshold = self.config["motion_detection_threshold"]
        self.queue_size_limit = self.config["queue_size_limit"]
        self.gpio_pin = self.config["gpio_pin"]
        self.led_activation_duration = self.config["led_activation_duration"]
        self.camera_warmup_time = self.config["camera_warmup_time"]
        self.frame_queue = queue.Queue(maxsize=self.queue_size_limit)
        self.alert_triggered = False
        self.alert_timer = None
        self.cap = None
        self._running = True

    def _load_config(self, config_path):
        try:
            with open(config_path, "r") as f:
                config = json.load(f)
            required_keys = ["camera_resolution", "camera_framerate", "motion_detection_threshold", "queue_size_limit", "gpio_pin", "led_activation_duration", "camera_warmup_time"]
            for key in required_keys:
                if key not in config:
                    raise KeyError(f"Missing required config key: {key}")
            return config
        except (FileNotFoundError, json.JSONDecodeError, KeyError) as e:
            logger.error(f"Error loading configuration: {e}. Using default configuration.")
            return DEFAULT_CONFIG.copy()

    def initialize_camera(self):
        try:
            self.cap = cv2.VideoCapture(0)
            if not self.cap.isOpened():
                raise RuntimeError("Could not open camera.")
            self.cap.set(cv2.CAP_PROP_FRAME_WIDTH, self.camera_resolution[0])
            self.cap.set(cv2.CAP_PROP_FRAME_HEIGHT, self.camera_resolution[1])
            self.cap.set(cv2.CAP_PROP_FPS, self.camera_framerate)
            time.sleep(self.camera_warmup_time)
            logger.info("Camera initialized successfully.")
        except Exception as e:
            logger.error(f"Error initializing camera: {e}")
            raise

    def capture_and_process_frames(self):
        try:
            while self._running:
                ret, frame = self.cap.read()
                if not ret:
                    logger.error("Failed to capture frame from camera.")
                    break
                if self.frame_queue.full():
                    try:
                        self.frame_queue.get_nowait()
                    except queue.Empty:
                        pass
                self.frame_queue.put(frame, timeout=1)
                time.sleep(0.1)
        except queue.Full:
            logger.warning("Frame queue is full. Dropping frame.")
        except Exception as e:
            logger.error(f"Error capturing and processing frames: {e}")

    def detect_motion(self):
        try:
            while self._running:
                try:
                    frame = self.frame_queue.get(timeout=1)
                except queue.Empty:
                    continue
                gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
                gray = cv2.GaussianBlur(gray, (21, 21), 0)
                if self.previous_frame is None:
                    self.previous_frame = gray
                    continue
                frame_delta = cv2.absdiff(self.previous_frame, gray)
                thresh = cv2.threshold(frame_delta, self.motion_detection_threshold, 255, cv2.THRESH_BINARY)[1]
                thresh = cv2.dilate(thresh, None, iterations=2)
                contours, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
                for contour in contours:
                    if cv2.contourArea(contour) < 500:
                        continue
                    self.trigger_alert()
                    break
                self.previous_frame = gray
        except Exception as e:
            logger.error(f"Error detecting motion: {e}")

    def trigger_alert(self):
        if self.alert_triggered:
            return
        self.alert_triggered = True
        logger.info("Motion detected! Triggering alert.")
        try:
            GPIO.output(self.gpio_pin, GPIO.HIGH)
            self.alert_timer = threading.Timer(self.led_activation_duration, self.stop_alert)
            self.alert_timer.daemon = True
            self.alert_timer.start()
        except Exception as e:
            logger.error(f"Error triggering alert: {e}")

    def stop_alert(self):
        try:
            GPIO.output(self.gpio_pin, GPIO.LOW)
            self.alert_triggered = False
            logger.info("Alert stopped.")
        except Exception as e:
            logger.error(f"Error stopping alert: {e}")

    def run(self):
        try:
            self.initialize_camera()
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pin, GPIO.OUT, initial=GPIO.LOW)
            self.previous_frame = None
            capture_thread = threading.Thread(target=self.capture_and_process_frames)
            detect_thread = threading.Thread(target=self.detect_motion)
            capture_thread.daemon = True
            detect_thread.daemon = True
            capture_thread.start()
            detect_thread.start()
            while self._running:
                time.sleep(1)
        except KeyboardInterrupt:
            logger.info("Exiting program.")
        except Exception as e:
            logger.error(f"An unexpected error occurred: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        self._running = False
        if self.cap is not None:
            self.cap.release()
        cv2.destroyAllWindows()
        if self.alert_timer is not None and self.alert_timer.is_alive():
            self.alert_timer.cancel()
        GPIO.cleanup()
        logger.info("Resources cleaned up.")

def main():
    signal.signal(signal.SIGINT, signal.default_int_handler)
    system = MotionDetectionSystem("config.json")
    system.run()

if __name__ == "__main__":
    main()

