import cv2
import signal
import sys
import time
import logging
import numpy as np

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18

CASCADE_PATH = '/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml'
FRAME_WIDTH = 32

running = True
camera = None
window_created = False
servo = None
led = None
button = None

def cleanup():
    global camera, window_created, servo, led, button
    if camera is not None:
        try:
            camera.release()
        except Exception:
            pass
        camera = None
    if window_created:
        try:
            cv2.destroyAllWindows()
        except Exception:
            pass
        window_created = False
    if servo is not None:
        try:
            servo.stop()
        except Exception:
            pass
        servo = None
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
        button = None

def signal_handler(sig, frame):
    global running
    running = False

def main():
    global camera, window_created, servo, led, button

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        led = LED(LED_PIN)
        button = Button(BUTTON_PIN, pull_up=True)
        servo = Servo(SERVO_PIN)
    except Exception as e:
        logging.warning(f"GPIO initialization failed (LED/Btn/Servo): {e}. Continuing without GPIO control.")

    try:
        cascade = cv2.CascadeClassifier(CASCADE_PATH)
        if cascade.empty():
            raise IOError(f"Failed to load cascade classifier from {CASCADE_PATH}")
    except Exception as e:
        logging.error(f"Error loading cascade classifier: {e}")
        cleanup()
        return

    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise IOError("Cannot open webcam /dev/video0")
    except Exception as e:
        logging.error(f"Error opening camera: {e}")
        cleanup()
        return

    try:
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, FRAME_WIDTH)
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, FRAME_WIDTH)
    except Exception as e:
        logging.warning(f"Could not set frame dimensions: {e}")

    try:
        cv2.namedWindow("Human Detection", cv2.WINDOW_NORMAL)
        window_created = True
    except Exception as e:
        logging.warning(f"Could not create display window: {e}")
        window_created = False

    servo_angle = 90
    try:
        servo.angle(servo_angle)
        time.sleep(0.02)
    except Exception as e:
        logging.warning(f"Could not initialize servo: {e}")

    try:
        while running:
            ret, frame = camera.read()
            if not ret:
                logging.error("Failed to grab frame")
                break

            try:
                gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            except Exception as e:
                logging.error(f"Error converting frame to grayscale: {e}")
                break

            try:
                faces = cascade.detectMultiScale(gray, 1.3, 5)
            except Exception as e:
                logging.error(f"Error detecting faces: {e}")
                break

            if len(faces) > 0:
                if led is not None:
                    try:
                        led.on()
                    except Exception as e:
                        logging.warning(f"Error turning LED on: {e}")
                if servo is not None:
                    try:
                        center_x = faces[0][0] + faces[0][2] / 2
                        frame_width = frame.shape[1]
                        if center_x < frame_width / 2:
                            servo_angle = min(180, servo_angle + 20)
                        else:
                            servo_angle = max(0, servo_angle - 20)
                        servo.angle(servo_angle)
                        time.sleep(0.02)
                    except Exception as e:
                        logging.warning(f"Error controlling servo: {e}")
            else:
                if led is not None:
                    try:
                        led.off()
                    except Exception as e:
                        logging.warning(f"Error turning LED off: {e}")

            if window_created:
                try:
                    for (x, y, w, h) in faces:
                        cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
                    cv2.imshow("Human Detection", frame)
                    if cv2.waitKey(1) & 0xFF == ord('q'):
                        running = False
                except Exception as e:
                    logging.error(f"Error displaying frame: {e}")
                    break
            else:
                time.sleep(0.01)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

