import time
import datetime
import sqlite3
import logging
import signal
import sys
import os
from typing import Optional, Tuple, Dict, Any

try:
    import smbus2
except ImportError:
    smbus2 = None

try:
    import adafruit_bmp280
except ImportError:
    adafruit_bmp280 = None

try:
    import adafruit_bme280
except ImportError:
    adafruit_bme280 = None

try:
    import adafruit_ms8607
except ImportError:
    adafruit_ms8607 = None

CONFIG_FILE = "config.txt"
DATABASE_FILE = "wildlife_data.db"
ERROR_LOG_FILE = "error.log"
DEFAULT_SAMPLING_INTERVAL = 60  # seconds (only used for MS8607; BMP/BME use it as-is)

running = True
db_connection = None


def signal_handler(signum, frame):
    global running
    running = False


def setup_logging():
    logging.basicConfig(
        filename=ERROR_LOG_FILE,
        level=logging.ERROR,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def load_config(config_file: str) -> Optional[Dict[str, Any]]:
    config: Dict[str, Any] = {
        "Sensor1_Type": None,
        "Sensor1_Address": None,
        "Sensor1_ID": None,
        "Sensor2_Type": None,
        "Sensor2_Address": None,
        "Sensor2_ID": None,
        "Sensor3_Type": None,
        "Sensor3_Address": None,
        "Sensor3_ID": None,
        "Sampling_Interval_Seconds": DEFAULT_SAMPLING_INTERVAL,
    }
    try:
        with open(config_file, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                value = value.strip()
                if key in config:
                    config[key] = value
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
    except Exception as e:
        logging.error(f"Error reading configuration file: {e}")
    return config


def initialize_database(db_file: str) -> Optional[sqlite3.Connection]:
    global db_connection
    try:
        db_connection = sqlite3.connect(db_file)
        cursor = db_connection.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id TEXT,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        """)
        db_connection.commit()
        return db_connection
    except sqlite3.Error as e:
        logging.error(f"Database initialization error: {e}")
        return None


def initialize_sensor(sensor_type: str, address: str, bus: Optional[smbus2.SMBus]) -> Optional[Any]:
    try:
        address_int = int(address, 16)
    except ValueError:
        logging.error(f"Invalid I2C address: {address}")
        return None

    if sensor_type == "BMP280":
        if adafruit_bmp280 is None:
            logging.error("adafruit_bmp280 library not installed")
            return None
        try:
            return adafruit_bmp280.Adafruit_BMP280_I2C(bus, address=address_int)
        except Exception as e:
            logging.error(f"BMP280 initialization error at 0x{address_int:02X}: {e}")
            return None
    elif sensor_type == "BME280":
        if adafruit_bme280 is None:
            logging.error("adafruit_bme280 library not installed")
            return None
        try:
            return adafruit_bme280.Adafruit_BME280_I2C(bus, address=address_int)
        except Exception as e:
            logging.error(f"BME280 initialization error at 0x{address_int:02X}: {e}")
            return None
    elif sensor_type == "MS8607":
        if adafruit_ms8607 is None:
            logging.error("adafruit_ms8607 library not installed")
            return None
        try:
            return adafruit_ms8607.MS8607(bus, address=address_int)
        except Exception as e:
            logging.error(f"MS8607 initialization error at 0x{address_int:02X}: {e}")
            return None
    else:
        logging.error(f"Invalid sensor type: {sensor_type}")
        return None


def read_sensor_data(sensor: Any, sensor_type: str) -> Tuple[Optional[float], Optional[float], Optional[float]]:
    try:
        if sensor_type == "BMP280":
            return sensor.pressure, sensor.temperature, None
        elif sensor_type == "BME280":
            return sensor.pressure, sensor.temperature, sensor.humidity
        elif sensor_type == "MS8607":
            return sensor.pressure, sensor.temperature, sensor.humidity
        else:
            return None, None, None
    except Exception as e:
        logging.error(f"Error reading sensor data: {e}")
        return None, None, None


def validate_data(pressure: Optional[float], temperature: Optional[float], humidity: Optional[float], sensor_type: str) -> bool:
    if pressure is not None and not (70000 <= pressure <= 110000):
        logging.warning(f"Invalid pressure reading: {pressure} Pa for {sensor_type}")
        return False
    if temperature is not None and not (-20 <= temperature <= 50):
        logging.warning(f"Invalid temperature reading: {temperature} C for {sensor_type}")
        return False
    if humidity is not None and not (0 <= humidity <= 100):
        logging.warning(f"Invalid humidity reading: {humidity} % for {sensor_type}")
        return False
    return True


def store_data(db_connection: sqlite3.Connection, timestamp: str, sensor_type: str, sensor_id: str, pressure: Optional[float], temperature: Optional[float], humidity: Optional[float]) -> None:
    try:
        cursor = db_connection.cursor()
        cursor.execute("""
            INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent)
            VALUES (?, ?, ?, ?, ?, ?)
        """, (timestamp, sensor_type, sensor_id, pressure, temperature, humidity))
        db_connection.commit()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")


def main():
    global running, db_connection

    setup_logging()
    signal.signal(signal.SIGINT, signal_handler)

    config = load_config(CONFIG_FILE)
    if not any(config.get(k) for k in ["Sensor1_Type", "Sensor2_Type", "Sensor3_Type"]):
        logging.error("No sensors configured. Exiting.")
        return

    db_connection = initialize_database(DATABASE_FILE)
    if db_connection is None:
        return

    try:
        bus = smbus2.SMBus(1)
    except Exception as e:
        logging.error(f"Failed to initialize I2C bus 1: {e}")
        db_connection.close()
        return

    sensors = []
    for i in range(1, 4):
        sensor_type = config.get(f"Sensor{i}_Type")
        if not sensor_type:
            continue
        address = config.get(f"Sensor{i}_Address")
        sensor_id = config.get(f"Sensor{i}_ID")
        if not address or not sensor_id:
            logging.error(f"Sensor {i} missing address or ID in config.")
            continue
        sensor = initialize_sensor(sensor_type, address, bus)
        if sensor:
            sensors.append((sensor_type, sensor, sensor_id))

    if not sensors:
        logging.error("No sensors initialized. Exiting.")
        db_connection.close()
        return

    sampling_interval = int(config.get("Sampling_Interval_Seconds", DEFAULT_SAMPLING_INTERVAL))
    if sampling_interval <= 0:
        sampling_interval = DEFAULT_SAMPLING_INTERVAL

    try:
        while running:
            for sensor_type, sensor, sensor_id in sensors:
                pressure, temperature, humidity = read_sensor_data(sensor, sensor_type)
                if validate_data(pressure, temperature, humidity, sensor_type):
                    timestamp = datetime.datetime.now().isoformat()
                    store_data(db_connection, timestamp, sensor_type, sensor_id, pressure, temperature, humidity)
            for _ in range(sampling_interval):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        if db_connection:
            db_connection.close()
        if bus:
            bus.close()
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

