import smbus
import RPi.GPIO as GPIO
import time
import signal
import sys

# I2C configuration
I2C_BUS = 1
PCF8574_ADDR = 0x27

# GPIO configuration
INT_PIN = 17

# PCF8574 bit layout: bits 0-7 correspond to sensors 0-7, active-low
SENSOR_MASK = 0xFF

# Global flag for the interrupt handler
obstacle_detected = False

# Initialize I2C bus
try:
    bus = smbus.SMBus(I2C_BUS)
except Exception as e:
    print(f"Error initializing I2C bus {I2C_BUS}: {e}")
    sys.exit(1)

# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(INT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def read_proximity_sensors():
    """Read all eight proximity sensors from the PCF8574 and return a byte value."""
    try:
        return bus.read_byte_data(PCF8574_ADDR, 0)
    except Exception as e:
        print(f"I2C read error: {e}")
        return None

def handle_interrupt(channel):
    """Interrupt handler for falling edge on INT_PIN."""
    global obstacle_detected
    obstacle_detected = True

# Register interrupt callback
GPIO.add_event_detect(INT_PIN, GPIO.FALLING, callback=handle_interrupt, bouncetime=50)

def cleanup():
    """Clean up GPIO and I2C resources."""
    GPIO.remove_event_detect(INT_PIN)
    GPIO.cleanup()
    try:
        bus.close()
    except Exception:
        pass

def main():
    try:
        while True:
            if obstacle_detected:
                obstacle_detected = False
                proximity_value = read_proximity_sensors()
                if proximity_value is not None:
                    for i in range(8):
                        if proximity_value & (1 << i):
                            continue
                        print(f"Obstacle detected by sensor {i}")
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

