import time
import logging
import json
import signal
import sys
import os
from collections import deque

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

DEFAULT_CONFIG = {
    "offset": 0.0,
    "max_distance": 200.0,
    "low": 10.0,
    "high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

SENSOR_PINS = {
    1: {"trigger": 17, "echo": 18},
    2: {"trigger": 22, "echo": 23},
    3: {"trigger": 24, "echo": 25},
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        defaults = DEFAULT_CONFIG.copy()
        defaults.update(config)
        return defaults
    except FileNotFoundError:
        logging.warning("config.json not found; using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in config.json: {e}; using defaults.")
        return DEFAULT_CONFIG.copy()


def initialize_gpio():
    if GPIO is None:
        logging.warning("RPi.GPIO not available; running in mock mode.")
        return True
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in SENSOR_PINS.values():
            GPIO.setup(pin["trigger"], GPIO.OUT, initial=GPIO.LOW)
            GPIO.setup(pin["echo"], GPIO.IN)
        return True
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return False


def measure_distance(trigger_pin, echo_pin, max_distance):
    if GPIO is None:
        return max_distance
    try:
        GPIO.output(trigger_pin, GPIO.LOW)
        time.sleep(0.000002)
        GPIO.output(trigger_pin, GPIO.HIGH)
        time.sleep(0.00001)
        GPIO.output(trigger_pin, GPIO.LOW)

        timeout = time.time() + 0.05
        while GPIO.input(echo_pin) == 0:
            if time.time() > timeout:
                return None
        start_time = time.time()

        timeout = time.time() + 0.05
        while GPIO.input(echo_pin) == 1:
            if time.time() > timeout:
