import hardware

from math import ceil

try:
    from openface import training
except ImportError:
    print("Error: openface package not found. Install with: pip install openface")
    sys.exit(1)

try:
    from openface import align
except ImportError:
    print("Error: openface package not found. Install with: pip install openface")
    sys.exit(1)

try:
    from openface import nn
except ImportError:
    print("Error: openface package not found. Install with: pip install openface")
    sys.exit(1)

try:
    from openface import img_utils
except ImportError:
    print("Error: openface package not found. Install with: pip install openface")
    sys.exit(1)

try:
    import face_utils as ft
except ImportError:
    print("Error: face_utils module not found. Install with: pip install face_utils")
    sys.exit(1)

try:
    import camera_utils as cu
except ImportError:
    print("Error: camera_utils module not found. Install with: pip install camera_utils")
    sys.exit(1)

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup(camera=None):
    """Release camera and restore box to locked state."""
    if camera is not None and camera.isOpened():
        camera.release()
    try:
        hardware.Box.lock()
    except Exception:
        pass


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)

    camera = None
    try:
        # --- Initialize camera ---
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            print("Error: Could not open camera.")
            return

        # Set camera properties
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
        camera.set(cv2.CAP_PROP_FPS, 15)
        camera.set(cv2.CAP_PROP_FORMAT, cv2.VideoWriter_fourcc(*'XRGB'))

        # --- Load face recognition models ---
        try:
            detector = ft.new_detector(config.CASCADE_CLASS_PATH)
        except Exception as e:
            print(f"Error loading face detector: {e}")
            return

        try:
            if config.ALIGN_IMAGE_SIZE > 0:
                align_image_size = config.ALIGN_IMAGE_SIZE
            else:
                align_image_size = int(ceil(max(480, 640) / 8.0)) * 8
            align = training.get_aligner(
                'opencv',
                'Face',
                config.ALIGN_IMAGE_SIZE,
                config.ALIGN_IMAGE_SIZE,
            )
        except Exception as e:
            print(f"Error loading aligner: {e}")
            return

        try:
            net = nn.load_net(config.NET_FILE, config.TRAINING_FILE)
        except Exception as e:
            print(f"Error loading neural network: {e}")
            return

        # --- Initialize box state ---
        hardware.Box.lock()

        # --- Main loop ---
        while _running:
            try:
                # Check if the button is up (box is locked)
                if hardware.Box.is_button_up():
                    # Capture frame
                    ret, frame = camera.read()
                    if not ret or frame is None:
                        print("Warning: Failed to capture frame.")
                        time.sleep(0.1)
                        continue

                    # Detect faces
                    try:
                        bbs = detector.detect(frame, config.DETECTOR_THRESHOLD)
                    except Exception as e:
                        print(f"Warning: Face detection failed: {e}")
                        time.sleep(0.1)
                        continue

                    if len(bbs) > 0:
                        # Align and crop the first detected face
                        try:
                            cropped = cu.crop_bb(frame, align, bbs[0], config.ALIGN_IMAGE_SIZE)
                        except Exception as e:
                            print(f"Warning: Face alignment failed: {e}")
                            time.sleep(0.1)
                            continue

                        # Resize and convert to grayscale
                        try:
                            cropped = img_utils.resize(cropped, width=100)
                            gray = cv2.cvtColor(cropped, cv2.COLOR_BGR2GRAY)
                        except Exception as e:
                            print(f"Warning: Image processing failed: {e}")
                            time.sleep(0.1)
                            continue

                        # Predict identity
                        try:
                            l, conf = net.predict(gray, config.PREDICT_MARGIN)
                        except Exception as e:
                            print(f"Warning: Prediction failed: {e}")
                            time.sleep(0.1)
                            continue

                        # Unlock if recognized face and confidence is high enough
                        if l == config.POSITIVE_LABEL and config.POSITIVE_THRESHOLD > conf > 1500:
                            hardware.Box.unlock()
                    else:
                        # Re-lock if no face detected
                        hardware.Box.lock()
                else:
                    # Re-lock if button is down
                    hardware.Box.lock()

                time.sleep(0.1)

            except Exception as e:
                print(f"Error in main loop: {e}")
                time.sleep(0.1)

    finally:
        _cleanup(camera)


if __name__ == '__main__':
    main()

