import os
import time
import signal
import logging
import datetime
import threading
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received. Exiting gracefully...")

signal.signal(signal.SIGINT, signal_handler)

class CameraHandler:
    def __init__(self, config):
        self.config = config
        self.picam2 = None
        self.encoder = None
        self.output = None
        self.lock = threading.Lock()

    def initialize_camera(self):
        try:
            self.picam2 = Picamera2()
            # Configure for video mode with the specified resolution
            video_config = self.picam2.create_video_configuration(
                main={"size": (self.config['resolution_width'], self.config['resolution_height']), "format": "RGB888"}
            )
            self.picam2.configure(video_config)
            self.picam2.start()
            logging.info("CSI camera initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            return False

    def capture_frame(self):
        try:
            with self.lock:
                frame = self.picam2.capture_array()
            return frame
        except Exception as e:
            logging.error(f"Error capturing frame: {e}")
            return None

    def start_recording(self):
        try:
            self.encoder = H264Encoder()
            self.output = FileOutput(self.config['video_file_path'])
            self.picam2.start_recording(self.encoder, self.output)
            logging.info("Video recording started.")
        except Exception as e:
            logging.error(f"Error starting video recording: {e}")

    def stop_recording(self):
        try:
            if self.picam2:
                self.picam2.stop_recording()
                logging.info("Video recording stopped.")
        except Exception as e:
            logging.error(f"Error stopping video recording: {e}")

    def close(self):
        try:
            if self.picam2:
                self.picam2.stop()
                self.picam2.close()
                logging.info("Camera resources released.")
        except Exception as e:
            logging.error(f"Error closing camera: {e}")

class MotionDetector:
    def __init__(self, config):
        self.config = config
        self.previous_frame = None
        self.motion_detected = False
        self.motion_confirmation = False
        self.motion_confirmation_timer = None
        self.motion_confirmation_time = self.config['confirmation_delay']
        self.lock = threading.Lock()

    def detect_motion(self, current_frame):
        try:
            with self.lock:
                if current_frame is None:
                    return False

                if self.previous_frame is None:
                    self.previous_frame = current_frame.copy()
                    return False

                # Calculate the absolute difference between consecutive frames
                diff = np.abs(current_frame.astype(np.int16) - self.previous_frame.astype(np.int16))

                # Apply the motion threshold
                motion_mask = diff > self.config['motion_threshold']

                # Calculate the percentage of pixels that exceed the threshold
                percentage = np.mean(motion_mask) * 100

                # Check if the percentage exceeds the threshold
                if percentage > self.config['motion_threshold']:
                    self.motion_detected = True
                    self.motion_confirmation = False
                    self.start_confirmation_timer()
                    logging.info(f"Motion detected! Percentage of changed pixels: {percentage:.2f}%")
                    return True
                else:
                    self.motion_detected = False
                    return False

                self.previous_frame = current_frame.copy()
        except Exception as e:
            logging.error(f"Error detecting motion: {e}")
            return False

    def start_confirmation_timer(self):
        try:
            self.motion_confirmation = True
            self.motion_confirmation_timer = threading.Timer(self.motion_confirmation_time, self.confirmation_timeout)
            self.motion_confirmation_timer.daemon = True
            self.motion_confirmation_timer.start()
        except Exception as e:
            logging.error(f"Error starting confirmation timer: {e}")

    def confirmation_timeout(self):
        try:
            self.motion_confirmation = False
            logging.info("Motion confirmation timer expired.")
        except Exception as e:
            logging.error(f"Error in confirmation timeout: {e}")

class AlertManager:
    def __init__(self, config):
        self.config = config
        self.alert_sent = False
        self.alert_lock = threading.Lock()

    def check_temperature(self, temperature):
        try:
            with self.alert_lock:
                if temperature > self.config['temperature_threshold'] and not self.alert_sent:
                    logging.warning(f"High temperature alert! Temperature: {temperature:.2f}°C")
                    self.alert_sent = True
                    return True
                elif temperature <= self.config['temperature_threshold']:
                    self.alert_sent = False
                return False
        except Exception as e:
            logging.error(f"Error checking temperature: {e}")
            return False

    def check_motion(self):
        try:
            with self.alert_lock:
                if self.config['simulated_temperature']:
                    temperature = self.config['simulated_temperature']
                else:
                    try:
                        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
                            temperature = float(f.read()) / 1000.0
                    except (FileNotFoundError, IOError, ValueError) as e:
                        logging.error(f"Error reading CPU temperature: {e}")
                        temperature = 0.0

                if self.motion_detected and self.motion_confirmation and self.check_temperature(temperature):
                    timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
                    snapshot_filename = os.path.join(self.config['snapshot_dir'], f"{timestamp}.jpg")
                    logging.info(f"Motion detected and temperature is normal. Saving snapshot to {snapshot_filename}")
                    return snapshot_filename
                return None
        except Exception as e:
            logging.error(f"Error checking motion: {e}")
            return None

def load_config(config_file_path):
    config = {
        'resolution_width': 64,
        'resolution_height': 64,
        'roi_x1': 0,
        'roi_y1': 0,
        'roi_x2': 64,
        'roi_y2': 64,
        'motion_threshold': 1,
        'confirmation_delay': 2,
        'temperature_threshold': 50,
