import sys
import os
import signal
import time
import select
import threading

import cv2
import numpy as np
import playsound
from PIL import Image

import config
import face as f
import audio as a
import gpio as g

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_lock = threading.Lock()
_camera = None
_gpio = None
_audio = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _cleanup():
    """Release every hardware / resource handle we hold."""
    global _camera, _gpio, _audio
    if _camera is not None:
        try:
            _camera.release()
        except Exception:
            pass
        _camera = None
    if _gpio is not None:
        try:
            _gpio.cleanup()
        except Exception:
            pass
        _gpio = None
    if _audio is not None:
        try:
            _audio.quit()
        except Exception:
            pass
        _audio = None


def _lock_door():
    """Lock the door (set BCM 17 HIGH)."""
    with _lock:
        if _gpio is not None:
            try:
                _gpio.output(g.LOCK_PIN, g.HIGH)
            except Exception:
                pass


def _unlock_door():
    """Unlock the door (set BCM 17 LOW)."""
    with _lock:
        if _gpio is not None:
            try:
                _gpio.output(g.LOCK_PIN, g.LOW)
            except Exception:
                pass


def _button_pressed():
    """Return True if BCM 5 is LOW (button pressed to GND)."""
    with _lock:
        if _gpio is not None:
            try:
                return _gpio.input(g.BUTTON_PIN) == g.LOW
            except Exception:
                return False
    return False


def _process_image(image, model_path):
    """Detect a single face, crop & resize, then run recognition.

    Returns (label, confidence) or (None, None) on failure.
    """
    if not os.path.isfile(model_path):
        print(f"Error: model file not found: {model_path}", file=sys.stderr)
        return None, None

    try:
        face_model = f.FaceModel(model_path)
    except Exception as exc:
        print(f"Error loading face model: {exc}", file=sys.stderr)
        return None, None

    try:
        gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    except cv2.error as exc:
        print(f"Error converting image to grayscale: {exc}", file=sys.stderr)
        return None, None

    try:
        face_coords = f.detect_single(gray_image)
    except Exception as exc:
        print(f"Error detecting face: {exc}", file=sys.stderr)
        return None, None

    if face_coords is None:
        return None, None

    x, y, w, h = face_coords
    cropped = f.crop(gray_image, x, y, w, h)
    resized = f.resize(cropped)

    try:
        label, confidence = face_model.predict(resized)
    except Exception as exc:
        print(f"Error during face recognition: {exc}", file=sys.stderr)
        return None, None

    return label, confidence


def _play_audio(channel):
    """Play the sound on the given audio channel (0-3)."""
    if _audio is not None:
        try:
            _audio.play(channel)
        except Exception as exc:
            print(f"Error playing audio channel {channel}: {exc}", file=sys.stderr)


def _handle_input():
    """Non-blocking check for 'l' on stdin (thread-safe)."""
    try:
        rlist, _, _ = select.select([sys.stdin], [], [], 0.0)
        if rlist:
            line = sys.stdin.readline().strip()
            if line == 'l':
                _lock_door()
                print("Door locked.")
    except Exception:
        pass


def main():
    global _camera, _gpio, _audio

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- Initialize camera -------------------------------------------------
    try:
        _camera = config.CAMERA_GETTER()
    except Exception as exc:
        print(f"Error initializing camera: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Initialize GPIO (button on BCM 5, lock on BCM 17) -----------------
    try:
        _gpio = g.GPIO()
        _gpio.setup(g.BUTTON_PIN, g.INPUT, pull_up_down=g.PUD_UP)
        _gpio.setup(g.LOCK_PIN, g.OUT)
        _lock_door()
    except Exception as exc:
        print(f"Error initializing GPIO: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Initialize audio --------------------------------------------------
    try:
        _audio = a.Audio()
        _audio.init(48000, -16, 1, 1024)
    except Exception as exc:
        print(f"Error initializing audio: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Main loop ----------------------------------------------------------
    print("Running. Press button (BCM 5) to trigger recognition, "
          "'l' + Enter to lock the door, or Ctrl-C to exit.")

    try:
        while _running:
            _handle_input()

            if _button_pressed():
                print("Button pressed — looking for face...")

                try:
                    image = _camera.read()
                except Exception as exc:
                    print(f"Error reading from camera: {exc}", file=sys.stderr)
                    _play_audio(a.LATER_CHANNEL)
                    time.sleep(0.1)
                    continue

                if image is None or image.size == 0:
                    print("Error: empty frame from camera.", file=sys.stderr)
                    _play_audio(a.LATER_CHANNEL)
                    time.sleep(0.1)
                    continue

                label, confidence = _process_image(image, config.TRAINING_FILE)

                if label is None or confidence is None:
                    print("Face recognition failed.")
                    _play_audio(a.LATER_CHANNEL)
                    time.sleep(0.1)
                    continue

                print(f"Predicted {label} with confidence {confidence:.2f}")

                if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                    print("Face recognized! Unlocking door.")
                    _unlock_door()
                    _play_audio(a.WELCOME_CHANNEL)
                else:
                    print("Face not recognized.")
                    _play_audio(a.LATER_CHANNEL)
                    _lock_door()
                    _play_audio(a.WAIT_CHANNEL)

            time.sleep(0.1)

    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        _cleanup()
        print("Exiting.")


if __name__ == "__main__":
    main()

