import signal
import sys
import time
import boto3
from botocore.exceptions import ClientError, BotoCoreError

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

COLLECTION_ID = "home"
IMAGE_PATH = "image.jpg"
SIMILARITY_THRESHOLD = 85
WARMUP_SECONDS = 2

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def initialize_rekognition_client():
    try:
        return boto3.client("rekognition")
    except (BotoCoreError, ClientError) as e:
        print(f"Error initializing Rekognition client: {e}", file=sys.stderr)
        return None


def search_face(rekognition_client, image_path):
    try:
        with open(image_path, "rb") as image_file:
            image_bytes = image_file.read()
    except OSError as e:
        print(f"Error reading image file '{image_path}': {e}", file=sys.stderr)
        return None

    try:
        response = rekognition_client.search_faces_by_image(
            CollectionId=COLLECTION_ID,
            Image={"Bytes": image_bytes},
            MaxFaces=1,
            FaceMatchThreshold=SIMILARITY_THRESHOLD,
        )
        return response
    except ClientError as e:
        print(f"Rekognition ClientError searching for face: {e}", file=sys.stderr)
        return None
