import asyncio
import logging
import signal
import sys
import threading
from typing import Callable, Optional

import cv2
import numpy as np
import websockets

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)


class WebSocketHandler:
    """Manages WebSocket connections and broadcasts data."""

    def __init__(self):
        self._connections: set[websockets.WebSocketServerProtocol] = set()

    def has_connections(self) -> bool:
        return bool(self._connections)

    def register(self, websocket: websockets.WebSocketServerProtocol) -> None:
        self._connections.add(websocket)

    def unregister(self, websocket: websockets.WebSocketServerProtocol) -> None:
        self._connections.discard(websocket)

    def broadcast(self, data: bytes) -> None:
        """Broadcasts data to all connected WebSocket clients."""
        for ws in self._connections:
            try:
                ws.send(data)
            except websockets.exceptions.ConnectionClosed:
                logger.warning("WebSocket connection closed unexpectedly.")
                self._connections.discard(ws)
            except Exception as e:
                logger.error(f"Error broadcasting to WebSocket: {e}")

    def close_all(self) -> None:
        for ws in list(self._connections):
            try:
                ws.close()
            except Exception as e:
                logger.error(f"Error closing WebSocket: {e}")
        self._connections.clear()


class MotionDetector:
    """Detects motion between consecutive frames using NumPy frame arrays."""

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], bool]):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self._detect_motion = detect_motion_function

    def detect(self, prev_frame: np.ndarray, curr_frame: np.ndarray) -> bool:
        if prev_frame is None or curr_frame is None:
            logger.warning("Motion detection skipped: received None frame.")
            return False
        try:
            return self._detect_motion(prev_frame, curr_frame)
        except Exception as e:
            logger.error(f"Error during motion detection: {e}")
            return False


class CameraStream:
    """Streams camera frames to WebSocket clients with motion detection."""

    def __init__(
        self,
        camera_index: int = 0,
        frame_rate: int = 10,
        resolution: tuple[int, int] = (640, 480),
        detect_motion_function: Optional[Callable[[np.ndarray, np.ndarray], bool]] = None,
        motion_detector: Optional[MotionDetector] = None,
        websocket_handler: Optional[WebSocketHandler] = None,
    ):
        if not isinstance(camera_index, int) or camera_index < 0:
            raise ValueError("camera_index must be a non-negative integer.")
        if not isinstance(frame_rate, int) or frame_rate <= 0:
            raise ValueError("frame_rate must be a positive integer.")
        if not (isinstance(resolution, tuple) and len(resolution) == 2):
            raise ValueError("resolution must be a tuple of two integers.")
        if resolution[0] <= 0 or resolution[1] <= 0:
            raise ValueError("resolution dimensions must be positive.")

        self.camera_index = camera_index
        self.frame_rate = frame_rate
        self.resolution = resolution
        self.detect_motion = motion_detector or MotionDetector(detect_motion_function or self._default_motion_detection)
        self.websocket_handler = websocket_handler or WebSocketHandler()
        self._camera: Optional[cv2.VideoCapture] = None
        self._frame_lock = threading.Lock()
        self._stop_event = threading.Event()
        self._frame: Optional[np.ndarray] = None
        self._prev_frame: Optional[np.ndarray] = None
        self._frame_count = 0
        self._frame_delay = 1.0 / self.frame_rate

    def _default_motion_detection(self, prev_frame: np.ndarray, curr_frame: np.ndarray) -> bool:
        if prev_frame is None or curr_frame is None:
            return False
        try:
            diff = cv2.absdiff(prev_frame, curr_frame)
            gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
            blur = cv2.GaussianBlur(gray, (5, 5), 0)
            _, thresh = cv2.threshold(blur, 20, 255, cv2.THRESH_BINARY)
            contours, _ = cv2.findContours(thresh, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)
            return any(cv2.contourArea(c) > 500 for c in contours)
        except Exception as e:
            logger.error(f"Error in default motion detection: {e}")
            return False

    def _initialize_camera(self) -> bool:
        try:
            self._camera = cv2.VideoCapture(self.camera_index)
            if not self._camera.isOpened():
                logger.error(f"Could not open camera at index {self.camera_index}.")
                self._camera = None
                return False
            self._camera.set(cv2.CAP_PROP_FRAME_WIDTH, self.resolution[0])
            self._camera.set(cv2.CAP_PROP_FRAME_HEIGHT, self.resolution[1])
            actual_w = int(self._camera.get(cv2.CAP_PROP_FRAME_WIDTH))
            actual_h = int(self._camera.get(cv2.CAP_PROP_FRAME_HEIGHT))
            logger.info(f"Camera initialized: requested {self.resolution}, actual {actual_w}x{actual_h}")
            return True
        except Exception as e:
            logger.error(f"Error initializing camera: {e}")
            self._camera = None
            return False

    def _read_frame(self) -> None:
        if self._camera is None:
            return
        try:
            ret, frame = self._camera.read()
            if not ret or frame is None:
                logger.warning("Failed to read frame from camera.")
                return
            with self._frame_lock:
                self._frame = frame.copy()
        except Exception as e:
            logger.error(f"Error reading frame: {e}")

    async def _broadcast_frame(self) -> None:
        if self._frame is None:
            return
        try:
            if self.detect_motion.detect(self._prev_frame, self._frame):
                logger.info("Motion detected!")
            self._prev_frame = self._frame.copy()
            self._frame_count += 1
            if self._frame_count >= 64:
                self._frame_count = 0
                logger.info("Camera buffer reset.")
        except Exception as e:
            logger.error(f"Error in broadcast loop: {e}")
            return

    async def _stream_loop(self) -> None:
        if not self._initialize_camera():
            return
        try:
            while not self._stop_event.is_set():
                self._read_frame()
                if self.websocket_handler.has_connections():
                    await self._broadcast_frame()
                await asyncio.sleep(self._frame_delay)
        except asyncio.CancelledError:
            logger.info("Stream loop cancelled.")
        except Exception as e:
            logger.error(f"Error in stream loop: {e}")
        finally:
            self._cleanup()

    def _cleanup(self) -> None:
        if self._camera is not None:
            try:
                self._camera.release()
            except Exception as e:
                logger.error(f"Error releasing camera: {e}")
            finally:
                self._camera = None
        cv2.destroyAllWindows()
        logger.info("Camera resources released.")

    async def start_stream(self) -> None:
        await self._stream_loop()

    def stop_stream(self) -> None:
        self._stop_event.set()


async def handle_client(websocket: websockets.WebSocketServerProtocol, path: str, handler: WebSocketHandler) -> None:
    try:
        handler.register(websocket)
        logger.info(f"WebSocket client connected: {websocket.remote_address}")
        while True:
            await asyncio.sleep(1)
    except websockets.exceptions.ConnectionClosed:
        logger.info(f"WebSocket client disconnected: {websocket.remote_address}")
    except Exception as e:
        logger.error(f"Error handling WebSocket client: {e}")
    finally:
        handler.unregister(websocket)


async def main() -> None:
    handler = WebSocketHandler()
    stream = CameraStream(camera_index=0, frame_rate=10, resolution=(640, 480))
    stream.websocket_handler = handler

    stop_event = asyncio.Event()

    def signal_handler(sig: int) -> None:
        logger.info(f"Signal {sig} received, shutting down...")
        stream.stop_stream()
        stop_event.set()

    loop = asyncio.get_running_loop()
    for sig in (signal.SIGINT, signal.SIGTERM):
        try:
            loop.add_signal_handler(sig, lambda s=sig: asyncio.create_task(signal_handler(s)))
        except NotImplementedError:
            signal.signal(sig, lambda s, f: asyncio.create_task(signal_handler(s)))

    server = await loop.create_server(
        lambda: handle_client(websocket, "", handler),
        '0.0.0.0', 8765
    )
    logger.info("WebSocket server started on ws://0.0.0.0:8765")

    try:
        await asyncio.gather(
            stream.start_stream(),
            stop_event.wait(),
            return_exceptions=True
        )
    except asyncio.CancelledError:
        pass
    finally:
        server.close()
        await server.wait_closed()
        handler.close_all()
        logger.info("Server stopped.")


if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        logger.info("Interrupted by user.")
        sys.exit(0)

