import argparse
import datetime
import json
import logging
import logging.handlers
import os
import signal
import sys
import threading
import time
from collections import deque

import numpy as np
import matplotlib.pyplot as plt
from matplotlib import cm

try:
    import smbus2
except ImportError:
    smbus2 = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

# Constants
DEFAULT_SAMPLING_RATE = 5
DEFAULT_MOTION_DETECTION_THRESHOLD = 1.0
DEFAULT_LOG_FILE_PATH = "beehive.log"
DEFAULT_LOG_MAX_SIZE = 1048576
DEFAULT_ENABLE_CAMERA = False
AMG8833_I2C_ADDR = 0x69
AMG8833_REG_PCTL = 0x00
AMG8833_REG_RST = 0x01
AMG8833_REG_T01L = 0x80
AMG8833_REG_T01H = 0x81
AMG8833_REG_T13L = 0x9F
AMG8833_REG_P01L = 0x40
AMG8833_REG_P01H = 0x41
AMG8833_REG_P13L = 0x5F
AMG8833_PCTL_NORMAL = 0x00
AMG8833_PCTL_SLEEP = 0x10
AMG8833_PCTL_STANDALONE = 0x20
AMG8833_PCTL_RESET = 0x30
AMG8833_RESET_DELAY = 0.01
AMG8833_MEASUREMENT_DELAY = 0.5
MAX_INIT_ATTEMPTS = 3
INIT_ATTEMPT_DELAY = 2
MAX_FRAMES = 300
VISUALIZATION_INTERVAL = 5

# Global state
running = True
config = {}
log_handler = None
log_file = None
i2c_bus = None
camera = None
frame_queue = deque(maxlen=MAX_FRAMES)
frame_lock = threading.Lock()


def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False


def load_config(config_file):
    global config
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        logging.info(f"Configuration loaded from {config_file}")
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        config = {}
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}")
        config = {}
    except Exception as e:
        logging.error(f"Error loading configuration: {e}")
        config = {}


def initialize_amg8833():
    global i2c_bus
    if smbus2 is None:
        logging.error("smbus2 library not available")
        return False
    for attempt in range(1, MAX_INIT_ATTEMPTS + 1):
