    if result.returncode != 0:
        log.error("libcamera-still exited with code %d: %s", result.returncode, result.stderr.strip())
        raise RuntimeError(f"libcamera-still failed (rc={result.returncode})")

    jpeg_bytes = result.stdout.encode("utf-8")
    if not jpeg_bytes:
        log.error("libcamera-still produced no output.")
        raise RuntimeError("empty capture output")

    return jpeg_bytes


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        log.info("Connected to broker %s:%d", BROKER_HOST, BROKER_PORT)
    else:
        log.error("MQTT connect failed – reason_code=%s", reason_code)


def on_disconnect(client, userdata, flags, reason_code, properties):
    log.warning("Disconnected from broker – reason_code=%s", reason_code)


def on_publish(client, userdata, mid, reason_code, properties):
    pass


def on_message(client, userdata, msg):
    try:
        payload = msg.payload.decode("utf-8", errors="replace")
    except Exception as exc:
        log.error("Failed to decode payload: %s", exc)
        return
    log.info("Control message received on %s: %s", msg.topic, payload)


def publish_image(client, jpeg_bytes):
    try:
        info = client.publish(TOPIC_IMAGE, jpeg_bytes, qos=1)
        info.wait_for_publish(timeout=MQTT_INTERVAL * 2)
        if info.rc != mqtt.MQTT_ERR_SUCCESS:
            log.error("Publish failed with rc=%s", info.rc)
    except Exception as exc:
        log.error("Publish error: %s", exc)


def capture_loop(client):
    while not shutdown_event.is_set():
        try:
            jpeg_bytes = capture_image()
        except Exception as exc:
            log.error("Image capture failed: %s", exc)
            shutdown_event.wait(MQTT_INTERVAL)
            continue

        timestamp = int(time.time() * 1000)
        filename = os.path.join(IMAGE_DIR, f"image_{timestamp}.jpg")
        try:
            with open(filename, "wb") as fh:
                fh.write(jpeg_bytes)
            log.info("Saved %s (%d bytes)", filename, len(jpeg_bytes))
        except OSError as exc:
            log.error("Failed to write image file '%s': %s", filename, exc)

        publish_image(client, jpeg_bytes)
        shutdown_event.wait(MQTT_INTERVAL)


def control_loop(client):
    while not shutdown_event.is_set():
        try:
            client.loop(timeout=1.0)
        except Exception as exc:
            log.error("MQTT control loop error: %s", exc)
            shutdown_event.wait(1.0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ensure_image_dir()
    except OSError:
        return

    client_image = mqtt.Client(mqtt.CallbackAPIVersion.VERSION1)
    client_image.on_connect = on_connect
    client_image.on_disconnect = on_disconnect
    client_image.on_publish = on_publish

    client_control = mqtt.Client(mqtt.CallbackAPIVersion.VERSION1)
    client_control.on_connect = on_connect
    client_control.on_disconnect = on_disconnect
    client_control.on_message = on_message

    capture_thread = None
    try:
        client_image.connect(BROKER_HOST, BROKER_PORT, keepalive=60)
        client_control.connect(BROKER_HOST, BROKER_PORT, keepalive=60)

        client_image.loop_start()
        client_control.loop_start()

        client_control.subscribe(TOPIC_CONTROL, qos=1)
        log.info("Subscribed to %s", TOPIC_CONTROL)

        capture_thread = threading.Thread(target=capture_loop, args=(client_image,), daemon=True)
        capture_thread.start()

        control_loop(client_control)

    except Exception as exc:
        log.error("Fatal error: %s", exc)
    finally:
        log.info("Shutting down …")
        shutdown_event.set()

        if capture_thread is not None and capture_thread.is_alive():
            capture_thread.join(timeout=5)

        for client in (client_image, client_control):
            try:
                client.loop_stop()
                client.disconnect()
            except Exception:
                pass

        log.info("Shutdown complete.")


if __name__ == "__main__":
    main()

