import io
import logging
import numpy as np
from typing import Callable, Optional

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffers MJPEG frames from a camera driver and flushes complete frames to an output sink."""

    def __init__(self, c, sink: Optional[io.BufferedIOBase] = None):
        self.c = c
        self.sink = sink
        self.buf = io.BytesIO()
        self._frame_complete = False
        self._frame_type = 0

    def write(self, d: bytes) -> int:
        """Append data to the buffer and flush complete frames.

        Returns the number of bytes written (len(d)).
        """
        try:
            self.buf.write(d)
            if self.sink is not None:
                self._check_frame_complete()
                if self._frame_complete and self._frame_type != 1:
                    self._flush_frame()
            return len(d)
        except Exception as e:
            logger.error(f"Error in CameraStreamBuffer.write: {e}")
            return 0

    def _check_frame_complete(self):
        """Set _frame_complete and _frame_type based on the MJPEG metadata."""
        try:
            meta = self.c.get_encode_meta()
            if meta and meta.get('frame_bytes', 0) > 0:
                self._frame_complete = True
                self._frame_type = meta.get('frame_type', 0)
            else:
                self._frame_complete = False
                self._frame_type = 0
        except Exception as e:
            logger.error(f"Error checking frame completion: {e}")
            self._frame_complete = False
            self._frame_type = 0

    def _flush_frame(self):
        """Flush the accumulated buffer to the sink."""
        try:
            frame_data = self.buf.getvalue()
            if self.sink:
                self.sink.write(frame_data)
            self.buf.seek(0)
            self.buf.truncate()
            self._frame_complete = False
            self._frame_type = 0
        except Exception as e:
            logger.error(f"Error flushing frame: {e}")

    def flush(self):
        """Flush any remaining data in the buffer."""
        try:
            if self.buf.tell() > 0:
                self._flush_frame()
        except Exception as e:
            logger.error(f"Error flushing remaining data: {e}")


class MotionDetectionBuffer:
    """Detects motion by comparing consecutive JPEG frames."""

    def __init__(self, f: Callable[[np.ndarray, np.ndarray], None]):
        self.f = f
        self.buf = io.BytesIO()
        self.prev_frame: Optional[np.ndarray] = None

    def write(self, d: bytes) -> int:
        """Parse MJPEG stream, decode JPEGs, and invoke the callback.

        Returns the number of bytes written (len(d)).
        """
        try:
            self.buf.write(d)
            if self.buf.tell() < 2:
                return len(d)

            while True:
                # Look for JPEG start-of-image marker (0xFF 0xD8)
                if self.buf.tell() < 2:
                    break
                self.buf.seek(-2, io.SEEK_CUR)
                marker = self.buf.read(2)
                if marker == b'\xff\xd8':
                    # Found a JPEG start; read the rest of the frame
                    self.buf.seek(-2, io.SEEK_CUR)
                    frame_bytes = self.buf.read(self.buf.tell())
                    self.buf.seek(0)
                    self.buf.truncate()

                    if frame_bytes:
                        try:
                            img = self.c.imdecode(frame_bytes, 1)
                            if img is not None:
                                if self.prev_frame is not None:
                                    self.f(self.prev_frame, img)
                                self.prev_frame = img
                        except Exception as e:
                            logger.error(f"Error decoding frame: {e}")
                    break
                else:
                    # Not a JPEG start; skip bytes until we find the next marker
                    self.buf.seek(-1, io.SEEK_CUR)
                    chunk = self.buf.read(1024)
                    if not chunk:
                        break
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer.write: {e}")
        return len(d)

