import time
import signal
import sys
import logging
import threading
from typing import Optional, Tuple

import numpy as np
import config
import my_face as mf
from gpiozero import OutputDevice, Button
from sound import Sound
from speech import Speech
from camera import Camera
from face import EigenFaceRecognizer

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class Door:
    def __init__(self, lock_pin: int = 18, button_pin: int = 17):
        self.lock = OutputDevice(lock_pin, active_high=True, initial_value=False)
        self.button = Button(button_pin, pull_up=True, bounce_time=0.05)
        self._lock_state = False
        self._closed = threading.Event()

    def is_button_up(self) -> bool:
        return self.button.is_pressed

    def lock_door(self) -> None:
        self.lock.off()
        self._lock_state = False

    def unlock_door(self) -> None:
        self.lock.on()
        self._lock_state = True

    def is_locked(self) -> bool:
        return self._lock_state

    def close(self) -> None:
        self._closed.set()
        self.lock.close()
        self.button.close()


class SoundController:
    def __init__(self, sound_files: dict):
        self.sounds = {}
        for name, path in sound_files.items():
            try:
                self.sounds[name] = Sound(path)
            except Exception as e:
                logger.error(f"Error loading sound {name}: {e}")
                self.sounds[name] = None

    def play(self, sound_name: str) -> None:
        sound = self.sounds.get(sound_name)
        if sound is not None:
            try:
                sound.play()
            except Exception as e:
                logger.error(f"Error playing sound {sound_name}: {e}")


class FacialRecognitionSystem:
    def __init__(self, camera: Camera, face_recognizer: EigenFaceRecognizer, sound_controller: SoundController, speech: Speech, door: Door):
        self.camera = camera
        self.face_recognizer = face_recognizer
        self.sound_controller = sound_controller
        self.speech = speech
        self.door = door
        self._running = threading.Event()
        self._lock = threading.Lock()

    def recognize_face(self) -> Tuple[Optional[str], Optional[float]]:
        try:
            image = self.camera.read()
            if image is None:
                return None, None
            gray_image = mf.rgb2gray(image)
            face_coords = mf.detect_single(gray_image)
            if face_coords is None:
                return None, None
            x, y, w, h = face_coords
            cropped_face = mf.crop(gray_image, x, y, w, h)
            cropped_face = mf.resize(cropped_face)
            cropped_face = mf.to_float(cropped_face)
            cropped_face = mf.center(cropped_face)
            cropped_face = mf.normalize(cropped_face)
            cropped_face = mf.flatten(cropped_face)
            label, confidence = self.face_recognizer.predict(cropped_face)
            return label, confidence
        except Exception as e:
            logger.error(f"Error during face recognition: {e}")
            return None, None

    def run(self) -> None:
        self._running.set()
        while self._running.is_set():
            if self.door.is_button_up():
                label, confidence = self.recognize_face()
                if label is None:
                    self.sound_controller.play("later")
                    self.speech.say("No face detected.")
                elif label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                    self.sound_controller.play("welcome")
                    self.speech.say("Welcome!")
                    with self._lock:
                        if self.door.is_button_up():
                            self.door.unlock_door()
                else:
                    self.sound_controller.play("wait")
                    self.speech.say("Access denied.")
            time.sleep(0.1)


def main() -> None:
    door = None
    try:
        door = Door(lock_pin=18, button_pin=17)
        camera = Camera()
        face_recognizer = EigenFaceRecognizer(config.TRAINING_FILE)
        sound_controller = SoundController(config.SOUND_FILES)
        speech = Speech()
        facial_recognition_system = FacialRecognitionSystem(camera, face_recognizer, sound_controller, speech, door)

        def signal_handler(signum, frame):
            logger.info(f"Signal {signum} received, shutting down...")
            facial_recognition_system._running.clear()

        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

        facial_recognition_thread = threading.Thread(target=facial_recognition_system.run, daemon=True)
        facial_recognition_thread.start()

        while facial_recognition_system._running.is_set():
            time.sleep(0.1)

        facial_recognition_thread.join(timeout=5)
    except Exception as e:
        logger.error(f"An error occurred: {e}")
    finally:
        if door is not None:
            door.close()


if __name__ == "__main__":
    main()

