import signal
import sys
import time
import logging

import smbus2
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

try:
    import adafruit_bme280
    import adafruit_tsl2561
except ImportError as exc:
    print(f"Missing required library: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-bme280 adafruit-circuitpython-tsl2561", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("bme280_oled")

I2C_BUS = 1
I2C_SCL = 3
I2C_SDA = 2

BME280_ADDR = 0x76
TSL2561_ADDR = 0x39

running = True


def handle_signal(signum, frame):
    global running
    running = False


signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)


def init_i2c():
    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        log.error("Cannot open I2C bus %d: %s", I2C_BUS, exc)
        return None

    try:
        bus.read_byte(BME280_ADDR)
    except OSError:
        log.error("BME280 not found at 0x%02X on bus %d", BME280_ADDR, I2C_BUS)
        bus.close()
        return None

    try:
        bus.read_byte(TSL2561_ADDR)
    except OSError:
        log.error("TSL2561 not found at 0x%02X on bus %d", TSL2561_ADDR, I2C_BUS)
        bus.close()
        return None

    return bus


def init_sensors(bus):
    try:
        bme = adafruit_bme280.Adafruit_BME280_I2C(bus, address=BME280_ADDR)
        bme.sea_level_pressure = 1013.25
    except Exception as exc:
        log.error("BME280 init failed: %s", exc)
        return None, None

    try:
        tsl = adafruit_tsl2561.TSL2561(bus, address=TSL2561_ADDR)
    except Exception as exc:
        log.error("TSL2561 init failed: %s", exc)
        return bme, None

    return bme, tsl


def init_oled():
    try:
        serial = i2c(port=I2C_BUS, address=0x3C)
        return ssd1306(serial, width=128, height=64)
    except Exception as exc:
        log.error("OLED init failed: %s", exc)
        return None


def read_bme280(bme):
    if bme is None:
        return None, None, None
    try:
        return bme.temperature, bme.humidity, bme.pressure
    except OSError as exc:
        log.warning("BME280 read error: %s", exc)
        return None, None, None


def read_tsl2561(tsl):
    if tsl is None:
        return None
    try:
        return tsl.lux
    except OSError as exc:
        log.warning("TSL2561 read error: %s", exc)
        return None


def display_data(oled, temp, hum, pres, lux):
    try:
        with canvas(oled) as draw:
            draw.text((0, 0), f"Temp: {temp:.1f} C", fill="white")
