    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        log.error("Cannot open I2C bus %d: %s", I2C_BUS, exc)
        return None

    try:
        bus.read_byte(BME280_ADDR)
    except OSError:
        log.error("BME280 not found at 0x%02X on bus %d", BME280_ADDR, I2C_BUS)
        bus.close()
        return None

    try:
        bus.read_byte(TSL2561_ADDR)
    except OSError:
        log.error("TSL2561 not found at 0x%02X on bus %d", TSL2561_ADDR, I2C_BUS)
        bus.close()
