import os
import time
import signal
import logging
from typing import List, Optional

from PIL import Image

logger = logging.getLogger(__name__)


class AnimatedGif:
    """Animated GIF player for a Raspberry Pi display driver.

    Attributes:
        display: The display object that accepts RGB image data.
        width: Target width for scaling GIF frames. Defaults to display.width.
        height: Target height for scaling GIF frames. Defaults to display.height.
        folder: Directory containing the GIF files.
        files: List of valid GIF file paths.
        _is_running: Internal flag controlling the animation loop.
    """

    def __init__(self, display, folder: str, width: Optional[int] = None, height: Optional[int] = None):
        if not hasattr(display, 'display') or not callable(display.display):
            raise TypeError("display must have a 'display' callable")
        self.display = display
        self.width = width if width is not None else getattr(display, 'width', 0)
        self.height = height if height is not None else getattr(display, 'height', 0)
        self.folder = folder
        self.files: List[str] = []
        self._is_running = False

    def load_files(self) -> None:
        """Load and validate GIF files from the folder.

        Raises:
            FileNotFoundError: If no valid GIF files are found.
        """
        if not os.path.isdir(self.folder):
            raise FileNotFoundError(f"Folder not found: {self.folder}")

        try:
            self.files = [
                os.path.join(self.folder, f)
                for f in os.listdir(self.folder)
                if f.lower().endswith('.gif')
            ]
        except OSError as e:
            logger.error(f"Error listing folder {self.folder}: {e}")
            raise

        if not self.files:
            raise FileNotFoundError(f"No GIF files found in {self.folder}")

        for file_path in self.files:
            try:
                with Image.open(file_path) as img:
                    if getattr(img, 'is_animated', False):
                        logger.debug(f"Validated animated GIF: {file_path}")
                    else:
                        logger.warning(f"Not an animated GIF (no is_animated flag): {file_path}")
                        self.files.remove(file_path)
            except (FileNotFoundError, OSError, IOError, ValueError) as e:
                logger.warning(f"Skipping invalid GIF file {file_path}: {e}")
                self.files.remove(file_path)

        if not self.files:
            raise FileNotFoundError(f"No valid animated GIF files found in {self.folder}")

    def preload(self) -> None:
        """Preload all GIF frames into memory.

        Each frame is converted to RGB, padded to the target dimensions,
        and the per-frame duration (ms) and loop count are read from
        the image metadata.  Frames are stored in self.files as a list
        of (frame_image, duration_ms, loop_count) tuples.
        """
        self.files = []
        for file_path in self.files:
            try:
                with Image.open(file_path) as img:
                    loop_count = img.info.get('loop', 0)
                    duration_ms = img.info.get('duration', 0)
                    if duration_ms is None:
                        duration_ms = 0
                    img = img.convert('RGB')
                    img = self._pad_image(img)
                    self.files.append((img, duration_ms, loop_count))
            except (FileNotFoundError, OSError, IOError, ValueError) as e:
                logger.warning(f"Skipping GIF file {file_path} during preload: {e}")
                continue

    def _pad_image(self, img: Image.Image) -> Image.Image:
        """Pad an image to the target dimensions using black background.

        Uses nearest-neighbor scaling and centers the image.
        """
        target_width = self.width
        target_height = self.height
        img_width, img_height = img.size

        if img_width == target_width and img_height == target_height:
            return img

        background = Image.new('RGB', (target_width, target_height), 'black')
        offset_x = (target_width - img_width) // 2
        offset_y = (target_height - img_height) // 2
        background.paste(img, (offset_x, offset_y))
        return background

    def play(self) -> bool:
        """Play the animated GIF once.

        Returns:
            True if playback finished successfully, False otherwise.
        """
        if not self.files:
            logger.warning("No GIF files loaded. Cannot play.")
            return False

        for frame, duration_ms, loop_count in self.files:
            if not self._is_running:
                logger.info("Animation stopped before playback.")
                return False

            try:
                self.display.display(frame)
            except Exception as e:
                logger.error(f"Error displaying frame: {e}")
                return False

            elapsed = 0.0
            frame_duration = duration_ms / 1000.0
            if frame_duration > 0:
                start = time.monotonic()
                while elapsed < frame_duration and self._is_running:
                    time.sleep(min(frame_duration - elapsed, 0.1))
                    elapsed = time.monotonic() - start

            if not self._is_running:
                logger.info("Animation stopped during frame playback.")
                return False

            if loop_count == 0:
                continue
            if loop_count == 1:
                return True
            # loop_count > 1: advance to next GIF
            break

        return True

    def run(self) -> None:
        """Continuously run the animation until stopped."""
        self._is_running = True
        try:
            while self._is_running:
                try:
                    self.play()
                except Exception as e:
                    logger.error(f"Error during playback: {e}")
                    if self._is_running:
                        time.sleep(0.1)
                if self._is_running:
                    time.sleep(0.1)
        finally:
            self.stop()

    def stop(self) -> None:
        """Stop the animation and release resources."""
        self._is_running = False
        logger.info("Animation stopped.")


def _signal_handler(signum, frame, animation: Optional[AnimatedGif] = None):
    """Handle SIGINT/SIGTERM by stopping the animation."""
    logger.info(f"Signal {signum} received. Stopping animation.")
    if animation is not None:
        animation.stop()

