import signal
import sys
import time
import logging

try:
    import smbus
except ImportError:
    sys.stderr.write("This script requires the smbus library. Install with: pip install smbus2\n")
    sys.exit(1)

try:
    from luma.core.interface.serial import i2c as luma_i2c
    from luma.oled.device import ssd1306
    from luma.core.render import canvas
except ImportError:
    sys.stderr.write("This script requires the luma.oled library. Install with: pip install luma.oled\n")
    sys.exit(1)

try:
    from adafruit_tsl2561 import TSL2561
except ImportError:
    sys.stderr.write("This script requires the adafruit-circuitpython- tsl2561 library. Install with: pip install adafruit-circuitpython- tsl2561\n")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("tsl2561_oled")

I2C_BUS = 1
OLED_ADDR = 0x3C
TSL2561_ADDR = 0x39
READ_INTERVAL = 1.0

running = True
bus = None
oled = None
sensor = None


def cleanup(signum=None, frame=None):
    global running, bus, oled, sensor
    running = False
    log.info("Shutting down...")
    if sensor is not None:
        try:
            sensor.power_down()
        except Exception:
            pass
    if oled is not None:
        try:
            oled.clear()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def init_i2c():
    global bus
    try:
        bus = smbus.SMBus(I2C_BUS)
    except Exception as e:
        log.error("Failed to open I2C bus %d: %s", I2C_BUS, e)
        return False
    return True


def init_oled():
    global oled
    try:
        serial = luma_i2c(port=I2C_BUS, address=OLED_ADDR)
        oled = ssd1306(serial)
    except Exception as e:
        log.error("Failed to initialize SSD1306 OLED at 0x%02X: %s", OLED_ADDR, e)
        return False
    return True


def init_sensor():
    global sensor
    try:
        sensor = TSL2561(bus, address=TSL2561_ADDR)
        sensor.integration_time = 101
        sensor.gain = 1
        log.info("TSL2561 initialized (gain=1, integration=101ms).")
    except Exception as e:
        log.error("Failed to initialize TSL2561 at 0x%02X: %s", TSL2561_ADDR, e)
        return False
    return True


def read_lux():
    try:
        raw = sensor.raw
        if raw is None:
            log.warning("Sensor returned None raw value.")
            return None
        if raw[0] == 0 and raw[1] == 0:
            log.warning("Sensor saturated or no light detected.")
            return None
        if raw[1] == 0:
            log.warning("Sensor gain out of range (1x gain, 101ms integration).")
            return None
        lux = (raw[0] * 0.0304) + (raw[1] * 0.0282)
        if raw[1] > 0x1000:
            lux += (raw[0] * 0.0153) + ((raw[1] - 0x1000) * 0.00013)
        return lux
    except Exception as e:
        log.error("Error reading lux: %s", e)
        return None


def lux_to_contrast(lux):
    if lux is None:
        return 0
    if lux <= 0:
        return 0
    if lux >= 10000:
        return 255
    return int((lux / 10000) * 255)


def main():
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    if not init_i2c():
        sys.exit(1)

    if not init_oled():
        cleanup()
        sys.exit(1)

    if not init_sensor():
        cleanup()
        sys.exit(1)

    log.info("Entering main loop. Press Ctrl+C to exit.")
    while running:
        lux = read_lux()
        contrast = lux_to_contrast(lux)
        try:
            with canvas(oled) as draw:
                if lux is not None:
                    draw.text((0, 0), f"Lux: {lux:.2f}", fill="white")
                else:
                    draw.text((0, 0), "Sensor Error", fill="white")
                draw.text((0, 12), f"Contrast: {contrast}", fill="white")
        except Exception as e:
            log.error("OLED display update failed: %s", e)
        time.sleep(READ_INTERVAL)


if __name__ == "__main__":
    main()

