                aqi, pm25 = read_simulated_sensor(config)
                if aqi is not None and pm25 is not None:
                    last_aqi = aqi
                    last_pm25 = pm25
                    timestamp = datetime.datetime.now().isoformat()
                    store_reading(timestamp, aqi, pm25)
                    color, description = classify_aqi(aqi, config["aqi_thresholds"])
                    print(f"AQI: {aqi}, PM2.5: {pm25:.2f} µg/m³, Color: {color}, Description: {description}")
                    last_update_time = current_time
                else:
                    logging.warning("Failed to read sensor data.")
            if button_pin is not None and GPIO is not None:
                try:
                    if GPIO.input(button_pin) == GPIO.LOW:
                        color, description = classify_aqi(last_aqi, config["aqi_thresholds"])
                        print(f"Button pressed. Current AQI: {last_aqi}, Color: {color}, Description: {description}")
                        time.sleep(0.2)
                except Exception as e:
                    logging.error("Error reading button: %s", e)
            time.sleep(0.1)
    except Exception as e:
        logging.error("An unexpected error occurred: %s", e)
    finally:
        cleanup_gpio(button_pin)
        logging.info("Air Quality Monitor stopped")


if __name__ == "__main__":
    main()

