import smbus
import time
import random
import signal
import sys

LCD_I2C_ADDR = 0x27
I2C_BUS = 1

# PCF8574 pin mapping for typical 16x2 LCD backpacks
EN = 0x04
RW = 0x02
RS = 0x01
BACKLIGHT = 0x08

bus = None
running = True

def signal_handler(signum, frame):
    global running
    running = False

def lcd_write_byte(data, mode):
    high = mode | (data & 0xF0) | BACKLIGHT
    low = mode | ((data << 4) & 0xF0) | BACKLIGHT
    for byte in (high, low):
        try:
            bus.write_byte(LCD_I2C_ADDR, byte)
            time.sleep(0.0005)
            bus.write_byte(LCD_I2C_ADDR, byte | EN)
            time.sleep(0.0005)
            bus.write_byte(LCD_I2C_ADDR, byte & ~EN)
            time.sleep(0.0005)
        except OSError as e:
            print(f"I2C write error: {e}")
            return False
    return True

def lcd_command(cmd):
    if not lcd_write_byte(cmd, 0):
        return False
    time.sleep(0.005)
    return True

def lcd_data(val):
    if not lcd_write_byte(val, RS):
        return False
    time.sleep(0.005)
    return True

def lcd_init():
    if not lcd_command(0x33):
        return False
    if not lcd_command(0x32):
        return False
    if not lcd_command(0x28):
        return False
    if not lcd_command(0x0C):
        return False
    if not lcd_command(0x06):
        return False
    if not lcd_command(0x01):
        return False
    time.sleep(0.005)
    return True

def lcd_clear():
    lcd_command(0x01)
    time.sleep(0.005)

def lcd_set_cursor(row, col):
    addr = 0x80 + col if row == 0 else 0xC0 + col
    lcd_command(addr)

def lcd_print(text, row=0):
    lcd_set_cursor(row, 0)
    for ch in text[:16]:
        lcd_data(ord(ch))

def get_soil_moisture():
    return random.randint(0, 100)

def get_air_temperature():
    return round(random.uniform(15.0, 35.0), 1)

def main():
    global bus
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)
    try:
        if not lcd_init():
            print("LCD initialization failed.")
            return
        for i in range(5):
            if not running:
                break
            soil = get_soil_moisture()
            air = get_air_temperature()
            row1 = f"Soil:{soil:02d}%"
            row2 = f"Air:{air:05.1f}C"
            lcd_print(row1, 0)
            lcd_print(row2, 1)
            print(f"Iter {i+1}: Soil={soil}% Air={air}C")
            time.sleep(2.0)
    except OSError as e:
        print(f"I2C communication error: {e}")
    finally:
        if bus is not None:
            try:
                lcd_clear()
            except OSError:
                pass
            bus.close()
            print("I2C bus closed.")

if __name__ == "__main__":
    main()

