import os
import sys
import time
import signal
import logging
from PIL import Image, ImageOps, ImageSequence
import smbus2
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

I2C_BUS = 1
I2C_ADDR = 0x3C
GIF_FOLDER = "gifs"
DISPLAY_WIDTH = 128
DISPLAY_HEIGHT = 64

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logger.info("SIGINT received, shutting down...")

def init_i2c_bus():
    try:
        bus = smbus2.SMBus(I2C_BUS)
        return bus
    except Exception as e:
        logger.error(f"Failed to initialize I2C bus {I2C_BUS}: {e}")
        return None

def init_oled_display():
    try:
        serial = i2c(port=I2C_BUS, address=I2C_ADDR)
        device = ssd1306(serial, width=DISPLAY_WIDTH, height=DISPLAY_HEIGHT)
        return device
    except Exception as e:
        logger.error(f"Failed to initialize OLED display at 0x{I2C_ADDR:02X}: {e}")
        return None

def load_gif_files(folder_path):
    if not os.path.isdir(folder_path):
        logger.error(f"GIF folder not found: {folder_path}")
        return []
    try:
        return [os.path.join(folder_path, f) for f in os.listdir(folder_path) if f.lower().endswith('.gif')]
    except Exception as e:
        logger.error(f"Error listing GIF files in {folder_path}: {e}")
        return []

def get_gif_metadata(file_path):
    try:
        with Image.open(file_path) as img:
            return img.info
    except Exception as e:
        logger.error(f"Error reading GIF metadata from {file_path}: {e}")
        return None

def resize_and_pad_image(image, width, height):
    try:
        resized = ImageOps.fit(image, (width, height), method=Image.Resampling.NEAREST)
        background = Image.new("RGB", (width, height), "black")
        background.paste(resized, (0, 0))
        return background
    except Exception as e:
        logger.error(f"Error resizing/padding image: {e}")
        return None

def display_gif_frame(device, image):
    try:
        with canvas(device) as draw:
            draw.image(image)
    except Exception as e:
        logger.error(f"Error displaying frame: {e}")

def play_gif(device, file_path, loop_count):
    try:
        with Image.open(file_path) as img:
            if loop_count == 0:
                for frame in ImageSequence.Iterator(img):
                    if not running:
                        break
                    frame = resize_and_pad_image(frame.convert("RGB"), DISPLAY_WIDTH, DISPLAY_HEIGHT)
                    if frame:
                        display_gif_frame(device, frame)
                    time.sleep(0.033)
            else:
                for _ in range(loop_count):
                    if not running:
                        break
                    for frame in ImageSequence.Iterator(img):
                        if not running:
                            break
                        frame = resize_and_pad_image(frame.convert("RGB"), DISPLAY_WIDTH, DISPLAY_HEIGHT)
                        if frame:
                            display_gif_frame(device, frame)
                        time.sleep(0.033)
    except Exception as e:
        logger.error(f"Error playing GIF {file_path}: {e}")

def main():
    signal.signal(signal.SIGINT, signal_handler)
    bus = init_i2c_bus()
    if bus is None:
        sys.exit(1)
    device = init_oled_display()
    if device is None:
        bus.close()
        sys.exit(1)
    try:
        gif_files = load_gif_files(GIF_FOLDER)
        if not gif_files:
            logger.warning("No GIF files found in the specified folder.")
            return
        for gif_file in gif_files:
            if not running:
                break
            metadata = get_gif_metadata(gif_file)
            if metadata:
                loop_count = metadata.get('loop', 0)
                logger.info(f"Playing GIF: {gif_file}, Loop count: {loop_count}")
                play_gif(device, gif_file, loop_count)
            else:
                logger.warning(f"Skipping GIF {gif_file}: metadata unavailable.")
    finally:
        try:
            device.cleanup()
        except Exception:
            pass
        try:
            bus.close()
        except Exception:
            pass
        logger.info("Resources released. Exiting.")

if __name__ == "__main__":
    main()

