# Constants for motor control
LEFT_MOTOR_IN1 = 12
LEFT_MOTOR_IN2 = 13
RIGHT_MOTOR_IN1 = 18
RIGHT_MOTOR_IN2 = 19

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _stop_motors():
    """Stop both motors safely."""
    try:
        GPIO.output(LEFT_MOTOR_IN1, GPIO.LOW)
        GPIO.output(LEFT_MOTOR_IN2, GPIO.LOW)
        GPIO.output(RIGHT_MOTOR_IN1, GPIO.LOW)
        GPIO.output(RIGHT_MOTOR_IN2, GPIO.LOW)
    except Exception:
        pass


def _set_motor_pins():
    """Configure GPIO pins for motor control."""
    GPIO.setmode(GPIO.BCM)
    for pin in (LEFT_MOTOR_IN1, LEFT_MOTOR_IN2, RIGHT_MOTOR_IN1, RIGHT_MOTOR_IN2):
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)


def _set_motor_speed(left_speed, right_speed):
    """Set motor speeds with safety checks."""
    if not (-100 <= left_speed <= 100 and -100 <= right_speed <= 100):
        raise ValueError("Motor speeds must be between -100 and 100")
    GPIO.output(LEFT_MOTOR_IN1, GPIO.HIGH if left_speed > 0 else GPIO.LOW)
    GPIO.output(LEFT_MOTOR_IN2, GPIO.LOW if left_speed > 0 else GPIO.HIGH)
    GPIO.output(RIGHT_MOTOR_IN1, GPIO.HIGH if right_speed > 0 else GPIO.LOW)
    GPIO.output(RIGHT_MOTOR_IN2, GPIO.LOW if right_speed > 0 else GPIO.HIGH)


def calculate_distance(point1, point2):
    """Calculate Euclidean distance between two points."""
    try:
        return math.sqrt((point2[0] - point1[0]) ** 2 + (point2[1] - point1[1]) ** 2)
    except TypeError:
        raise ValueError("Both points must be tuples of two numeric values")


def calculate_angle(point1, point2):
    """Calculate angle (degrees) of the line from point1 to point2, relative to the x-axis."""
    try:
        dx = point2[0] - point1[0]
        dy = point2[1] - point1[1]
        return math.degrees(math.atan2(dy, dx)) if dx or dy else 0.0
    except TypeError:
        raise ValueError("Both points must be tuples of two numeric values")


def calculate_heading(point1, point2):
    """Calculate heading (degrees) from point1 to point2."""
    try:
        dx = point2[0] - point1[0]
        dy = point2[1] - point1[1]
        return math.degrees(math.atan2(dy, dx))
    except TypeError:
        raise ValueError("Both points must be tuples of two numeric values")


def calculate_intersection(line1_start, line1_end, line2_start, line2_end):
    """Calculate intersection of two lines. Returns (x, y) or None if parallel/invalid."""
    try:
        xdiff = (line1_start[0] - line1_end[0], line2_start[0] - line2_end[0])
        ydiff = (line1_start[1] - line1_end[1], line2_start[1] - line2_end[1])

        def det(a, b):
            return a[0] * b[1] - a[1] * b[0]

        div = det(xdiff, ydiff)
        if div == 0:
            return None

        d = (det(*line1_start), det(*line2_start))
        x = det(d, xdiff) / div
        y = det(d, ydiff) / div
        return x, y
    except TypeError:
        raise ValueError("All points must be tuples of two numeric values")


def calculate_perpendicular_bisector(point1, point2):
    """Calculate perpendicular bisector of a line segment."""
    mid_x = (point1[0] + point2[0]) / 2.0
    mid_y = (point1[1] + point2[1]) / 2.0
    angle = calculate_angle(point1, point2) + 90
    return (mid_x, mid_y), angle


def calculate_image_point(point, distance, angle):
    """Calculate image point given a reference point, distance, and angle (degrees)."""
    try:
        rad = math.radians(angle)
        x = point[0] + distance * math.cos(rad)
        y = point[1] + distance * math.sin(rad)
        return x, y
    except TypeError:
        raise ValueError("Point must be a tuple of two numeric values")


def calculate_distance_to_line(point, line_start, line_end):
    """Calculate perpendicular distance from a point to a line."""
    try:
        x1, y1 = line_start
        x2, y2 = line_end
        x0, y0 = point
        dx = x2 - x1
        dy = y2 - y1
        if dx == 0 and dy == 0:
            return calculate_distance(point, line_start)
        m = -dx / dy if dx != 0 else float('inf')
        c = y1 - m * x1 if dx != 0 else x1
        return abs(m * x0 - y0 + c) / math.sqrt(m ** 2 + 1)
    except TypeError:
        raise ValueError("All inputs must be tuples of two numeric values")


def calculate_distance_to_segment(point, segment_start, segment_end):
    """Calculate perpendicular distance from a point to a line segment."""
    try:
        x1, y1 = segment_start
        x2, y2 = segment_end
        x0, y0 = point
        dx = x2 - x1
        dy = y2 - y1
        if dx == 0 and dy == 0:
