import time
import datetime
import random
import subprocess
import sys

# Constants for GPIO pin assignments (BCM numbering)
LIGHT_SENSOR_PIN = 17
TEMP_SENSOR_PIN = 4

# Thresholds for warnings and critical events
LOW_LIGHT_THRESHOLD = 300
HIGH_TEMP_THRESHOLD = 35
HIGH_PI_TEMP_THRESHOLD = 75

# Global flag for graceful shutdown
running = True


def get_light_level():
    """Simulates reading light level from a sensor connected to GPIO17."""
    try:
        hour = datetime.datetime.now().hour
        if 6 <= hour < 18:
            return random.randint(600, 1000)
        else:
            return random.randint(100, 300)
    except Exception as e:
        print(f"Error simulating light level: {e}")
        return None


def get_temperature():
    """Simulates reading temperature from a sensor connected to GPIO4."""
    try:
        return random.uniform(20, 30)
    except Exception as e:
        print(f"Error simulating temperature: {e}")
        return None


def get_voltage(light_level):
    """Calculates simulated battery voltage based on light level."""
    try:
        if light_level is None:
            return None
        if light_level > 300:
            return random.uniform(11.5, 12.5)
        else:
            return random.uniform(10.0, 11.0)
    except Exception as e:
        print(f"Error calculating voltage: {e}")
        return None


def get_current(light_level):
    """Calculates simulated battery current based on light level."""
    try:
        if light_level is None:
            return None
        if light_level > 300:
            return random.uniform(1.5, 2.5)
        else:
            return random.uniform(0.5, 1.0)
    except Exception as e:
        print(f"Error calculating current: {e}")
        return None


def get_pi_temperature():
    """Reads the Raspberry Pi's internal temperature using vcgencmd."""
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True,
            text=True,
            timeout=5,
            check=True
        )
        output = result.stdout.strip()
        # Expected format: temp=XX.X'C
        if not output.startswith('temp='):
            print(f"Unexpected vcgencmd output format: {output}")
            return None
        temp_str = output.split('=')[1].split("'")[0]
        return float(temp_str)
    except subprocess.TimeoutExpired:
        print("Error: vcgencmd timed out.")
        return None
    except subprocess.CalledProcessError as e:
        print(f"Error: vcgencmd failed with return code {e.returncode}: {e.stderr}")
        return None
    except (IndexError, ValueError) as e:
        print(f"Error parsing vcgencmd output: {e}")
        return None
    except Exception as e:
        print(f"Error reading Pi temperature: {e}")
        return None


def log_data(light_level, temperature, voltage, current, pi_temperature):
    """Logs sensor data and system status to the console."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{timestamp} - Light: {light_level} lux, Temperature: {temperature:.2f} C, "
          f"Voltage: {voltage:.2f} V, Current: {current:.2f} A, Pi Temperature: {pi_temperature:.2f} C")


def check_thresholds(light_level, temperature, pi_temperature):
    """Checks sensor values against predefined thresholds and logs warnings or critical events."""
    if light_level is not None and light_level < LOW_LIGHT_THRESHOLD:
        print(f"WARNING: Low light level detected ({light_level} lux). Consider adjusting the solar panel or battery.")
    if temperature is not None and temperature > HIGH_TEMP_THRESHOLD:
        print("WARNING: High temperature detected. Activating cooling system.")
    if pi_temperature is not None and pi_temperature > HIGH_PI_TEMP_THRESHOLD:
        print("CRITICAL: Raspberry Pi temperature too high. Shutting down system.")
        print("CRITICAL: System shutdown initiated.")
        sys.exit(1)


def main():
    """Main function to simulate the clean energy monitoring system."""
    global running
    try:
        while running:
            light_level = get_light_level()
            temperature = get_temperature()
            voltage = get_voltage(light_level)
            current = get_current(light_level)
            pi_temperature = get_pi_temperature()

            log_data(light_level, temperature, voltage, current, pi_temperature)
            check_thresholds(light_level, temperature, pi_temperature)

            time.sleep(5)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Cleaning up resources...")
        print("Program finished.")


if __name__ == "__main__":
    main()

