TIMEOUT = 1.0
READ_INTERVAL = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def open_serial_port() -> serial.Serial:
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error opening serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        raise


def read_temperature(ser: serial.Serial) -> float | None:
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error reading from serial port: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    try:
        line = raw.decode("ascii", errors="replace").strip()
    except Exception as exc:
        print(f"Error decoding serial data: {exc}", file=sys.stderr)
        return None

    if not line:
        return None

    try:
        return float(line)
    except ValueError:
        print(f"Error: Invalid data received from sensor: {line!r}", file=sys.stderr)
        return None


def display_temperature(temperature: float) -> None:
    print(f"Temperature: {temperature:.1f} C")


