import csv
import os
import signal
import sys
import time
from datetime import datetime

import adafruit_dht
from board import D4

DATA_DIR = "/home/pi/data"
CSV_FILE = os.path.join(DATA_DIR, "sensor_data.csv")
ERROR_FILE = os.path.join(DATA_DIR, "error.log")

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _ensure_dir(path):
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as exc:
        print(f"FATAL: cannot create directory {path}: {exc}", file=sys.stderr)
        sys.exit(1)


def _write_error(message):
    try:
        with open(ERROR_FILE, "a", encoding="utf-8") as fh:
            fh.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} - {message}\n")
    except OSError as exc:
        print(f"CRITICAL: cannot write to error log: {exc}", file=sys.stderr)


def _write_csv(timestamp, temperature):
    try:
        with open(CSV_FILE, "a", newline="", encoding="utf-8") as fh:
            writer = csv.writer(fh)
            writer.writerow([timestamp, f"{temperature:.2f}"])
    except OSError as exc:
        _write_error(f"CSV write failed: {exc}")


def main():
    global _running

    _ensure_dir(DATA_DIR)

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = adafruit_dht.DHT22(D4, use_pulseio=False)
    except Exception as exc:
        print(f"FATAL: cannot initialise DHT22 on GPIO4: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(CSV_FILE, "a", newline="", encoding="utf-8") as fh:
            if fh.tell() == 0:
                writer = csv.writer(fh)
                writer.writerow(["Timestamp", "Temperature_C"])

        while _running:
            try:
                temperature = sensor.temperature
                if temperature is None:
                    raise RuntimeError("sensor returned None")
                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                _write_csv(timestamp, temperature)
                print(f"Logged: {timestamp}  {temperature:.2f} C")
            except RuntimeError as exc:
                _write_error(f"DHT22 read error: {exc}")
            except Exception as exc:
                _write_error(f"Unexpected error: {exc}")

            for _ in range(60):
                if not _running:
                    break
                time.sleep(1)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

