import time
import logging
import smbus2
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

DHT20_I2C_ADDRESS = 0x70
DHT20_STATUS_REG = 0x18
DHT20_DATA_REG = 0x29
DHT20_STATUS_CHECK_VALUE = 0x18
POWER_STABILIZATION_DELAY = 0.5
CRC_POLYNOMIAL = 0x31
CRC_INITIAL_VALUE = 0xFF
MAX_RETRIES = 5
RETRY_DELAY = 2.0
STATUS_TIMEOUT = 0.1


class DHT20:
    def __init__(self, i2c_bus_number=1):
        self._bus = None
        self._crc_error = False
        try:
            self._bus = smbus2.SMBus(i2c_bus_number)
            time.sleep(POWER_STABILIZATION_DELAY)
            self._check_status()
        except Exception as e:
            logging.error(f"Error initializing DHT20: {e}")
            self._cleanup()
            raise

    def _check_status(self):
        try:
            status = self._bus.read_byte_data(DHT20_I2C_ADDRESS, DHT20_STATUS_REG)
            if status != DHT20_STATUS_CHECK_VALUE:
                logging.error(
                    f"DHT20 status check failed: got 0x{status:02X}, "
                    f"expected 0x{DHT20_STATUS_CHECK_VALUE:02X}"
                )
                raise RuntimeError("DHT20 status check failed")
        except Exception as e:
            logging.error(f"Error checking DHT20 status: {e}")
            raise

    def _read_raw_data(self):
        try:
            data = self._bus.read_i2c_block_data(
                DHT20_I2C_ADDRESS, DHT20_DATA_REG, 7
            )
            if len(data) != 7:
                raise RuntimeError(f"Expected 7 bytes, got {len(data)}")
            return data
        except Exception as e:
            logging.error(f"Error reading raw data: {e}")
            raise

    @staticmethod
    def _calculate_crc8(data):
        crc = CRC8()
        crc.update(data)
        return crc.digest()

    def read_data(self):
        for attempt in range(1, MAX_RETRIES + 1):
            try:
                self._check_status()
                data = self._read_raw_data()
                crc_error = self._calculate_crc8(data[:6]) != data[6]
                if crc_error:
                    logging.warning(
                        f"DHT20 CRC error on attempt {attempt}/{MAX_RETRIES}"
                    )
                    self._crc_error = True
                else:
                    self._crc_error = False
                    humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4))
                    temperature_raw = (
                        ((data[3] & 0x0F) << 16)
                        | (data[4] << 8)
                        | data[5]
                    )
                    temperature = temperature_raw / 5242.88 - 50.0
                    humidity = humidity_raw / 1048576.0 * 100.0
                    return temperature, humidity, False
            except Exception as e:
                logging.error(f"Error reading data (attempt {attempt}/{MAX_RETRIES}): {e}")
                if attempt < MAX_RETRIES:
                    time.sleep(RETRY_DELAY)
        logging.error("Failed to read DHT20 data after multiple retries.")
        return None, None, True

    def cleanup(self):
        self._cleanup()

    def _cleanup(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self._bus = None


class CRC8:
    def __init__(self, init=CRC_INITIAL_VALUE, poly=CRC_POLYNOMIAL):
        self._init = init
        self._poly = poly
        self._value = init

    def update(self, data):
        if isinstance(data, str):
            data = data.encode("utf-8")
        for byte in data:
            self._value ^= byte
            for _ in range(8):
                if self._value & 0x80:
                    self._value = (
                        (self._value << 1) ^ self._poly
                    ) & 0xFF
                else:
                    self._value = (self._value << 1) & 0xFF

    def digest(self):
        return self._value


def _signal_handler(signum, frame):
    logging.info(f"Signal {signum} received, exiting.")
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        sensor = DHT20()
        temp, hum, crc_err = sensor.read_data()
        if temp is not None and hum is not None:
            logging.info(f"Temperature: {temp:.2f} °C")
            logging.info(f"Humidity: {hum:.2f} %")
        else:
            logging.error("Failed to read DHT20 data.")
        sensor.cleanup()
    except Exception as e:
        logging.error(f"Fatal error: {e}")
        sys.exit(1)

