        bme280 = adafruit_bme280.Adafruit_BME280_I2C(i2c_bus, address=I2C_ADDRESS_BME280)
        return bme280
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        return None

def initialize_tsl2591(i2c_bus):
    """Initializes the TSL2591 sensor."""
    try:
        tsl2591 = adafruit_tsl2591.TSL2591(i2c_bus, address=I2C_ADDRESS_TSL2591)
        return tsl2591
    except Exception as e:
        print(f"Error initializing TSL2591 sensor: {e}")
        return None

def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Reads temperature, humidity, and light intensity from the sensors."""
    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
        light_intensity = tsl2591_sensor.lux
        return temperature, humidity, light_intensity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None

def display_sensor_data(temperature, humidity, light_intensity):
    """Displays the sensor data in a formatted way."""
    if all(v is not None for v in [temperature, humidity, light_intensity]):
        print(f"Temperature: {temperature:.2f} C")
        print(f"Humidity: {humidity:.2f} %")
        print(f"Light Intensity: {light_intensity:.2f} lux")
    else:
        print("Failed to read all sensor data.")

def main():
    """Main function to read and display sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor = initialize_bme280(i2c_bus)
    if bme280_sensor is None:
        return

    tsl2591_sensor = initialize_tsl2591(i2c_bus)
    if tsl2591_sensor is None:
        return

    try:
        while True:
            # Select the correct channel for the BME280 and TSL2591
            try:
                with multiplexer[0]:
                    temperature, humidity, light_intensity = read_sensor_data(bme280_sensor, tsl2591_sensor)
            except Exception as e:
                print(f"Error selecting multiplexer channel: {e}")
                temperature, humidity, light_intensity = None, None, None

            display_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        print("Exiting program.")

if __name__ == "__main__":
    main()

