import time
import logging
import signal
import sys
from typing import Optional

import board
import busio
import adafruit_bmp280

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


class AltitudeMonitor:
    def __init__(self, i2c_bus: int = 1, sea_level_pressure: float = 1013.25):
        self.sea_level_pressure = sea_level_pressure
        self._sensor: Optional[adafruit_bmp280.Adafruit_BMP280_I2C] = None
        self._i2c = None
        self._baseline_pressure: Optional[float] = None

        try:
            self._i2c = busio.I2C(board.SCL, board.SDA)
            self._sensor = adafruit_bmp280.Adafruit_BMP280_I2C(self._i2c, address=0x76)
            self._sensor.sea_level_pressure = self.sea_level_pressure
            logging.info("BMP280 initialized on I2C bus %d.", i2c_bus)
        except (ValueError, OSError, RuntimeError, OSError) as e:
            logging.error("Failed to initialize BMP280: %s", e)
            self._cleanup()
            raise

    def _cleanup(self):
        if self._sensor is not None:
            try:
                self._sensor.sea_level_pressure = self.sea_level_pressure
            except Exception:
                pass
        if self._i2c is not None:
            try:
                self._i2c.deinit()
            except Exception:
                pass
        self._sensor = None
        self._i2c = None

    def get_altitude(self) -> Optional[float]:
        if self._sensor is None:
            logging.error("Sensor not initialized.")
            return None
        try:
            return self._sensor.altitude
        except (OSError, RuntimeError) as e:
            logging.error("Error reading altitude: %s", e)
            return None

    def calibrate(self, num_samples: int = 100) -> bool:
        if self._sensor is None:
            logging.error("Sensor not initialized; cannot calibrate.")
            return False

        logging.info("Calibrating sensor... collecting %d samples.", num_samples)
        pressures = []
        for i in range(num_samples):
            try:
                p = self._sensor.pressure
                if p is not None:
                    pressures.append(p)
            except (OSError, RuntimeError) as e:
                logging.error("Error reading pressure during calibration: %s", e)
            time.sleep(0.1)

        if not pressures:
            logging.error("No valid pressure samples collected; cannot calibrate.")
            return False

        pressures.sort()
        trim = max(1, int(0.25 * num_samples))
        trimmed = pressures[trim:-trim]
        if not trimmed:
            logging.error("Calibration failed: no valid samples after trimming.")
            return False

        self._baseline_pressure = sum(trimmed) / len(trimmed)
        self._sensor.sea_level_pressure = self._baseline_pressure
        logging.info("Calibration complete. Baseline pressure: %.2f hPa", self._baseline_pressure)
        return True

    def get_baseline(self) -> Optional[float]:
        return self._baseline_pressure

    def run(self, sample_interval: float = 1.0):
        if self._sensor is None:
            logging.error("Sensor not initialized; cannot run.")
            return

        if not self.calibrate():
            logging.warning("Using default sea-level pressure of %.2f hPa.", self.sea_level_pressure)
            self._baseline_pressure = self.sea_level_pressure
            self._sensor.sea_level_pressure = self.sea_level_pressure

        logging.info("Starting altitude monitoring. Press Ctrl+C to stop.")
        try:
            while _running:
                altitude = self.get_altitude()
                if altitude is not None:
                    logging.info("Altitude: %.2f meters", altitude)
                time.sleep(sample_interval)
        except KeyboardInterrupt:
            logging.info("Program stopped by user.")
        except Exception as e:
            logging.error("Unexpected error: %s", e)
        finally:
            self._cleanup()


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)
    try:
        monitor = AltitudeMonitor(i2c_bus=1, sea_level_pressure=1013.25)
        monitor.run(sample_interval=1.0)
    except (ValueError, OSError, RuntimeError) as e:
        logging.error("Fatal error: %s", e)
        sys.exit(1)


if __name__ == "__main__":
    main()

