        time.sleep(0.5)
        GPIO.output(led_pin, GPIO.LOW)
        time.sleep(0.5)
    except Exception as e:
        logging.error(f"Error blinking LED: {e}")


def read_dht22():
    if GPIO is None:
        return 25.0, 50.0
    try:
