        import board
        pin_map = {
            4: board.D4,
            17: board.D17,
            18: board.D18,
            22: board.D22,
            23: board.D23,
            24: board.D24,
            25: board.D25,
            27: board.D27,
        }
        if dht_pin not in pin_map:
            logging.error(f"Unsupported BCM pin {dht_pin} for DHT22.")
            return None, None
        dht = adafruit_dht.DHT22(pin_map[dht_pin], use_pulseio=False)
        try:
            temperature = dht.temperature
            humidity = dht.humidity
            if temperature is None or humidity is None:
                logging.warning("DHT22 returned None for temperature or humidity.")
                return None, None
            return temperature, humidity
        finally:
            dht.exit()
    except RuntimeError as e:
        logging.error(f"DHT22 read error (sensor absent or timing issue): {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected DHT22 error: {e}")
        return None, None


def main():
    global running
    load_config()
    setup_logging()
    logging.info("Starting DHT22 monitoring system.")
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    gpio_ok = setup_gpio()
    try:
        while running:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                logging.info(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                if gpio_ok:
                    blink_led()
            else:
                logging.error("Failed to read DHT22 sensor data.")
                if gpio_ok:
                    GPIO.output(led_pin, GPIO.HIGH)
            time.sleep(read_interval)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Shutting down DHT22 monitoring system.")
        cleanup_gpio()
        logging.info("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

