import time
import signal
import sys
from gpiozero import PWMOutputDevice

PWM_PIN = 18
PWM_FREQ = 50.0
TEMP_FILE = '/sys/class/thermal/thermal_zone0/temp'
LOOP_INTERVAL = 1.0

running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_cpu_temp():
    try:
        with open(TEMP_FILE, 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (OSError, ValueError) as e:
        print(f'Error reading CPU temperature: {e}', file=sys.stderr)
        return None

def compute_duty(temp):
    if temp is None:
        return None
    if temp > 80.0:
        return 100.0
    if temp > 70.0:
        return 80.0
    if temp > 60.0:
        return 60.0
    if temp > 50.0:
        return 40.0
    return 20.0

def main():
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        fan = PWMOutputDevice(PWM_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        print(f'Failed to initialize PWM on BCM pin {PWM_PIN}: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            temp = read_cpu_temp()
            duty = compute_duty(temp)

            if duty is not None:
                fan.value = duty / 100.0
                print(f'Temp: {temp:.1f} C  |  Duty: {duty:.1f}%')
            else:
                print('Skipping this iteration due to read error.', file=sys.stderr)

            time.sleep(LOOP_INTERVAL)
    finally:
        fan.value = 0.0
        fan.close()
        print('Fan control stopped and resources released.')

if __name__ == '__main__':
    main()

