import time
import signal
import sys
import board
import adafruit_dht

# Global sensor handle so signal handler can release it
_sensor = None

def _cleanup(signum=None, frame=None):
    """Release the sensor and exit cleanly on signal or normal exit."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None
    if signum is not None:
        sys.exit(0)

def main():
    global _sensor

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    # Initialize the DHT11 sensor on board.D4 (BCM 4, physical pin 7)
    try:
        _sensor = adafruit_dht.DHT11(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 on board.D4: {e}")
        sys.exit(1)

    try:
        while True:
            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f} °C")
                    print(f"Humidity: {humidity:.1f} %")
                else:
                    print("Sensor returned None for temperature or humidity.")

            except RuntimeError as e:
                # DHT11 reads can occasionally fail due to timing jitter or
                # checksum errors; retry on the next iteration.
                print(f"RuntimeError reading DHT11: {e}")

            except Exception as e:
                # Catch-all for unexpected I/O or library errors
                print(f"Unexpected error: {e}")

            time.sleep(5)

    except KeyboardInterrupt:
        pass
    finally:
        _cleanup()

if __name__ == "__main__":
    main()

