import random
import time
import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

HEATER_PIN = 17
READ_INTERVAL = 2.0
NUM_READINGS = 5
TEMP_MIN = 10
TEMP_MAX = 30
HEATER_THRESHOLD = 20

heater = None
running = True


def handle_signal(signum, frame):
    global running
    running = False


def read_temperature():
    return random.randint(TEMP_MIN, TEMP_MAX - 1)


def control_heater(temperature):
    if temperature < HEATER_THRESHOLD:
        print("Heater ON")
        heater.on()
    else:
        print("Heater OFF")
        heater.off()


def cleanup():
    global heater
    if heater is not None:
        try:
            heater.off()
            heater.close()
        except Exception:
            pass
        heater = None


def main():
    global heater
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        heater = OutputDevice(HEATER_PIN)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO {HEATER_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO {HEATER_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not running:
                break
            temperature = read_temperature()
            print(f"Reading {i + 1}/{NUM_READINGS} - Temperature: {temperature}°C")
            control_heater(temperature)
            if i < NUM_READINGS - 1 and running:
                time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Error during readings: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

