import asyncio
import json
import logging
import signal
import sys
import threading
import time
from datetime import datetime

import aiohttp
import adafruit_dht
import board
from gpiozero import PWMLED

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
DHT_PIN = board.D4          # BCM GPIO4 (single-wire data line)
LED1_PINS = (17, 22, 27)    # BCM GPIO17 (red), GPIO22 (green), GPIO27 (blue)
LED2_PINS = (5, 6, 13)     # BCM GPIO5 (red), GPIO6 (green), GPIO13 (blue)
LED3_PINS = (19, 26, 16)   # BCM GPIO19 (red), GPIO26 (green), GPIO16 (blue)
CLOUD_ENDPOINT = "http://example.com/api/data"
READ_INTERVAL = 5           # seconds between sensor reads
RETRY_DELAY = 2             # seconds between retries on failure
ALERT_TEMP_MIN = 18.0
ALERT_TEMP_MAX = 28.0
ALERT_HUM_MIN = 30.0
ALERT_HUM_MAX = 80.0
PWM_FREQ = 1000             # Hz
PWM_MAX = 1.0               # gpiozero PWMLED value range is 0.0–1.0

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
    handlers=[
        logging.FileHandler("greenhouse_monitor.log"),
        logging.StreamHandler(sys.stdout),
    ],
)

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
stop_event = threading.Event()
latest_temp = None
latest_hum = None
leds = {}
pwm_lock = threading.Lock()


def _rgb_to_brightness(rgb):
    """Map (r, g, b) tuple (0-255) to brightness (0.0–1.0)."""
    return sum(rgb) / (3.0 * 255.0)


def _brightness_to_duty(brightness):
    """Map brightness (0.0–1.0) to PWM duty cycle (0.0–1.0)."""
    return max(0.0, min(1.0, brightness))


def _color_to_rgb(temp):
    """Map temperature to an RGB tuple (0-255, 0-255, 0-255)."""
    if temp is None:
        return (0, 0, 0)
    if temp > 28.0:
        return (255, 0, 0)   # Red
    if temp < 18.0:
        return (0, 0, 255)   # Blue
    return (0, 255, 0)       # Green


def _humidity_to_brightness(hum):
    """Map humidity to brightness (0.0–1.0)."""
    if hum is None:
        return 0.0
    return (hum - 30.0) / (80.0 - 30.0)


def _init_leds():
    """Create PWMLED objects for each channel."""
    global leds
    pins = [LED1_PINS, LED2_PINS, LED3_PINS]
    leds = {}
    for idx, pin in enumerate(pins):
        leds[idx + 1] = {
            "red": PWMLED(pin[0], frequency=PWM_FREQ, initial_value=0.0),
            "green": PWMLED(pin[1], frequency=PWM_FREQ, initial_value=0.0),
            "blue": PWMLED(pin[2], frequency=PWM_FREQ, initial_value=0.0),
        }
    logging.info("RGB LEDs initialised (1000 Hz PWM).")


def _set_leds(temp, hum):
    """Set all three LEDs from temperature and humidity."""
    rgb = _color_to_rgb(temp)
    brightness = _humidity_to_brightness(hum)
    duty = _brightness_to_duty(brightness)
    for led in leds.values():
        led["red"].value = rgb[0] / 255.0 * duty
        led["green"].value = rgb[1] / 255.0 * duty
        led["blue"].value = rgb[2] / 255.0 * duty
    logging.info(
        f"LEDs updated: temp={temp}°C, hum={hum}%, "
        f"RGB={rgb}, brightness={brightness:.2f}, duty={duty:.2f}"
    )


def _cleanup():
    """Turn off all LEDs and close PWM channels."""
    logging.info("Cleaning up GPIO resources...")
    for led in leds.values():
        for ch in led.values():
            try:
                ch.value = 0.0
                ch.close()
            except Exception as exc:
                logging.error(f"Error closing PWM channel: {exc}")
    logging.info("GPIO cleanup complete.")


def _signal_handler(signum, frame):
    logging.info(f"Signal {signum} received, initiating shutdown...")
    stop_event.set()


def _upload_task():
    """Background task: upload latest readings to cloud endpoint."""
    while not stop_event.is_set():
        temp = latest_temp
        hum = latest_hum
        alert = None

        if temp is not None and hum is not None:
            if not (ALERT_TEMP_MIN <= temp <= ALERT_TEMP_MAX):
                alert = "status: Temperature Alert"
            if not (ALERT_HUM_MIN <= hum <= ALERT_HUM_MAX):
                alert = "status: Humidity Alert" if alert else "status: Humidity Alert"

        payload = {
            "timestamp": datetime.now().isoformat(),
            "temperature": temp,
            "humidity": hum,
            "color": _color_to_rgb(temp),
            "brightness": _brightness_to_duty(_humidity_to_brightness(hum)),
        }
        if alert:
            payload["alert"] = alert

        try:
            async def _post():
                async with aiohttp.ClientSession() as session:
                    async with session.post(
                        CLOUD_ENDPOINT, json=payload, timeout=10
                    ) as resp:
                        logging.info(
                            f"Upload OK (HTTP {resp.status}). "
                            f"Payload: {payload}"
                        )
            asyncio.run(_post())
        except Exception as exc:
            logging.error(f"Upload failed: {exc}")

        # Wait 60 seconds, but wake early on stop_event
        stop_event.wait(60)


def _sensor_task():
    """Main sensor loop: read DHT22 with retries and update LEDs."""
    global latest_temp, latest_hum
    dht = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)

    while not stop_event.is_set():
        temp = None
        hum = None
        for attempt in range(3):
            if stop_event.is_set():
                break
            try:
                temp = dht.temperature
                hum = dht.humidity
                if temp is not None and hum is not None:
                    break
            except RuntimeError as exc:
                logging.warning(f"DHT22 read attempt {attempt + 1} failed: {exc}")
            except Exception as exc:
                logging.error(f"DHT22 unexpected error: {exc}")
            if attempt < 2:
                stop_event.wait(RETRY_DELAY)

        if temp is not None and hum is not None:
            latest_temp = temp
            latest_hum = hum
            logging.info(
                f"Sensor read OK: temp={temp:.1f}°C, hum={hum:.1f}%"
            )
            _set_leds(temp, hum)
        else:
            logging.error("Sensor read failed after 3 retries.")

        stop_event.wait(READ_INTERVAL)

    try:
        dht.exit()
    except Exception:
        pass
    logging.info("Sensor task stopped.")


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _init_leds()

    upload_thread = threading.Thread(target=_upload_task, daemon=True)
    sensor_thread = threading.Thread(target=_sensor_task, daemon=True)

    upload_thread.start()
    sensor_thread.start()

    try:
        while not stop_event.is_set():
            stop_event.wait(1)
    except KeyboardInterrupt:
        stop_event.set()
    finally:
        stop_event.set()
        upload_thread.join(timeout=5)
        sensor_thread.join(timeout=5)
        _cleanup()
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

