import time
import signal
import sys
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

FAN_PIN = 17
WAIT_TIME = 1
PWM_FREQUENCY = 25
HYSTERESIS = 1
THERMAL_ZONE_PATH = "/sys/class/thermal/thermal_zone0/temp"

fan = None
running = True


def get_cpu_temperature():
    try:
        with open(THERMAL_ZONE_PATH, "r") as f:
            return float(f.read().strip()) / 1000.0
    except (OSError, ValueError) as e:
        logging.error(f"Error reading CPU temperature: {e}")
        return None


def cleanup(signum=None, frame=None):
    global fan, running
    running = False
    if fan is not None:
        try:
            fan.close()
            logging.info("PWM stopped and GPIO released.")
        except Exception as e:
            logging.error(f"Error during cleanup: {e}")
    if signum is not None:
        sys.exit(0)


def main():
    global fan
    signal.signal(signal.SIGTERM, cleanup)
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY, initial_value=0)
        logging.info(f"PWM initialized on GPIO{FAN_PIN} at {PWM_FREQUENCY} Hz.")
    except Exception as e:
        logging.error(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}")
        sys.exit(1)

    fan_speed = 0
    try:
        while running:
            cpu_temp = get_cpu_temperature()
            if cpu_temp is None:
                time.sleep(WAIT_TIME)
                continue

            if cpu_temp > 45:
                fan_speed = 100
            elif cpu_temp > 40:
                fan_speed = 75
            elif cpu_temp > 35:
                fan_speed = 50
            elif cpu_temp > 30:
                fan_speed = 25
            else:
                fan_speed = 0

            if fan_speed != 0:
                fan.value = fan_speed / 100.0
                logging.info(f"Temperature: {cpu_temp:.1f}°C, Fan Speed: {fan_speed}%")
            else:
                fan.value = 0
                logging.info(f"Temperature: {cpu_temp:.1f}°C, Fan Speed: 0%")

            time.sleep(WAIT_TIME)
    except KeyboardInterrupt:
        logging.info("Fan control interrupted by user.")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

