import sys
import time
from datetime import datetime

LOG_FILE = "temp_log.txt"
READINGS = 10
DELAY = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _write_line(fh, line):
    fh.write(line + "\n")
    fh.flush()

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        import adafruit_dht
        from board import D4
        sensor = adafruit_dht.DHT22(D4, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on GPIO4: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(LOG_FILE, "a", encoding="utf-8") as fh:
            for i in range(READINGS):
                if not _running:
                    break
                try:
                    temp = sensor.temperature
                    if temp is None:
                        raise RuntimeError("sensor returned None")
                    line = datetime.now().strftime("%Y-%m-%d %H:%M:%S, temperature: %.2f C" % temp)
                except Exception as exc:
                    line = datetime.now().strftime("%Y-%m-%d %H:%M:%S, temperature: ERROR — %s" % exc)
                _write_line(fh, line)
                if i < READINGS - 1 and _running:
                    time.sleep(DELAY)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

