import time
import signal
import sys
import logging
from datetime import datetime

import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
LOG_FILE = '/home/pi/sensor_log.txt'
ALERT_PIN = 17
TEMP_THRESHOLD = 28.0
HUMIDITY_THRESHOLD = 65.0
ALERT_DURATION = 5.0

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s [%(levelname)s] %(message)s',
)
log = logging.getLogger('sensor')

_running = True


def _signal_handler(signum, frame):
    global _running
    log.info('Signal %s received – shutting down.', signum)
    _running = False


def _cleanup():
    try:
        GPIO.output(ALERT_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()
    log.info('GPIO cleaned up.')


def _open_serial():
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=1.0,
            write_timeout=2.0,
        )
    except serial.SerialException as exc:
        log.error('Cannot open %s: %s', SERIAL_PORT, exc)
        return None
    except Exception as exc:
        log.error('Unexpected error opening %s: %s', SERIAL_PORT, exc)
        return None


def _read_line(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        log.error('Serial read error: %s', exc)
        return None
    except Exception as exc:
        log.error('Unexpected read error: %s', exc)
        return None
    if not raw:
        return None
    try:
        return raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        log.error('Decode error: %s', exc)
        return None


def _parse(line):
    if not line:
        return None, None
    parts = line.split(',')
    if len(parts) != 2:
        log.warning('Malformed line ignored: %r', line)
        return None, None
    try:
