import signal
import sys
import time
import numpy as np
import matplotlib.pyplot as plt
from matplotlib import cm

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1.0
FRAME_WIDTH = 24
FRAME_HEIGHT = 32
EXPECTED_PIXELS = FRAME_WIDTH * FRAME_HEIGHT
UPDATE_INTERVAL = 0.1

_running = True
_api_call = None
_fig = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _api_call, _fig
    if _api_call is not None:
        try:
            _api_call.close()
        except Exception:
            pass
        _api_call = None
    if _fig is not None:
        try:
            plt.close(_fig)
        except Exception:
            pass
        _fig = None


def _parse_frame(raw):
    if not raw:
        return None
    try:
        parts = raw.split(",")
    except Exception:
        return None
    if len(parts) != EXPECTED_PIXELS:
        return None
    try:
        values = [float(p) for p in parts]
    except Exception:
        return None
    if len(values) != EXPECTED_PIXELS:
        return None
    return np.array(values, dtype=np.float32).reshape((FRAME_HEIGHT, FRAME_WIDTH))


def main():
    global _api_call, _fig, _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _api_call = open(SERIAL_PORT, "r", timeout=TIMEOUT)
    except Exception as exc:
        print(f"Error: cannot open serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        _fig, ax = plt.subplots(figsize=(8, 6))
        im = ax.imshow(
            np.zeros((FRAME_HEIGHT, FRAME_WIDTH), dtype=np.float32),
            cmap="inferno",
            interpolation="nearest",
            vmin=0.0,
            vmax=100.0,
        )
        ax.set_title("Thermal Imaging Frame")
        ax.set_xlabel("X")
        ax.set_ylabel("Y")
        plt.colorbar(im, ax=ax, label="Temperature (°C)")
        plt.tight_layout()
        plt.show(block=False)
    except Exception as exc:
        print(f"Error: failed to initialize plot: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    last_frame = None

    try:
        while _running:
            try:
                raw = _api_call.readline()
            except Exception as exc:
                print(f"Error: serial read failed: {exc}", file=sys.stderr)
                break

            if not raw:
                continue

            decoded = raw.decode("ascii", errors="replace").strip()
            if not decoded:
                continue

            frame = _parse_frame(decoded)
            if frame is None:
                print("Warning: malformed frame received, skipping.", file=sys.stderr)
                continue

            last_frame = frame
            im.set_data(frame)
            im.set_clim(vmin=frame.min(), vmax=frame.max())
            plt.draw()
            plt.pause(UPDATE_INTERVAL)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

