import signal
import sys
import time
from gpiozero import PWMOutputDevice

PWM_PIN = 18
PWM_FREQUENCY = 25000
TEMP_THRESHOLD = 40.0
LOW_POWER_DUTY = 20.0
HIGH_POWER_DUTY = 100.0
SAMPLE_INTERVAL = 5.0

fan = None
running = True

def cleanup(signum=None, frame=None):
    global running, fan
    running = False
    if fan is not None:
        try:
            fan.value = 0.0
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def read_cpu_temp():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (OSError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None

def main():
    global fan
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        fan = PWMOutputDevice(PWM_PIN, frequency=PWM_FREQUENCY, initial_value=0.0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{PWM_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        while running:
            temp = read_cpu_temp()
            if temp is not None:
                duty = HIGH_POWER_DUTY if temp > TEMP_THRESHOLD else LOW_POWER_DUTY
                fan.value = duty / 100.0
                print(f"CPU Temp: {temp:.1f}°C, Fan Duty: {duty:.0f}%")
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

