import time
import random
import logging
import logging.handlers
import signal
import sys
import os
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

# Constants
DHT_PIN = 4
LOG_FILE = '/var/log/wearable'
TEMP_MIN, TEMP_MAX = 10, 55
HUM_MIN, HUM_MAX = 20, 100
READ_INTERVAL = 5
MAX_RETRIES = 3
RETRY_DELAY = 1
LOG_BACKUP_COUNT = 7

# Global state
_running = True
_logger = None


def _setup_logging():
    """Configure file and console logging with daily rotation."""
    global _logger
    log_dir = LOG_FILE
    if not os.path.exists(log_dir):
        log_dir = os.path.join(os.path.expanduser('~'), '.local', 'log', 'wearable')
        os.makedirs(log_dir, exist_ok=True)
    log_file = os.path.join(log_dir, 'wearable.log')
    logger = logging.getLogger('wearable')
    logger.setLevel(logging.INFO)
    logger.handlers.clear()
    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    try:
        file_handler = logging.handlers.TimedRotatingFileHandler(
            log_file, when='midnight', interval=1, backupCount=LOG_BACKUP_COUNT
        )
        file_handler.setFormatter(formatter)
        logger.addHandler(file_handler)
    except (PermissionError, OSError) as e:
        print(f'Failed to open log file {log_file}: {e}', file=sys.stderr)
        return None
    console_handler = logging.StreamHandler()
    console_handler.setFormatter(formatter)
    logger.addHandler(console_handler)
    _logger = logger
    return logger


def _cleanup_gpio():
    """Release GPIO resources if available."""
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _read_simulated_sensor():
    """Simulate a DHT22 reading with random values."""
    temperature = random.uniform(15, 45)
    humidity = random.uniform(40, 95)
    return temperature, humidity


def _validate_reading(temperature, humidity):
    """Validate temperature and humidity ranges."""
    if not (TEMP_MIN <= temperature <= TEMP_MAX):
        return False, f'Temperature out of range: {temperature:.2f}°C'
    if not (HUM_MIN <= humidity <= HUM_MAX):
        return False, f'Humidity out of range: {humidity:.2f}%'
    return True, None


def _log_event(logger, level, message):
    """Log an event with the given level."""
    if logger is not None:
        logger.log(level, message)


def main():
    """Main loop: simulate sensor readings, validate, log, and handle errors."""
    global _logger, _running

    logger = _setup_logging()
    if logger is None:
        print('Failed to initialize logging. Exiting.', file=sys.stderr)
        return

    _log_event(logger, logging.INFO, 'Wearable simulation started.')

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if GPIO is not None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        except Exception as e:
            _log_event(logger, logging.ERROR, f'GPIO setup failed: {e}')
            _cleanup_gpio()
            _log_event(logger, logging.INFO, 'Wearable simulation stopped.')
            return

    try:
        while _running:
            temperature, humidity = None, None
            for attempt in range(1, MAX_RETRIES + 1):
                if not _running:
                    break
                try:
                    temperature, humidity = _read_simulated_sensor()
                    if temperature is not None and humidity is not None:
                        break
                except Exception as e:
                    _log_event(logger, logging.ERROR, f'Reading error (attempt {attempt}/{MAX_RETRIES}): {e}')
                if attempt < MAX_RETRIES:
                    time.sleep(RETRY_DELAY)

            if temperature is None or humidity is None:
                _log_event(logger, logging.ERROR, 'Failed to read sensor after multiple retries.')
                if _running:
                    time.sleep(READ_INTERVAL)
                continue

            is_valid, error = _validate_reading(temperature, humidity)
            if is_valid:
                timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                log_msg = f'Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%, Timestamp: {timestamp}'
                _log_event(logger, logging.INFO, log_msg)
            else:
                _log_event(logger, logging.ERROR, f'Invalid reading: {error}')

            if _running:
                time.sleep(READ_INTERVAL)

    except TypeError as e:
        _log_event(logger, logging.ERROR, f'Type error: {e}')
    except ValueError as e:
        _log_event(logger, logging.ERROR, f'Value error: {e}')
    except OSError as e:
        _log_event(logger, logging.ERROR, f'OS error: {e}')
    except Exception as e:
        _log_event(logger, logging.ERROR, f'Unexpected error: {e}')
    finally:
        _log_event(logger, logging.INFO, 'Wearable simulation stopped.')
        for handler in list(logger.handlers):
            try:
                handler.close()
            except Exception:
                pass
            logger.removeHandler(handler)
        _cleanup_gpio()


if __name__ == '__main__':
    main()

