    except OSError as e:
        _log_event(logger, logging.ERROR, f'OS error: {e}')
    except Exception as e:
        _log_event(logger, logging.ERROR, f'Unexpected error: {e}')
    finally:
        _log_event(logger, logging.INFO, 'Wearable simulation stopped.')
        for handler in list(logger.handlers):
            try:
                handler.close()
            except Exception:
                pass
            logger.removeHandler(handler)
        _cleanup_gpio()


if __name__ == '__main__':
    main()

