try:
    import RPi.GPIO as GPIO
except RuntimeError as e:
    print(f"Failed to import RPi.GPIO: {e}")
    print("Ensure this script is running on a Raspberry Pi with proper permissions.")
    sys.exit(1)

LED_PIN = 17
led_state = False
_running = True

def cleanup_gpio():
    """Drive the LED low and release the GPIO pin."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup(LED_PIN)
    except Exception:
        pass

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False

def main():
    global led_state, _running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        print("Ensure you have proper permissions (e.g., run with sudo) and the pin is not already in use.")
        sys.exit(1)

    try:
        while _running:
            try:
                user_input = input("Enter 'on', 'off', or 'exit': ").strip().lower()
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input == "on":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
            elif user_input == "off":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
            elif user_input == "exit":
                print("Exiting program.")
                break
            else:
                print("Invalid input")

            print(f"LED state: {led_state}")
            time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

