_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in SENSOR_PINS:
            try:
                GPIO.setup(pin, GPIO.IN, pull_up_up=True)
            except Exception as exc:
                print(f"Error: failed to configure GPIO{pin}: {exc}", file=sys.stderr)
                GPIO.cleanup()
                return 1

        print(f"Monitoring GPIO{SENSOR_PINS[0]}, GPIO{SENSOR_PINS[1]}, GPIO{SENSOR_PINS[2]} "
              f"every {POLL_INTERVAL:.1f} s. Press Ctrl+C to exit.")

        while _running:
            try:
                for i, pin in enumerate(SENSOR_PINS, 1):
                    try:
                        if GPIO.input(pin):
                            print(f"Response for sensor {i}")
                    except Exception as exc:
                        print(f"Error reading GPIO{pin}: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Unexpected error during polling: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
        return 1
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

