import sys
import time
import signal
import threading
import traceback

try:
    import DOG
except ImportError as exc:
    print(f"Error: DOG library not found: {exc}", file=sys.stderr)
    sys.exit(1)

DOG_API = None
RECEIVE_THREAD = None
LOG_FILE_PATH = None
LOG_FILE = None
RUNNING = True


def _cleanup(signum=None, frame=None):
    """Signal-safe cleanup: stop the receive thread, close the log file,
    release the DOG library API, and exit."""
    global RUNNING, DOG_API, LOG_FILE, RECEIVE_THREAD
    RUNNING = False
    if RECEIVE_THREAD is not None and RECEIVE_THREAD.is_alive():
        RECEIVE_THREAD.join(timeout=2.0)
    if LOG_FILE is not None:
        try:
            LOG_FILE.close()
        except Exception:
            pass
        LOG_FILE = None
    if DOG_API is not None:
        try:
            DOG.stop()
        except Exception:
            pass
        DOG_API = None
    if signum is not None:
        sys.exit(0)


def _help(*args):
    """Displays help information for the given command or general usage."""
    if not args:
        print("Available commands: start, stop, help, display, send, write, exit")
    elif args[0] == "start":
        print("Starts logging to a file. Usage: start <filename>")
    elif args[0] == "stop":
        print("Stops the logging process.")
    elif args[0] == "help":
        print("Displays help information. Usage: help [command]")
    elif args[0] == "display":
        print("Displays the contents of the log file.")
    elif args[0] == "send":
        print("Sends data to the device. Usage: send <data>")
    elif args[0] == "write":
        print("Writes data directly to the log file. Usage: write <data>")
    else:
        print(f"Unknown command: {args[0]}")


def _start(*args):
    """Starts the logging process by creating a file and starting the receive thread."""
    global LOG_FILE_PATH, LOG_FILE, DOG_API, RECEIVE_THREAD
    if DOG_API is not None:
        print("Logging already started.")
        return
    if not args or not args[0]:
        print("Error: Missing filename. Usage: start <filename>")
        return
    LOG_FILE_PATH = args[0]
    try:
        LOG_FILE = open(LOG_FILE_PATH, "a")
    except OSError as e:
        print(f"Error opening file '{LOG_FILE_PATH}': {e}", file=sys.stderr)
        LOG_FILE = None
        return
    try:
        DOG.start()
        DOG_API = DOG
    except Exception as e:
        print(f"Error starting DOG API: {e}", file=sys.stderr)
        try:
            LOG_FILE.close()
        except Exception:
            pass
        LOG_FILE = None
        return
    RECEIVE_THREAD = threading.Thread(target=_receive_data, daemon=True)
    RECEIVE_THREAD.start()


def _receive_data():
    """Continuously receives data from the DOG device and logs it to the file."""
    global RUNNING
    while RUNNING:
        try:
            data = DOG.receive()
            if data is not None:
                try:
                    LOG_FILE.write(data + "\n")
                    LOG_FILE.flush()
                except OSError as e:
                    print(f"Error writing to log file: {e}", file=sys.stderr)
        except Exception as e:
            print(f"Error receiving data: {e}", file=sys.stderr)
        time.sleep(0.1)


def _stop(*args):
    """Stops the logging process and releases resources."""
    global DOG_API, LOG_FILE, RECEIVE_THREAD
    if DOG_API is None:
        print("Logging not started.")
        return
    try:
        DOG.stop()
    except Exception as e:
        print(f"Error stopping DOG API: {e}", file=sys.stderr)
    DOG_API = None
    if LOG_FILE is not None:
        try:
            LOG_FILE.close()
        except Exception as e:
            print(f"Error closing log file: {e}", file=sys.stderr)
        LOG_FILE = None
    if RECEIVE_THREAD is not None and RECEIVE_THREAD.is_alive():
        RECEIVE_THREAD.join(timeout=2.0)
    RECEIVE_THREAD = None


def _display(*args):
    """Displays the contents of the log file."""
    global LOG_FILE
    if LOG_FILE is None:
        print("Log file not open.")
        return
    try:
        with open(LOG_FILE.name, "r") as f:
            print(f.read(), end="")
    except OSError as e:
        print(f"Error reading log file: {e}", file=sys.stderr)


def _send(*args):
    """Sends data to the DOG device."""
    if DOG_API is None:
        print("Logging not started.")
        return
    if not args or not args[0]:
        print("Error: Missing data. Usage: send <data>")
        return
    try:
        DOG.send(" ".join(args))
    except Exception as e:
        print(f"Error sending data: {e}", file=sys.stderr)


def _write(*args):
    """Writes data directly to the log file."""
    global LOG_FILE
    if LOG_FILE is None:
        print("Log file not open.")
        return
    if not args or not args[0]:
        print("Error: Missing data. Usage: write <data>")
        return
    try:
        LOG_FILE.write(" ".join(args) + "\n")
        LOG_FILE.flush()
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)


def _exit(*args):
    """Exits the program."""
    _cleanup()


COMMANDS = {
    "start": _start,
    "stop": _stop,
    "help": _help,
    "display": _display,
    "send": _send,
    "write": _write,
    "exit": _exit,
}


def run():
    """Main function to run the command-line interface."""
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)
    while RUNNING:
        try:
            line = input("> ")
        except EOFError:
            break
        except KeyboardInterrupt:
            break
        parts = line.split()
        if not parts:
            continue
        command = parts[0].lower()
        args = parts[1:]
        try:
            COMMANDS[command](*args)
        except KeyError:
            print(f"Unknown command: {command}")
        except Exception as e:
            print(f"An error occurred: {e}", file=sys.stderr)
            traceback.print_exc(file=sys.stderr)
    _cleanup()


if __name__ == "__main__":
    run()

