import signal
import sys
import time

try:
    from smbus2 import SMBus, i2c_msg
except ImportError:
    from smbus import SMBus
    i2c_msg = None

BH1750_ADDR = 0x23
BH1750_CMD_POWER_ON = 0x01
BH1750_CMD_RESET = 0x07
BH1750_CMD_CONTINUOUS_HIGH_RES_MODE = 0x10

I2C_BUS = 1
I2C_FREQ = 400000
MEASUREMENT_DELAY = 0.12
READ_INTERVAL = 3.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_msg(bus, addr, cmd):
    if i2c_msg is not None:
        write = i2c_msg.write(addr, [cmd])
        bus.i2c_rdwr(write)
    else:
        bus.write_byte(addr, cmd)


def _read_msg(bus, addr, length):
    if i2c_msg is not None:
        read = i2c_msg.read(addr, length)
        bus.i2c_rdwr(read)
        return list(read)
    else:
        return bus.read_i2c_block_data(addr, 0x00, length)


def _init_sensor(bus, addr):
    _write_msg(bus, addr, BH1750_CMD_POWER_ON)
    time.sleep(0.01)
    _write_msg(bus, addr, BH1750_CMD_RESET)
    time.sleep(0.01)
    _write_msg(bus, addr, BH1750_CMD_CONTINUOUS_HIGH_RES_MODE)
    time.sleep(0.18)


def read_illuminance(bus, addr):
    _write_msg(bus, addr, BH1750_CMD_CONTINUOUS_HIGH_RES_MODE)
    time.sleep(MEASUREMENT_DELAY)
    data = _read_msg(bus, addr, 2)
    raw = (data[0] << 8) | data[1]
    return raw / 1.2


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
        bus.i2c_rdwr(i2c_msg.read(BH1750_ADDR, 1))
        print(f"I2C bus {I2C_BUS} initialized at {I2C_FREQ} Hz.")
    except OSError as e:
        print(f"Error initializing I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        return 1

    try:
        try:
            _init_sensor(bus, BH1750_ADDR)
        except OSError as e:
            print(f"Error initializing BH1750 at 0x{BH1750_ADDR:02X}: {e}", file=sys.stderr)
            return 1

        print("BH1750 initialized. Reading illuminance every 3 seconds (Ctrl+C to stop).")

        while _running:
            try:
                lux = read_illuminance(bus, BH1750_ADDR)
                print(f"Illuminance: {lux:.2f} lx")
            except OSError as e:
                print(f"I2C communication error: {e}", file=sys.stderr)
            except Exception as e:
                print(f"Unexpected error reading sensor: {e}", file=sys.stderr)

            time.sleep(READ_INTERVAL)

    finally:
        if bus is not None:
            try:
                bus.close()
                print("I2C bus closed.")
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

