import time
import signal
import logging
import zmq
import threading
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None
    logging.error("RPi.GPIO not available. Are you running on a Raspberry Pi?")
except ImportError:
    GPIO = None
    logging.error("RPi.GPIO not found. Install with: pip install RPi.GPIO")

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class PIDHandler:
    """
    Manages PID error outputs via PWM on physical pin 12 (BCM GPIO 18) and
    a digital output on physical pin 10 (BCM GPIO 15) using BOARD numbering.
    """

    def __init__(self, pwm_pin=12, digital_pin=10, pwm_freq=1000, watchdog_timeout=20.0):
        self.pwm_pin = pwm_pin
        self.digital_pin = digital_pin
        self.pwm_freq = pwm_freq
        self.watchdog_timeout = watchdog_timeout
        self.global_err_state = False
        self.last_msg = time.time()
        self.subscriptions = {}
        self.subscription_lock = threading.Lock()
        self._running = True
        self._pwm = None
        self._digital = None

        if GPIO is None:
            logging.error("GPIO library unavailable; cannot initialize hardware.")
            return

        try:
            GPIO.setmode(GPIO.BOARD)
            GPIO.setwarnings(False)
            self._setup_gpio()
            logging.info("PIDHandler initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing GPIO: {e}")
            self.cleanup()
            raise

    def _setup_gpio(self):
        try:
            GPIO.setup(self.pwm_pin, GPIO.OUT)
            GPIO.setup(self.digital_pin, GPIO.OUT)
            GPIO.output(self.pwm_pin, GPIO.LOW)
            GPIO.output(self.digital_pin, GPIO.LOW)
        except Exception as e:
            logging.error(f"Error setting up GPIO pins: {e}")
            raise

    def update_error_output(self, state):
        if self._pwm is not None:
            try:
                self._pwm.ChangeDutyCycle(state * 100)
            except Exception as e:
                logging.error(f"Error updating PWM duty cycle: {e}")
        if self._digital is not None:
            try:
                GPIO.output(self.digital_pin, GPIO.HIGH if state else GPIO.LOW)
            except Exception as e:
                logging.error(f"Error setting digital output: {e}")

    def set_error_output(self, state):
        self.global_err_state = bool(state)
        self.update_error_output(state)

    def handle_message(self, data):
        if data is None:
            return
        self.last_msg = time.time()
        if not self.global_err_state:
            self.set_error_output(False)
        with self.subscription_lock:
            for topic, callback in self.subscriptions.items():
                if topic in data:
                    try:
                        callback(data[topic])
                    except Exception as e:
                        logging.error(f"Error handling callback for topic {topic}: {e}")

    def subscribe(self, topic, callback):
        with self.subscription_lock:
            self.subscriptions[topic] = callback

    def unsubscribe(self, topic):
        with self.subscription_lock:
            if topic in self.subscriptions:
                del self.subscriptions[topic]

    def _watchdog_check(self):
        if self.global_err_state:
            return
        if time.time() - self.last_msg > self.watchdog_timeout:
            logging.warning("Watchdog timeout triggered!")
            self.set_error_output(True)

    def run(self, context, in_socket, out_socket, pwm=True):
        self._pwm = self._pwm if pwm else None
        self._digital = self._pwm if not pwm else None
        if self._pwm is not None:
            try:
                self._pwm = GPIO.PWM(self.pwm_pin, self.pwm_freq)
                self._pwm.start(0)
            except Exception as e:
                logging.error(f"Error initializing PWM: {e}")
                self._pwm = None
        if self._digital is not None:
            try:
                GPIO.output(self.digital_pin, GPIO.LOW)
            except Exception as e:
                logging.error(f"Error setting digital pin: {e}")
                self._digital = None
        self.set_error_output(False)
        self.last_msg = time.time()
        while self._running:
            try:
