# fingerprint_authentication_rpi.py
# Raspberry Pi 5 fingerprint authentication system using an Adafruit Fingerprint sensor over I2C.
# Wiring: Adafruit Fingerprint sensor SDA -> GPIO 2 (board.SDA), SCL -> GPIO 3 (board.SCL), VCC -> 3.3V, GND -> GND

import time
import board
import busio
import adafruit_fingerprint

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Toggle the running flag on SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


import signal
signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


def authenticate_fingerprint(i2c_bus):
    """
    Authenticates a fingerprint against a pre-loaded database.

    Args:
        i2c_bus: An initialized busio.I2C object.

    Returns:
        True if authentication is successful, False otherwise.
    """
    try:
        sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
    except ValueError as e:
        print(f"Error: I2C bus is locked or sensor not detected - {e}")
        return False
    except RuntimeError as e:
        print(f"Error: Sensor communication failure - {e}")
        return False
    except Exception as e:
        print(f"Unexpected error initializing fingerprint sensor - {e}")
        return False

    try:
        print("Waiting for fingerprint...")
        while _running:
            try:
                ret = sensor.get_image()
            except RuntimeError as e:
                print(f"Error: Sensor communication failure - {e}")
                time.sleep(1)
                continue

            if ret == adafruit_fingerprint.OK:
                print("Image taken")
                break
            elif ret == adafruit_fingerprint.NOFINGER:
                print(".", end="", flush=True)
                time.sleep(0.1)
            else:
                print(f"Error: get_image() returned {ret}")
                return False

        if not _running:
            return False

        try:
            sensor.image_2_tz(1)
        except RuntimeError as e:
            print(f"Error: Sensor communication failure - {e}")
            return False

        try:
            result = sensor.finger_search()
        except RuntimeError as e:
            print(f"Error: Sensor communication failure - {e}")
            return False

        if result == adafruit_fingerprint.OK:
            print("Found fingerprint!")
            print("ID:", result[0], "with confidence:", result[1])
            return True
        elif result == adafruit_fingerprint.NOTFOUND:
            print("Access Denied")
            return False
        else:
            print(f"Error: finger_search() returned {result}")
            return False

    except Exception as e:
        print(f"An unexpected error occurred during authentication: {e}")
        return False


def main():
    """Main function to run the fingerprint authentication loop."""
    i2c = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        print("I2C bus initialized.")

        while _running:
            if authenticate_fingerprint(i2c):
                print("Access Granted")
            else:
                print("Access Denied")

            if _running:
                time.sleep(1)

    except ValueError as e:
        print(f"Error: I2C bus is locked or sensor not detected - {e}")
    except RuntimeError as e:
        print(f"Error: Sensor communication failure - {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        print("Exiting program.")


if __name__ == "__main__":
    main()

