import time
import signal
import sys
import atexit
from PIL import Image, ImageDraw, ImageFont

try:
    import spidev
except ImportError:
    spidev = None

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None


# ---- Pin assignments (BCM numbering) ----
PIN_DC = 22
PIN_RST = 18
PIN_LED = 23
SPI_BUS = 0
SPI_DEVICE = 0


class TFTDisplay:
    """Minimal ST7735 driver for a 1.44-inch 128x128 TFT display over SPI."""

    def __init__(self, spi_bus=SPI_BUS, spi_device=SPI_DEVICE,
                 dc=PIN_DC, rst=PIN_RST, led=PIN_LED):
        self._spi = None
        self._gpio = GPIO is not None
        self._dc = dc
        self._rst = rst
        self._led = led
        self._width = 128
        self._height = 128
        self._colors = {
            'white': (self._color565(255, 255, 255)),
            'red': (self._color565(255, 0, 0)),
            'blue': (self._color565(0, 0, 255)),
            'black': (self._color565(0, 0, 0)),
        }
        self._font_files = {
            1: '/usr/share/fonts/DejaVuSans.ttf',
            2: '/usr/share/fonts/DejaVuSans-Bold.ttf',
            3: '/usr/share/fonts/DejaVuSansMono.ttf',
            4: '/usr/share/fonts/DejaVuSansMono-Bold.ttf',
            5: '/usr/share/fonts/DejaVuSansCondensed.ttf',
            6: '/usr/share/fonts/DejaVuSansCondensed-Bold.ttf',
            7: '/usr/share/fonts/DejaVuSansExtraLight.ttf',
            8: '/usr/share/fonts/DejaVuSansExtraLight-Bold.ttf',
        }
        self._fonts = {}
        self._image = None
        self._draw = None

        # --- GPIO setup (if available) ---
        if self._gpio:
            GPIO.setwarnings(False)
            GPIO.setmode(GPIO.BCM)
            for pin in (self._dc, self._rst, self._led):
                GPIO.setup(pin, GPIO.OUT)
            GPIO.output(self._led, GPIO.HIGH)   # backlight on
            GPIO.output(self._rst, GPIO.HIGH)    # not reset
            GPIO.output(self._dc, GPIO.LOW)      # command mode

        # --- SPI setup ---
        if spidev is not None:
            self._spi = spidev.SpiDev()
            try:
                self._spi.open(spi_bus, spi_device)
                self._spi.max_speed_hz = 32_000_000
                self._spi.mode = 0
            except Exception as exc:
                print(f"Error: cannot open SPI bus {spi_bus} device {spi_device}: {exc}")
                self._spi = None
        else:
            print("Error: spidev library not available; cannot open SPI.")

        # --- Font loading ---
        for fid, path in self._font_files.items():
            try:
                self._fonts[fid] = ImageFont.truetype(path, 16)
            except Exception as exc:
                print(f"Warning: could not load font {fid} from {path}: {exc}")

        # --- Hardware reset ---
        if self._gpio:
            GPIO.output(self._rst, GPIO.LOW)
            time.sleep(0.01)
            GPIO.output(self._rst, GPIO.HIGH)
            time.sleep(0.05)

        # --- ST7735 init sequence (90° orientation) ---
        self._write_cmd(0x11)          # Sleep out
        time.sleep(0.12)
        self._write_cmd(0x3A)          # COLMOD: 16-bit/pixel
        self._write_data(0x05)
        self._write_cmd(0x36)          # MADCTL: 90°
        self._write_data(0xC8)
        self._write_cmd(0x21)          # Invert on
        self._write_cmd(0x13)          # NORON
        time.sleep(0.01)
        self._write_cmd(0x29)          # Display on
        time.sleep(0.05)

        self.clear_display(self._colors['black'])
        self._image = Image.new('RGB', (self._width, self._height))
        self._draw = ImageDraw.Draw(self._image)

    # -- Low-level helpers --
    def _write_cmd(self, value):
        if self._gpio:
            GPIO.output(self._dc, GPIO.LOW)
        if self._spi:
            self._spi.writebytes([value])

    def _write_data(self, value):
        if self._gpio:
            GPIO.output(self._dc, GPIO.HIGH)
        if self._spi:
            self._spi.writebytes([value])

    def _color565(self, r, g, b):
        return ((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3)

    # -- Display control --
    def clear_display(self, color):
        if self._image is None:
            return
        self._draw.rectangle((0, 0, self._width - 1, self._height - 1), fill=color)
        self.display_image(self._image)

    def display_image(self, image):
        if self._spi is None:
            return
        buf = bytearray(self._width * self._height * 2)
        pixels = image.load()
        for y in range(self._height):
            for x in range(self._width):
                rgb = pixels[x, y]
                buf[y * self._width * 2 + x * 2] = self._color565(rgb[0], rgb[1], rgb[2]) & 0xFF
                buf[y * self._width * 2 + x * 2 + 1] = (self._color565(rgb[0], rgb[1], rgb[2]) >> 8) & 0xFF
        self._write_cmd(0x2A)          # CASET
        self._write_data(0x00)
        self._write_data(0x00)
        self._write_data(0x00)
        self._write_data(self._width - 1)
        self._write_cmd(0x2B)          # RASET
        self._write_data(0x00)
        self._write_data(0x00)
        self._write_data(0x00)
        self._write_data(self._height - 1)
        self._write_cmd(0x2C)          # RAMWR
        for i in range(0, len(buf), 4096):
            chunk = buf[i:i + 4096]
            if self._gpio:
                GPIO.output(self._dc, GPIO.HIGH)
            if self._spi:
                self._spi.writebytes(list(chunk))

    # -- Cleanup --
    def close(self):
        if self._spi is not None:
            try:
                self._spi.close()
            except Exception:
                pass
            self._spi = None
        if self._gpio:
            try:
                GPIO.output(self._led, GPIO.LOW)
            except Exception:
                pass
            try:
                GPIO.cleanup()
            except Exception:
                pass

    def __del__(self):
        self.close()


# ---- Globals for signal handling ----
_display = None


def _cleanup():
    if _display is not None:
        _display.close()


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}; exiting.")
    _cleanup()
    sys.exit(0)


def main():
    global _display
    _display = TFTDisplay()

    atexit.register(_cleanup)
    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)

    colors = ['red', 'blue', 'white', 'black']
    try:
        for color in colors:
            _display.clear_display(_display._colors[color])
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as exc:
        print(f"Error during background color cycle: {exc}")
    finally:
        _cleanup()


if __name__ == '__main__':
    main()

