import signal
import sys

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO is not available. Are you running on a Raspberry Pi?")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000
running = True


def cleanup():
    """Stop PWM and release GPIO resources."""
    global running
    running = False
    try:
        if GPIO.getmode() is not None:
            GPIO.output(FAN_PIN, GPIO.LOW)
            GPIO.cleanup()
    except Exception:
        pass


def handle_signal(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global running
    running = False


def main():
    global running

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    try:
        GPIO.setup(FAN_PIN, GPIO.OUT)
    except Exception as e:
        print(f"Failed to initialize GPIO{FAN_PIN}: {e}")
        GPIO.cleanup()
        sys.exit(1)

    pwm = None
    try:
        pwm = GPIO.PWM(FAN_PIN, PWM_FREQ)
        pwm.start(0)
    except Exception as e:
        print(f"Warning: could not initialize hardware PWM on GPIO{FAN_PIN} "
              f"at {PWM_FREQ} Hz: {e}")
        print("Falling back to software PWM. Continuing...")

    try:
        while running:
            try:
                raw = input("Enter fan speed (0-100, or 'q' to quit): ")
            except EOFError:
                break

            if raw.strip().lower() == "q":
                break

            try:
                speed = float(raw)
            except ValueError:
                print("Invalid input. Please enter a number between 0 and 100, or 'q'.")
                continue

            if not 0.0 <= speed <= 100.0:
                print("Invalid input. Please enter a number between 0 and 100, or 'q'.")
                continue

            try:
                if pwm is not None:
                    pwm.ChangeDutyCycle(speed)
                else:
                    GPIO.output(FAN_PIN, GPIO.HIGH if speed > 0 else GPIO.LOW)
            except Exception as e:
                print(f"Error setting fan speed: {e}")

    except KeyboardInterrupt:
        pass
    finally:
        cleanup()


if __name__ == "__main__":
    main()

