#!/usr/bin/env python3
"""3-bit binary counter on a Pimoroni Rainbow HAT with touchpads A/B/C.

Touchpad A (GPIO5)  -> MSB  (value 4)
Touchpad B (GPIO6)  -> middle bit (value 2)
Touchpad C (GPIO12) -> LSB  (value 1)

Discrete LEDs, 14-segment display, APA102 LED strip, buzzer, and
onboard green/blue LEDs are all driven atomically on every toggle.
"""

import signal
import sys
import time

# ---------------------------------------------------------------------------
# Optional imports — degrade gracefully if hardware is absent
# ---------------------------------------------------------------------------
try:
    import rainbowhat as rh
    _HAS_RAINBOW_HAT = True
except Exception as exc:  # pragma: no cover
    print(f"Warning: rainbowhat import failed ({exc}); running in stub mode.",
          file=sys.stderr)
    _HAS_RAINBOW_HAT = False

try:
    import RPi.GPIO as GPIO
    _HAS_GPIO = True
except Exception as exc:  # pragma: no cover
    print(f"Warning: RPi.GPIO import failed ({exc}); running in stub mode.",
          file=sys.stderr)
    _HAS_GPIO = False

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
TOUCH_A_PIN = 5   # BCM 5  -> touchpad A (MSB)
TOUCH_B_PIN = 6   # BCM 6  -> touchpad B (middle bit)
TOUCH_C_PIN = 12  # BCM 12 -> touchpad C (LSB)

APA102_DATA_PIN = 10   # BCM 10
APA102_CLOCK_PIN = 11  # BCM 11

BUZZER_PIN = 13       # BCM 13
GREEN_LED_PIN = 7     # BCM 7
BLUE_LED_PIN = 8      # BCM 8

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
bit_states = [False, False, False]
_running = True


def _cleanup():
    """Turn everything off and release resources."""
    try:
        if _HAS_RAINBOW_HAT:
            rh.display.clear()
            rh.display.show()
    except Exception as exc:
        print(f"Error clearing display: {exc}", file=sys.stderr)

    try:
        if _HAS_RAINBOW_HAT:
            rh.lights.rgb(0, 0, 0)
    except Exception as exc:
        print(f"Error clearing lights: {exc}", file=sys.stderr)

    try:
        if _HAS_RAINBOW_HAT:
            rh.disco.clear()
            rh.disco.show()
    except Exception as exc:
        print(f"Error clearing disco: {exc}", file=sys.stderr)

    try:
        if _HAS_GPIO:
            GPIO.output(BUZZER_PIN, GPIO.LOW)
            GPIO.output(GREEN_LED_PIN, GPIO.LOW)
            GPIO.output(BLUE_LED_PIN, GPIO.LOW)
    except Exception as exc:
        print(f"Error controlling GPIO outputs: {exc}", file=sys.stderr)

    try:
        if _HAS_RAINBOW_HAT:
            rh.apa102.clear()
            rh.apa102.show()
    except Exception as exc:
        print(f"Error clearing APA102: {exc}", file=sys.stderr)

    try:
        if _HAS_GPIO:
            GPIO.cleanup()
    except Exception as exc:
        print(f"Error during GPIO cleanup: {exc}", file=sys.stderr)


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global _running
    _running = False


def _setup_gpio():
    """Configure GPIO pins for the buzzer, green LED, blue LED, and APA102."""
    if not _HAS_GPIO:
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(BUZZER_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(GREEN_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(BLUE_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as exc:
        print(f"Error setting up GPIO: {exc}", file=sys.stderr)


def _setup_rainbow_hat():
    """Initialize the Rainbow HAT peripherals."""
    if not _HAS_RAINBOW_HAT:
        return
    try:
        rh.display.clear()
        rh.display.show()
    except Exception as exc:
        print(f"Error initializing display: {exc}", file=sys.stderr)

    try:
        rh.lights.rgb(0, 0, 0)
    except Exception as exc:
        print(f"Error initializing lights: {exc}", file=sys.stderr)

    try:
        rh.disco.clear()
        rh.disco.show()
    except Exception as exc:
        print(f"Error initializing disco: {exc}", file=sys.stderr)

    try:
        rh.apa102.clear()
        rh.apa102.show()
    except Exception as exc:
        print(f"Error initializing APA102: {exc}", file=sys.stderr)


def _update_discrete_leds():
    """Set the three discrete LEDs according to bit_states."""
    if not _HAS_RAINBOW_HAT:
        return
    try:
        rh.lights.set_led(0, 0, 0, 0)
        rh.lights.set_led(1, 0, 0, 0)
        rh.lights.set_led(2, 0, 0, 0)
        if bit_states[0]:
            rh.lights.set_led(0, 255, 0, 0)
        if bit_states[1]:
            rh.lights.set_led(1, 0, 255, 0)
        if bit_states[2]:
            rh.lights.set_led(2, 0, 0, 255)
    except Exception as exc:
        print(f"Error updating discrete LEDs: {exc}", file=sys.stderr)


def _update_14seg(value):
    """Write a decimal value (0-7) to the 14-segment display."""
    if not _HAS_RAINBOW_HAT:
        return
    try:
        rh.display.clear()
        rh.display.print_float(value)
        rh.display.show()
    except Exception as exc:
        print(f"Error updating 14-segment display: {exc}", file=sys.stderr)


def _update_apa102(value):
    """Drive the APA102 LED strip according to the current value.

    Value 0  -> dim white pixel at index 0
    Value 7  -> all seven pixels white
    Otherwise -> a single pixel at index value is colored red/green/blue
                 according to the states of A, B, C.
    """
    if not _HAS_RAINBOW_HAT:
        return
    try:
        rh.apa102.clear()
        if value == 0:
            rh.apa102.set_pixel(0, 255, 255, 0, 0)
        elif value == 7:
            for i in range(7):
                rh.apa102.set_pixel(i, 255, 255, 255, 0)
        else:
            r = 255 if bit_states[0] else 0
            g = 255 if bit_states[1] else 0
            b = 255 if bit_states[2] else 0
            rh.apa102.set_pixel(value, r, g, b, 0)
        rh.apa102.show()
    except Exception as exc:
