    _setup_rainbow_hat()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not _HAS_RAINBOW_HAT:
        print("Running in stub mode — no touch events will be processed.",
