import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

LED_PIN = 17
ON_DURATION = 1.0
OFF_DURATION = 1.0

led = None


def turn_on_led(pin):
    """Turn the specified GPIO pin HIGH."""
    global led
    if led is None or led.pin.number != pin:
        try:
            led = LED(pin)
        except GPIOZeroError as exc:
            print(f"Error: failed to initialize GPIO{pin}: {exc}", file=sys.stderr)
            raise
    led.on()


def turn_off_led(pin):
    """Turn the specified GPIO pin LOW."""
    global led
    if led is not None and led.pin.number == pin:
        led.off()


def cleanup():
    """Release GPIO resources and leave the pin in a defined (LOW) state."""
    global led
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        led = None


def main():
    print("Starting LED blink program on GPIO17...")
    try:
        while True:
            turn_on_led(LED_PIN)
            time.sleep(ON_DURATION)
            turn_off_led(LED_PIN)
            time.sleep(OFF_DURATION)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup()
        print("GPIO cleanup done.")


if __name__ == "__main__":
    main()

