import signal
import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)


class LEDController:
    """
    Controls an LED connected to a Raspberry Pi GPIO pin using gpiozero.

    Attributes:
        pin (int): The BCM GPIO pin number the LED is connected to.
        led (LED): The gpiozero LED device instance.
    """

    def __init__(self, pin):
        """
        Initializes the LEDController.

        Args:
            pin (int): The BCM GPIO pin number (e.g., 25 for physical pin 22).

        Raises:
            ValueError: If the pin number is invalid or the LED cannot be initialized.
        """
        if not isinstance(pin, int) or pin < 0:
            raise ValueError(f"Invalid GPIO pin number: {pin!r}")

        try:
            self.led = LED(pin)
        except (GPIOZeroError, GPIODeviceError) as e:
            raise ValueError(f"Failed to initialize LED on GPIO{pin}: {e}") from e
        except Exception as e:
            raise ValueError(f"Unexpected error initializing LED on GPIO{pin}: {e}") from e

        self.pin = pin
        self._running = True

    def on(self):
        """Turns the LED on."""
        try:
            self.led.on()
        except Exception as e:
            print(f"Error turning LED on: {e}")

    def off(self):
        """Turns the LED off."""
        try:
            self.led.off()
        except Exception as e:
            print(f"Error turning LED off: {e}")

    def blink(self, on_duration, off_duration):
        """
        Blinks the LED with specified on and off durations.

        Args:
            on_duration (float): Duration the LED stays on in seconds.
            off_duration (float): Duration the LED stays off in seconds.

        Raises:
