import logging
import signal
import sys
import time

import RPi.GPIO as GPIO

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PIR_PIN = 23
DEBOUNCE_MS = 200
POLL_INTERVAL_S = 0.1
CHECK_INTERVAL_S = 10
DEAD_SENSOR_TIMEOUT_S = 30
TOTAL_DURATION_S = 60


class MotionCounter:
    def __init__(self, pin: int, debounce_ms: int):
        self.pin = pin
        self.debounce_ms = debounce_ms
        self.last_trigger_time = 0.0
        self.visitor_count = 0
        self._running = True
        self._last_motion_time = time.monotonic()

    def _setup_gpio(self) -> None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logging.info("GPIO setup complete on pin %d.", self.pin)
        except Exception as exc:
            logging.error("Failed to initialize GPIO: %s", exc)
            raise

    def _cleanup_gpio(self) -> None:
        try:
            GPIO.cleanup()
            logging.info("GPIO cleanup complete.")
        except Exception as exc:
            logging.error("Error during GPIO cleanup: %s", exc)

    def _handle_signal(self, signum, frame) -> None:
        logging.info("Received signal %d, shutting down...", signum)
        self._running = False

    def _check_sensor_presence(self) -> bool:
        if time.monotonic() - self._last_motion_time > DEAD_SENSOR_TIMEOUT_S:
            logging.warning(
                "No motion detected for %d seconds. "
                "Sensor may be disconnected or wiring fault.",
                DEAD_SENSOR_TIMEOUT_S,
            )
            return False
        return True

    def _read_motion(self) -> bool:
        try:
            return GPIO.input(self.pin) == GPIO.HIGH
        except Exception as exc:
            logging.error("Error reading GPIO pin %d: %s", self.pin, exc)
            return False

    def _debounce(self, motion_detected: bool) -> bool:
        if motion_detected and (time.monotonic() - self.last_trigger_time) * 1000 >= self.debounce_ms:
            self.last_trigger_time = time.monotonic()
            return True
        return False

    def _update_visitor_count(self) -> None:
        self.visitor_count += 1
        logging.info("Visitor count: %d", self.visitor_count)

    def run(self) -> None:
        self._setup_gpio()
        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGTERM, self._handle_signal)

        try:
            while self._running:
                if not self._check_sensor_presence():
                    time.sleep(POLL_INTERVAL_S)
                    continue

                motion_detected = self._read_motion()
                if motion_detected and self._debounce(motion_detected):
                    self._update_visitor_count()
                    self._last_motion_time = time.monotonic()

                time.sleep(POLL_INTERVAL_S)

        except Exception as exc:
            logging.error("Unexpected error in main loop: %s", exc)
        finally:
            self._cleanup_gpio()
            logging.info("Final visitor count: %d", self.visitor_count)


def main() -> None:
    counter = MotionCounter(PIR_PIN, DEBOUNCE_MS)
    start_time = time.monotonic()
    try:
        while time.monotonic() - start_time < TOTAL_DURATION_S:
            counter.run()
            time.sleep(CHECK_INTERVAL_S)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

