def get_sensor_data(bus: SMBus, address: int) -> Optional[Dict]:
    """Read data from a single MCP39F511N sensor via I2C."""
    try:
        # Read 8 bytes from registers 0x00 to 0x07
        data = bus.read_i2c_block_data(address, 0x00, 8)
        if len(data) != 8:
            logger.error(f"Short read from 0x{address:02X}: got {len(data)} bytes")
            return None

        # Parse 16-bit unsigned values (big-endian)
        active_power = (data[0] << 8) | data[1]
        voltage = (data[2] << 8) | data[3]
        current = (data[4] << 8) | data[5]
        frequency = (data[6] << 8) | data[7]

        return {
            'active_power': active_power,
            'voltage': voltage,
            'current': current,
            'frequency': frequency,
            'power_factor': 1.0,  # MCP39F511N reports power factor as 1.0
        }
    except OSError as e:
        logger.error(f"I2C read error from 0x{address:02X}: {e}")
        return None
    except Exception as e:
        logger.error(f"Unexpected error reading 0x{address:02X}: {e}")
        return None


def acquire_data() -> None:
    """Acquire data from all sensors and log it."""
    global log_file, log_file_size, log_file_handle, log_file_rotation_in_progress

    while running:
        timestamp = datetime.datetime.now().isoformat()
        readings: List[Dict] = []

        for address in SENSOR_ADDRESSES:
            bus = None
            try:
                bus = SMBus(I2C_BUS)
                data = get_sensor_data(bus, address)
                if data:
                    readings.append({
                        'timestamp': timestamp,
                        'sensor_address': f'0x{address:02X}',
                        **data
                    })
            except Exception as e:
                logger.error(f"Error accessing I2C bus: {e}")
            finally:
                if bus is not None:
                    try:
                        bus.close()
                    except Exception:
                        pass

        if readings:
            with data_lock:
                for reading in readings:
                    sensor_data[reading['sensor_address']][reading['timestamp']] = reading

            log_data(readings)
        else:
            logger.warning("No sensor data acquired this cycle.")

        # Sleep in small increments to allow prompt signal handling
        for _ in range(SAMPLE_INTERVAL):
            if not running:
                break
            time.sleep(1)


def log_data(data: List[Dict]) -> None:
    """Log data to a rotating JSON file."""
    global log_file, log_file_size, log_file_handle, log_file_rotation_in_progress

    if not data:
        return

    filename = f"energy_log_{datetime.date.today().isoformat()}.json"
    file_size_limit = LOG_FILE_SIZE_LIMIT
    file_permissions = LOG_FILE_PERMISSIONS

    with log_file_lock:
        if log_file is None or log_file != filename:
            # Rotate or create new log file
            if log_file_handle is not None:
                try:
                    log_file_handle.close()
                except Exception:
                    pass
                log_file_handle = None

            log_file = filename
            log_file_size = 0
            log_file_handle = None

            # Check if log file already exists
            if os.path.exists(filename):
                try:
                    with open(filename, 'r') as f:
                        log_file_size = os.path.getsize(filename)
                except Exception as e:
                    logger.error(f"Error checking log file size: {e}")
                    log_file_size = 0

            if log_file_size > file_size_limit:
                # Rotate: compress existing file and start a new one
                with log_file_rotation_lock:
                    if log_file_rotation_in_progress:
                        logger.warning("Log rotation already in progress, skipping.")
                        return
                    log_file_rotation_in_progress = True

                try:
                    compressed_filename = f"energy_log_{datetime.date.today().isoformat()}_{datetime.datetime.now().strftime('%H%M%S')}.json.gz"
                    os.system(f"gzip -c {filename} > {compressed_filename}")
                    logger.info(f"Compressed {filename} to {compressed_filename}")

                    # Remove old log files if we have too many
                    log_files = [
                        f for f in os.listdir('.')
                        if f.startswith('energy_log_') and f.endswith('.json.gz')
                    ]
                    log_files.sort()
                    while len(log_files) > MAX_LOG_FILES:
                        old_file = log_files.pop(0)
                        try:
                            os.remove(old_file)
                            logger.info(f"Removed old log file: {old_file}")
                        except Exception as e:
                            logger.error(f"Error removing {old_file}: {e}")

                    # Start a new log
                    log_file_handle = open(filename, 'w', encoding='utf-8')
                    log_file_size = 0
                    logger.info(f"Started new log file: {filename}")
                except Exception as e:
                    logger.error(f"Error during log rotation: {e}")
                finally:
                    log_file_rotation_in_progress = False
            else:
                # Append to existing log
                try:
                    log_file_handle = open(filename, 'a', encoding='utf-8')
                    log_file_size = os.path.getsize(filename)
                except Exception as e:
                    logger.error(f"Error opening log file: {e}")
                    log_file_handle = None

        if log_file_handle is not None:
            try:
                # Write each reading as a JSON line
                for reading in data:
                    json.dump(reading, log_file_handle)
                    log_file_handle.write('\n')
                log_file_handle.flush()
                log_file_size += len(json.dumps(data[0])) + 1  # approx bytes written
            except Exception as e:
                logger.error(f"Error writing to log file: {e}")
                try:
                    log_file_handle.close()
                except Exception:
                    pass
                log_file_handle = None
        else:
            logger.warning("Log file handle is not open.")


def view_data() -> None:
    """View current sensor data."""
    with data_lock:
        for addr, data in sensor_data.items():
            if data:
                print(f"Sensor 0x{addr:02X}:")
                for ts, d in data.items():
                    print(f"  {ts}: {d}")
            else:
                print(f"Sensor 0x{addr:02X}: No data")


def get_data_by_date(date: str) -> None:
    """Retrieve and print data for a specific date."""
    global log_file
    filename = f"energy_log_{date}.json"
    if not os.path.exists(filename):
        print(f"Log file for {date} not found.")
        return

    try:
        with open(filename, 'r', encoding='utf-8') as f:
            for line in f:
                try:
                    data = json.loads(line.strip())
                    print(data)
                except json.JSONDecodeError as e:
                    logger.error(f"Error decoding JSON line: {e}")
    except Exception as e:
        logger.error(f"Error reading log file: {e}")


def get_stats(sensor_address: str, date: str) -> None:
    """Calculate and print statistics for a sensor on a specific date."""
    global log_file
    filename = f"energy_log_{date}.json"
    if not os.path.exists(filename):
        print(f"Log file for {date} not found.")
        return

    timestamps: List[str] = []
    active_powers: List[float] = []

    try:
        with open(filename, 'r', encoding='utf-8') as f:
            for line in f:
                try:
                    data = json.loads(line.strip())
                    if data.get('sensor_address') == sensor_address:
                        timestamps.append(data['timestamp'])
                        active_powers.append(data['active_power'])
                except json.JSONDecodeError as e:
                    logger.error(f"Error decoding JSON line: {e}")
    except Exception as e:
        logger.error(f"Error reading log file: {e}")
        return

    if not timestamps:
        print("No data found for this sensor and date.")
        return

    print(f"Sensor Address: {sensor_address}")
    print(f"Date: {date}")
    print(f"Timestamps: {timestamps}")
    print(f"Min Active Power: {min(active_powers):.2f} W")
    print(f"Max Active Power: {max(active_powers):.2f} W")
    print(f"Average Active Power: {sum(active_powers) / len(active_powers):.2f} W")


def main() -> None:
    """Main entry point."""
    global running

    parser = argparse.ArgumentParser(description="Raspberry Pi Energy Monitoring System")
    parser.add_argument("--start", action="store_true", help="Start the monitoring system")
    parser.add_argument("--stop", action="store_true", help="Stop the monitoring system")
    parser.add_argument("--view", action="store_true", help="View current sensor data")
    parser.add_argument("--date", type=str, help="Date (YYYY-MM-DD) to retrieve data")
    parser.add_argument("--stats", type=str, help="Sensor address (0xXX) to retrieve statistics")
    parser.add_argument("--sensor", type=str, help="Sensor address (0xXX) to retrieve data")
    args = parser.parse_args()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if args.start:
        # Start the data acquisition thread
        data_thread = threading.Thread(target=acquire_data, daemon=True)
        data_thread.start()

        # Keep the main thread alive until shutdown
        try:
            while running:
                time.sleep(1)
        except KeyboardInterrupt:
            running = False
            data_thread.join(timeout=2)
            logger.info("Data acquisition thread stopped.")
    elif args.stop:
        running = False
        logger.info("Shutdown requested.")
    elif args.view:
        view_data()
    elif args.date and args.stats:
        get_stats(args.stats, args.date)
    elif args.date and args.sensor:
        get_data_by_date(args.date)
    else:
        print("Invalid arguments. Use --help for usage.")


if __name__ == "__main__":
    main()

