import time
import random
import RPi.GPIO as GPIO

# GPIO pin connected to the SW-420 digital vibration sensor (BCM numbering)
VIBRATION_SENSOR_PIN = 17

# Sampling parameters
SAMPLE_COUNT = 6
SAMPLE_INTERVAL = 0.3  # seconds

# Threshold for maintenance recommendation
MAINTENANCE_THRESHOLD = 7.5

def setup_vibration_sensor():
    """Configure the GPIO pin for the vibration sensor with internal pull-up."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(VIBRATION_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        raise

def read_vibration_amplitude():
    """Return a simulated amplitude reading based on the sensor state."""
    # SW-420 digital output is active-low: LOW = vibration detected, HIGH = idle
    if GPIO.input(VIBRATION_SENSOR_PIN) == GPIO.LOW:
        return random.uniform(6.0, 9.0)  # vibration detected
    else:
        return random.uniform(3.0, 5.0)  # idle

def evaluate_maintenance(average_amplitude):
    """Return maintenance recommendation based on average amplitude."""
    if average_amplitude > MAINTENANCE_THRESHOLD:
        return "Maintenance recommended: wear trend is high"
    else:
        return "Component healthy: no action needed"

def cleanup():
    """Release GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}")

if __name__ == "__main__":
    try:
        setup_vibration_sensor()
        print("Vibration monitoring started. Press Ctrl+C to stop.")
        total = 0.0
        for i in range(SAMPLE_COUNT):
            total += read_vibration_amplitude()
            time.sleep(SAMPLE_INTERVAL)
        average_amplitude = total / SAMPLE_COUNT
        print(f"Average vibration amplitude: {average_amplitude:.2f}")
        print(evaluate_maintenance(average_amplitude))
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup()

