import random
import time
import signal
import sys
from gpiozero import DigitalInputDevice, DigitalOutputDevice

# GPIO pin definitions (BCM numbering)
WATER_SENSOR_PIN = 17   # digital input with internal pull-up
PUMP_CONTROL_PIN = 18    # digital output

# Water level thresholds
LOW_LEVEL_THRESHOLD = 20
HIGH_LEVEL_THRESHOLD = 80

# Global handles so the signal handler can release them
water_sensor = None
pump = None
running = True


def cleanup():
    """Release GPIO resources safely."""
    global water_sensor, pump
    if pump is not None:
        try:
            pump.close()
        except Exception:
            pass
    if water_sensor is not None:
        try:
            water_sensor.close()
        except Exception:
            pass


def handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global running
    running = False


def read_water_level():
    """Simulate reading a water level sensor (0–100 %)."""
    return random.randint(0, 100)


def control_pump(level, current_state):
    """Control the pump based on the water level and current state."""
    if level < LOW_LEVEL_THRESHOLD:
        return True   # turn pump ON
    if level > HIGH_LEVEL_THRESHOLD:
        return False  # turn pump OFF
    return current_state  # hold current state


def main():
    global water_sensor, pump

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # Initialize GPIO devices
    try:
        water_sensor = DigitalInputDevice(
            WATER_SENSOR_PIN, pull_up=True, bounce_time=None
        )
        pump = DigitalOutputDevice(PUMP_CONTROL_PIN, active_high=True, initial_value=False)
    except Exception as exc:
        print(f"Failed to initialize GPIO: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    pump_state = False  # start in OFF state

    try:
        for i in range(5):
            if not running:
                break

            level = read_water_level()
            pump_state = control_pump(level, pump_state)

            print(f"[{i + 1}/5] Water Level: {level}%  |  Pump: {'ON' if pump_state else 'OFF'}")

            # Drive the pump output
            if pump_state:
                pump.on()
            else:
                pump.off()

            # 2-second delay between readings (interruptible)
            for _ in range(20):
                if not running:
                    break
                time.sleep(0.1)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)

    finally:
        # Ensure pump is OFF and release GPIO resources
        if pump is not None:
            try:
                pump.off()
                pump.close()
            except Exception:
                pass
        if water_sensor is not None:
            try:
                water_sensor.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

