import json
import socket
import time
import logging
import signal
import sys
from typing import Optional, Tuple

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

SERVER_IP = "127.0.0.1"
SERVER_PORT = 9099
GPS_READ_TIMEOUT = 2.0

_running = True

def _signal_handler(signum, frame):
    global _running
    logger.info(f"Received signal {signum}, shutting down...")
    _running = False

def read_gps_position() -> Optional[Tuple[float, float]]:
    try:
        import serial
        with serial.Serial("/dev/serial0", baudrate=9600, timeout=GPS_READ_TIMEOUT) as ser:
            logger.info("GPS module initialized on /dev/serial0")
            time.sleep(2)
            if ser.in_waiting > 0:
                line = ser.readline().decode('utf-8', errors='ignore').strip()
                if line.startswith('$GPGGA'):
                    parts = line.split(',')
                    if len(parts) > 6 and parts[6] != '0':
                        lat = float(parts[2]) if parts[2] else 0.0
                        lon = float(parts[4]) if parts[4] else 0.0
                        return lat, lon
            logger.warning("No GPS fix received, using simulated coordinates")
            return 37.7749, -122.4194
    except Exception as e:
        logger.error(f"Error reading GPS: {e}")
        return None

def handle_command(command: str) -> str:
    if command == "start":
        return "Tracking started"
    elif command == "stop":
        return "Tracking stopped"
    elif command == "report":
        pos = read_gps_position()
        if pos:
            return json.dumps({"lat": pos[0], "lon": pos[1]})
        else:
            return json.dumps({"error": "No GPS fix available"})
    else:
        return "Invalid command"

def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    server_socket = None
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((SERVER_IP, SERVER_PORT))
        server_socket.listen(5)
        server_socket.settimeout(1.0)
        logger.info(f"Server listening on {SERVER_IP}:{SERVER_PORT}")

        while _running:
            try:
                client_socket, addr = server_socket.accept()
                logger.info(f"Connection from {addr}")
                with client_socket:
                    data = client_socket.recv(1024).decode('utf-8', errors='ignore').strip()
                    if data:
                        response = handle_command(data)
                        client_socket.sendall(response.encode('utf-8'))
                    else:
                        logger.warning("Empty command received")
            except socket.timeout:
                continue
            except socket.error as e:
                if _running:
                    logger.error(f"Socket error: {e}")
            except Exception as e:
                if _running:
                    logger.error(f"Unexpected error: {e}")

    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        if server_socket:
            try:
                server_socket.close()
                logger.info("Server socket closed")
            except Exception as e:
                logger.error(f"Error closing socket: {e}")
        logger.info("Server stopped")

if __name__ == "__main__":
    main()

