import time
import random
import signal
import sys
from gpiozero import OutputDevice

# Constants
MOTOR1_HEAD_PINS = [17, 18, 27, 22]
MOTOR2_FOOT_PINS = [23, 24, 25, 12]
STEPS_PER_DEGREE = 12
STEPS_PER_ML = 25
BACKLASH_STEPS = 10
DELAY = 0.002
MIN_INTERVAL = 60
MAX_INTERVAL = 300

# Global list to track all GPIO pins for cleanup
_pins = []

def setup_gpio(pins):
    """Sets up GPIO pins as outputs using gpiozero."""
    global _pins
    _pins = []
    for pin in pins:
        try:
            dev = OutputDevice(pin)
            _pins.append(dev)
        except Exception as e:
            print(f"Error setting up GPIO pin {pin}: {e}")
            cleanup_gpio()
            sys.exit(1)

def cleanup_gpio():
    """Cleans up GPIO pins by closing all OutputDevice objects."""
    for dev in _pins:
        try:
            dev.close()
        except Exception:
            pass
    _pins.clear()

def signal_handler(sig, frame):
    """Handles SIGINT (Ctrl+C) for graceful shutdown."""
    print("\nExiting program...")
    cleanup_gpio()
    sys.exit(0)

def read_heart_rate():
    """Simulates reading the heart rate."""
    return random.randint(60, 100)

def read_spo2():
    """Simulates reading the SpO2."""
    return random.randint(95, 99)

def adjust_bed(motor_number, angle_degrees):
    """Adjusts the bed position using a stepper motor.

    Args:
        motor_number: 1 for head, 2 for foot.
        angle_degrees: Angle to adjust the bed by (1-30 degrees).
    """
    if not 1 <= motor_number <= 2:
        print("Error: Invalid motor number. Must be 1 or 2.")
        return
    if not 1 <= angle_degrees <= 30:
        print("Error: Invalid angle. Must be between 1 and 30 degrees.")
        return

    steps = int(angle_degrees * STEPS_PER_DEGREE)
    pins = MOTOR1_HEAD_PINS if motor_number == 1 else MOTOR2_FOOT_PINS

    for i in range(steps):
        for pin, value in zip(pins, [1, 0, 0, 0]):
            try:
                pin.value = value
            except Exception as e:
                print(f"Error setting GPIO pin {pin}: {e}")
                return
        time.sleep(DELAY)

    # Back off to compensate for backlash
    for _ in range(BACKLASH_STEPS):
        for pin, value in zip(pins, [0, 0, 0, 0]):
            try:
                pin.value = value
            except Exception as e:
                print(f"Error setting GPIO pin {pin}: {e}")
                return
        time.sleep(DELAY)

def dispense_medication(motor_number, dose_ml):
    """Dispenses medication using a stepper motor.

    Args:
        motor_number: 1 for head, 2 for foot.
        dose_ml: Dose of medication to dispense (1-10 ml).
    """
    if not 1 <= motor_number <= 2:
        print("Error: Invalid motor number. Must be 1 or 2.")
        return
    if not 1 <= dose_ml <= 10:
        print("Error: Invalid dose. Must be between 1 and 10 ml.")
        return

    steps = int(dose_ml * STEPS_PER_ML)
    pins = MOTOR1_HEAD_PINS if motor_number == 1 else MOTOR2_FOOT_PINS

    for i in range(steps):
        for pin, value in zip(pins, [1, 0, 0, 0]):
            try:
                pin.value = value
            except Exception as e:
                print(f"Error setting GPIO pin {pin}: {e}")
                return
        time.sleep(DELAY)

    # Back off to prevent siphoning
    for _ in range(BACKLASH_STEPS):
        for pin, value in zip(pins, [0, 0, 0, 0]):
            try:
                pin.value = value
            except Exception as e:
                print(f"Error setting GPIO pin {pin}: {e}")
                return
        time.sleep(DELAY)

def run_schedule(head_angle, foot_angle, dose_A, dose_B, interval_seconds):
    """Runs the bed adjustment and medication dispensing schedule.

    Args:
        head_angle: Angle to adjust the bed head by.
        foot_angle: Angle to adjust the bed foot by.
        dose_A: Dose of medication A to dispense.
        dose_B: Dose of medication B to dispense.
        interval_seconds: Interval between schedule executions.
    """
    if not MIN_INTERVAL <= interval_seconds <= MAX_INTERVAL:
        print("Error: Invalid interval. Must be between 60 and 300 seconds.")
        return

    try:
        adjust_bed(1, head_angle)
        adjust_bed(2, foot_angle)
        dispense_medication(1, dose_A)
        dispense_medication(2, dose_B)

        heart_rate = read_heart_rate()
        spo2 = read_spo2()
        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2}%")
        time.sleep(interval_seconds)
    except Exception as e:
        print(f"Error during schedule execution: {e}")

def main():
    """Main function to run the bed adjustment and medication dispensing schedule."""
    signal.signal(signal.SIGINT, signal_handler)
    setup_gpio(MOTOR1_HEAD_PINS + MOTOR2_FOOT_PINS)

    try:
        while True:
            run_schedule(15, 10, 5, 3, 120)
    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

