import random
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

# Configuration
LED_PIN = 23
MOISTURE_THRESHOLD = 30
NUM_READINGS = 3
DELAY_BETWEEN_READINGS = 1.0
LED_ON_DURATION = 2.0


def read_moisture_level() -> int:
    """Simulates reading moisture data from a sensor (0-100%)."""
    return random.randint(0, 100)


def control_watering(led: LED, moisture_level: int) -> None:
    """Controls watering based on moisture level and toggles the LED."""
    if moisture_level < MOISTURE_THRESHOLD:
        print(f"Moisture level: {moisture_level}% - Watering complete!")
        led.on()
        time.sleep(LED_ON_DURATION)
        led.off()
    else:
        print(f"Moisture level: {moisture_level}% - Moisture sufficient")


def main() -> None:
    """Main function to simulate watering system."""
    try:
        with LED(LED_PIN) as led:
            for i in range(NUM_READINGS):
                moisture = read_moisture_level()
                print(f"Reading {i + 1}/{NUM_READINGS} - Moisture: {moisture}%")
                control_watering(led, moisture)
                if i < NUM_READINGS - 1:
                    time.sleep(DELAY_BETWEEN_READINGS)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user. Exiting...")
    except GPIOZeroError as e:
        print(f"GPIO error: {e}")
    finally:
        # Ensure LED is off and pin is released deterministically
        try:
            with LED(LED_PIN) as led:
                led.off()
        except GPIOZeroError:
            pass


if __name__ == "__main__":
    main()

