import time
import logging
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

SERVO_PIN = 18
PWM_FREQUENCY = 50
MIN_ANGLE = 0
MAX_ANGLE = 180
STEP_DELAY = 0.5


class ServoController:
    """Encapsulates servo control via a PWM library on a Raspberry Pi."""

    def __init__(self, pin, frequency):
        self.pin = pin
        self.frequency = frequency
        self.pwm = None
        self._initialized = False
        try:
            import RPi.GPIO as GPIO
            self._GPIO = GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.OUT)
            self.pwm = GPIO.PWM(self.pin, self.frequency)
            self.pwm.start(0)
            self._initialized = True
            logging.info(
                "ServoController initialized on BCM pin %d at %d Hz.",
                self.pin,
                self.frequency,
            )
        except ImportError:
            logging.error(
                "RPi.GPIO not available. Install with: pip install RPi.GPIO"
            )
            raise
        except Exception as exc:
            logging.error("Failed to initialize servo on pin %d: %s", self.pin, exc)
            raise

    def _angle_to_duty_cycle(self, angle):
        """Convert an angle in degrees to a duty cycle for the SG90 servo."""
        if not MIN_ANGLE <= angle <= MAX_ANGLE:
            raise ValueError(
                f"Angle {angle} out of range ({MIN_ANGLE}-{MAX_ANGLE})."
            )
        return 2.0 * angle / 180.0 + 2.0

    def move_to(self, angle):
        """Move the servo to the specified angle and log the action."""
        if not self._initialized:
            raise RuntimeError("ServoController not initialized.")
        if self.pwm is None:
            raise RuntimeError("PWM object is not available.")
        try:
            duty = self._angle_to_duty_cycle(angle)
            self.pwm.ChangeDutyCycle(duty)
            logging.info("Moving servo to angle: %d", angle)
        except Exception as exc:
            logging.error("Error moving servo to angle %d: %s", angle, exc)
            raise

    def stop(self):
        """Stop the PWM signal and release the GPIO pin."""
        if not self._initialized:
            return
        try:
            if self.pwm is not None:
                self.pwm.stop()
        except Exception as exc:
            logging.error("Error stopping PWM: %s", exc)
        finally:
            try:
                self._GPIO.cleanup(self.pin)
                logging.info("GPIO pin %d cleaned up.", self.pin)
            except Exception as exc:
                logging.error("Error cleaning up GPIO: %s", exc)
            self._initialized = False


def run_servo_sweep(controller, angles):
    """Sweep the servo through a list of angles, pausing between each."""
    try:
        for angle in angles:
            controller.move_to(angle)
            time.sleep(STEP_DELAY)
    except KeyboardInterrupt:
        logging.info("Sweep interrupted by user.")
    except Exception as exc:
        logging.error("Error during sweep: %s", exc)
        raise


def main():
    controller = None
    try:
        controller = ServoController(SERVO_PIN, PWM_FREQUENCY)
        sweep_sequence = [0, 45, 90, 135, 180]
        run_servo_sweep(controller, sweep_sequence)
        logging.info("Sweep complete.")
    except Exception as exc:
        logging.error("Fatal error: %s", exc)
        sys.exit(1)
    finally:
        if controller is not None:
            controller.stop()


if __name__ == "__main__":
    main()

