            self._initialized = False


def run_servo_sweep(controller, angles):
    """Sweep the servo through a list of angles, pausing between each."""
    try:
        for angle in angles:
            controller.move_to(angle)
            time.sleep(STEP_DELAY)
    except KeyboardInterrupt:
        logging.info("Sweep interrupted by user.")
    except Exception as exc:
        logging.error("Error during sweep: %s", exc)
        raise


def main():
    controller = None
    try:
        controller = ServoController(SERVO_PIN, PWM_FREQUENCY)
        sweep_sequence = [0, 45, 90, 135, 180]
        run_servo_sweep(controller, sweep_sequence)
        logging.info("Sweep complete.")
    except Exception as exc:
        logging.error("Fatal error: %s", exc)
        sys.exit(1)
    finally:
        if controller is not None:
            controller.stop()


