import signal
import sys
import time

import serial
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERVO_PIN = 17
MIN_ANGLE = 0
MAX_ANGLE = 180
PWM_FREQ = 50
HOLD_SECONDS = 1.0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def angle_to_duty(angle):
    """Convert a 0-180-degree angle to a 50 Hz PWM duty cycle (1-2 ms pulse)."""
    if not (MIN_ANGLE <= angle <= MAX_ANGLE):
        raise ValueError(f"Angle {angle} out of range [{MIN_ANGLE}, {MAX_ANGLE}]")
    return (angle / 180.0) * 10.0 + 2.5


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(SERVO_PIN, GPIO.OUT)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        GPIO.cleanup()
        return 1

    pwm = None
    try:
        pwm = GPIO.PWM(SERVO_PIN, PWM_FREQ)
        pwm.start(0)

        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Serial read error: {exc}", file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                angle = int(line)
            except ValueError:
                print(f"Invalid data received (not an integer): {line!r}", file=sys.stderr)
                continue

            try:
                duty = angle_to_duty(angle)
            except ValueError as exc:
                print(f"Invalid angle: {exc}", file=sys.stderr)
                continue

            try:
                pwm.ChangeDutyCycle(duty)
            except Exception as exc:
                print(f"PWM update error: {exc}", file=sys.stderr)
                break

            time.sleep(HOLD_SECONDS)
            try:
                pwm.ChangeDutyCycle(0)
            except Exception as exc:
                print(f"PWM stop error: {exc}", file=sys.stderr)
                break

    finally:
        if pwm is not None:
            try:
                pwm.stop()
            except Exception:
                pass
        try:
            ser.close()
        except Exception:
            pass
        GPIO.cleanup()

    return 0


if __name__ == '__main__':
    sys.exit(main())

