#!/usr/bin/env python3
"""
Soil Moisture Monitoring and Irrigation Control System for Raspberry Pi Zero W

Hardware:
  - Raspberry Pi Zero W
  - Adafruit Seesaw soil moisture sensor (I2C, address 0x36)
  - 12 V water pump (relay on GPIO17)

The pump is activated when the soil moisture reading is below 500.
"""

import signal
import sys
import time
import logging

import board
import busio
import adafruit_seesaw.seesaw
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
I2C_ADDRESS = 0x36
PUMP_GPIO_PIN = 17
MOISTURE_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("soil_monitor")

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_pump = None
_i2c = None
_running = True


def _cleanup() -> None:
    """Turn off the pump and release GPIO / I2C resources."""
    global _pump, _i2c
    if _pump is not None:
        try:
            _pump.off()
            log.info("Pump turned OFF during cleanup.")
        except GPIOZeroError as exc:
            log.warning("Could not turn off pump during cleanup: %s", exc)
        finally:
            _pump = None
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None


def _signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def initialize_i2c() -> busio.I2C:
    """Initialize the I2C bus; exit on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        log.error("Failed to initialize I2C bus: %s", exc)
        sys.exit(1)


def initialize_sensor(i2c_bus: busio.I2C) -> adafruit_seesaw.seesaw.Seesaw:
    """Initialize the Seesaw soil moisture sensor; exit on failure."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
    except Exception as exc:
        log.error("Failed to initialize Seesaw sensor at 0x%02X: %s", I2C_ADDRESS, exc)
        sys.exit(1)


def initialize_pump(pin: int) -> OutputDevice:
    """Initialize the pump relay; exit on failure."""
    try:
        return OutputDevice(pin, active_high=True, initial_value=False)
    except GPIOZeroError as exc:
        log.error("Failed to initialize pump relay on GPIO%d: %s", pin, exc)
        sys.exit(1)


def read_moisture(sensor: adafruit_seesaw.seesaw.Seesaw) -> int:
    """Read soil moisture; return -1 on error."""
    try:
        return sensor.moisture_read()
    except Exception as exc:
        log.error("Error reading soil moisture: %s", exc)
        return -1


def control_pump(pump: OutputDevice, moisture: int) -> None:
    """Activate or deactivate the pump based on moisture level."""
    if moisture < 0:
        log.warning("Skipping pump control due to read error.")
        return
    if moisture < MOISTURE_THRESHOLD:
        if not pump.is_active:
            pump.on()
            log.info("Moisture %d < %d – pump ON.", moisture, MOISTURE_THRESHOLD)
    else:
        if pump.is_active:
            pump.off()
            log.info("Moisture %d >= %d – pump OFF.", moisture, MOISTURE_THRESHOLD)


def main() -> None:
    global _pump, _i2c

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _i2c = initialize_i2c()
    sensor = initialize_sensor(_i2c)
    _pump = initialize_pump(PUMP_GPIO_PIN)

    log.info("Soil moisture monitor started. Press Ctrl+C to stop.")

    try:
        while _running:
            moisture = read_moisture(sensor)
            if moisture >= 0:
                log.info("Soil Moisture: %d", moisture)
            control_pump(_pump, moisture)
            time.sleep(READ_INTERVAL_SECONDS)
    except Exception as exc:
        log.exception("Unexpected error in main loop: %s", exc)
    finally:
        _cleanup()
        log.info("Program terminated.")


if __name__ == "__main__":
    main()

