        response = ""
        for _ in range(attempts):
            try:
                chunk = self._uart.read(1000)
                if chunk:
                    response += chunk.decode('utf-8', errors='ignore')
                    if "OK" in response or "ERROR" in response:
                        break
            except serial.SerialException as e:
                logging.error("Serial read error: %s", e)
