import signal
import sys
import time
import board
import busio
import adafruit_seesaw.seesaw
from gpiozero import OutputDevice

# Constants
I2C_ADDRESS = 0x36
PUMP_GPIO_PIN = 17
DRY_SOIL_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

# Global state for signal handling
_running = True
_pump = None

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c():
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None

def initialize_seesaw(i2c_bus):
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing Seesaw sensor at 0x{I2C_ADDRESS:02X}: {e}", file=sys.stderr)
        return None

def initialize_pump(pin):
    try:
        return OutputDevice(pin, active_high=True, initial_value=False)
    except Exception as e:
        print(f"Error initializing pump GPIO{pin}: {e}", file=sys.stderr)
        return None

def read_moisture_level(seesaw_sensor):
    try:
        return seesaw_sensor.moisture_read()
    except Exception as e:
        print(f"Error reading moisture level: {e}", file=sys.stderr)
        return None

def control_water_pump(pump, moisture_level, dry_threshold):
    if moisture_level is None:
        return "UNKNOWN"
    if moisture_level < dry_threshold:
        pump.on()
        return "ON"
    else:
        pump.off()
        return "OFF"

def display_status(moisture_level, pump_status):
    print(f"Moisture Level: {moisture_level}")
    print(f"Water Pump: {pump_status}")

def cleanup(pump):
    if pump is not None:
        try:
            pump.off()
            pump.close()
        except Exception:
            pass

def main():
    global _pump

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    seesaw_sensor = initialize_seesaw(i2c_bus)
    if seesaw_sensor is None:
        cleanup(_pump)
        sys.exit(1)

    _pump = initialize_pump(PUMP_GPIO_PIN)
    if _pump is None:
        cleanup(_pump)
        sys.exit(1)

    try:
        while _running:
            moisture_level = read_moisture_level(seesaw_sensor)
            pump_status = control_water_pump(_pump, moisture_level, DRY_SOIL_THRESHOLD)
            display_status(moisture_level, pump_status)
            time.sleep(READ_INTERVAL_SECONDS)
    finally:
        cleanup(_pump)

if __name__ == "__main__":
    main()

