import RPi.GPIO as GPIO
import time
import datetime
import signal
import sys

RELAY_PIN = 17
SUNRISE_TIME = "07:00"
SUNSET_TIME = "19:00"
CHECK_INTERVAL = 60
RELAY_SETTLE_DELAY = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.HIGH)

def get_current_time_str():
    return datetime.datetime.now().strftime("%H:%M")

def is_sunrise_time():
    return get_current_time_str() == SUNRISE_TIME

def is_sunset_time():
    return get_current_time_str() == SUNSET_TIME

def open_door():
    GPIO.output(RELAY_PIN, GPIO.LOW)
    print(f"[{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] Door opened (relay LOW).")

def close_door():
    GPIO.output(RELAY_PIN, GPIO.HIGH)
    print(f"[{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] Door closed (relay HIGH).")

def cleanup_gpio():
    try:
        GPIO.output(RELAY_PIN, GPIO.HIGH)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)

    print("Chicken Coop Door Controller started. Press Ctrl+C to exit.")

    try:
        while _running:
            if is_sunrise_time():
                open_door()
                time.sleep(RELAY_SETTLE_DELAY)
            elif is_sunset_time():
                close_door()
                time.sleep(RELAY_SETTLE_DELAY)

            for _ in range(CHECK_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

