import time
import signal
import sys
import smbus2
from adafruit_servokit import ServoKit

I2C_BUS = 1
PCA9685_ADDR = 0x40
PWM_FREQ = 60
SERVO_CHANNELS = (0, 1)
SERVO_MIN_ANGLE = -77
SERVO_MAX_ANGLE = 77
STEP_DELAY = 0.25

kit = None
i2c = None
running = True


def cleanup(signum=None, frame=None):
    global running
    running = False
    if kit is not None:
        for ch in SERVO_CHANNELS:
            try:
                kit.servo[ch].angle = 0
            except Exception:
                pass
    if i2c is not None:
        try:
            i2c.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global kit, i2c
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        i2c = smbus2.SMBus(I2C_BUS)
    except Exception as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        i2c.read_byte_data(PCA9685_ADDR, 0x00)
    except Exception as e:
        print(f"Error: no device found at 0x{PCA9685_ADDR:02X} on bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        kit = ServoKit(channels=16, i2c=i2c, address=PCA9685_ADDR)
        kit.servo.frequency = PWM_FREQ
    except Exception as e:
        print(f"Error: failed to initialize ServoKit: {e}")
        sys.exit(1)

    def move_servo(channel, angle):
        try:
            kit.servo[channel].angle = angle
            time.sleep(STEP_DELAY)
        except Exception as e:
            print(f"Error moving servo on channel {channel}: {e}")

    try:
        move_servo(SERVO_CHANNELS[0], SERVO_MIN_ANGLE)
        move_servo(SERVO_CHANNELS[1], SERVO_MIN_ANGLE)
        move_servo(SERVO_CHANNELS[0], SERVO_MAX_ANGLE)
        move_servo(SERVO_CHANNELS[1], SERVO_MAX_ANGLE)
        move_servo(SERVO_CHANNELS[0], 0)
        move_servo(SERVO_CHANNELS[1], 0)
    except Exception as e:
        print(f"Error during servo sequence: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

