import signal
import sys
import time
import logging
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO is not available. Are you running on a Raspberry Pi?", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

SOLENOID_PIN = 24
PULSE_DURATION = 0.4
PULSE_DELAY = 1.0
NUM_PULSES = 3


class SolenoidController:
    """Controls a solenoid via a relay module on a Raspberry Pi GPIO pin."""

    def __init__(self, pin: int):
        self.pin = pin
        self._active = False

    def setup(self) -> None:
        """Configure the GPIO pin as a digital output and ensure the solenoid is off."""
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.OUT, initial=GPIO.LOW)
            self._active = False
            logger.info("GPIO pin %d configured as output (solenoid control).", self.pin)
        except Exception as exc:
            logger.error("Failed to initialize GPIO pin %d: %s", self.pin, exc)
            raise

    def activate(self, duration: float) -> None:
        """Energize the solenoid for *duration* seconds, then de-energize it."""
        if self._active:
            logger.warning("Solenoid already active; skipping activation.")
            return
        try:
            GPIO.output(self.pin, GPIO.HIGH)
            self._active = True
            logger.info("Solenoid activated on pin %d for %.3f s.", self.pin, duration)
            time.sleep(duration)
        except Exception as exc:
            logger.error("Error during solenoid activation: %s", exc)
            raise
        finally:
            self.deactivate()

    def deactivate(self) -> None:
        """De-energize the solenoid and mark it as inactive."""
        try:
            GPIO.output(self.pin, GPIO.LOW)
            self._active = False
            logger.info("Solenoid de-activated on pin %d.", self.pin)
        except Exception as exc:
            logger.error("Error during solenoid de-activation: %s", exc)
            raise

    def cleanup(self) -> None:
        """De-energize the solenoid and release the GPIO resource."""
        try:
            if self._active:
                self.deactivate()
            GPIO.cleanup(self.pin)
            logger.info("GPIO cleanup completed for pin %d.", self.pin)
        except Exception as exc:
            logger.error("Error during GPIO cleanup: %s", exc)
            raise


def run_pulse_sequence(controller: SolenoidController, num_pulses: int) -> None:
    """Schedule *num_pulses* 0.4 s activations separated by 1 s delays."""
    for i in range(1, num_pulses + 1):
        logger.info("Pulse %d/%d scheduled at %s", i, num_pulses, datetime.now().isoformat())
        controller.activate(PULSE_DURATION)
        if i < num_pulses:
            time.sleep(PULSE_DELAY)


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM by raising KeyboardInterrupt in main loop."""
    logger.info("Received signal %d; initiating shutdown.", signum)
    raise KeyboardInterrupt


def main() -> None:
    controller = SolenoidController(SOLENOID_PIN)
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        controller.setup()
        run_pulse_sequence(controller, NUM_PULSES)
    except KeyboardInterrupt:
        logger.info("Program interrupted by user.")
    except Exception as exc:
        logger.error("Unexpected error: %s", exc)
    finally:
        try:
            controller.cleanup()
        except Exception as exc:
            logger.error("Error during cleanup: %s", exc)


if __name__ == "__main__":
    main()

