#!/usr/bin/env python3
"""DS1338 RTC driver for Raspberry Pi using smbus2.

Wiring (BCM numbering):
  SDA -> GPIO2 (BCM 2)
  SCL -> GPIO3 (BCM 3)
  VCC -> 3.3 V
  GND -> GND

I2C address: 0x68 (default) or 0x69 (if A0 tied high).
"""

import signal
import sys
import time
from datetime import datetime

try:
    from smbus2 import SMBus
except ImportError:
    from smbus import SMBus

# ---------------------------------------------------------------------------
