                f"Cannot open I2C bus {self._bus_num}: {exc}"
            ) from exc

        # Probe the device address to confirm it is responding.
        try:
            self._bus.read_byte(self._addr)
        except OSError as exc:
            self._bus.close()
            self._bus = None
            raise RuntimeError(
                f"No DS1338 detected at address 0x{self._addr:02X} on bus {self._bus_num}: {exc}"
