import serial
import time
import signal
import sys
from typing import Optional, Dict, Any, Tuple, List

ESP_OK = b"OK"
ESP_ERROR = b"ERROR"
ESP_FAIL = b"FAIL"
ESP_READY = b"ready"
ESP_CLOSED = b"CLOSED"

ESP_AT = b"AT\r\n"
ESP_RST = b"AT+RST\r\n"
ESP_CWJAP = b"AT+CWJAP=\"%s\",\"%s\"\r\n"
ESP_CWQAP = b"AT+CWQAP\r\n"
ESP_CIFSR = b"AT+CIFSR\r\n"
ESP_CIPSTART = b"AT+CIPSTART=\"TCP\",\"%s\",%d\r\n"
ESP_CIPSEND = b"AT+CIPSEND=%d\r\n"
ESP_CIPCLOSE = b"AT+CIPCLOSE\r\n"


class ESP8266:
    def __init__(self, port: str = "/dev/serial0", baud_rate: int = 115200, timeout: float = 1.0):
        self._uart: Optional[serial.Serial] = None
        try:
            self._uart = serial.Serial(port, baud_rate, timeout=timeout)
        except serial.SerialException as e:
            print(f"Error opening UART port {port}: {e}", file=sys.stderr)
            raise
        self._original_sigint = signal.getsignal(signal.SIGINT)
        signal.signal(signal.SIGINT, self._signal_handler)
        self._original_sigterm = signal.getsignal(signal.SIGTERM)
        signal.signal(signal.SIGTERM, self._signal_handler)

    def _signal_handler(self, signum, frame):
        print(f"\nSignal {signum} received, closing UART...", file=sys.stderr)
        self.close()
        sys.exit(0)

    def _send_command(self, command: bytes, expected_response: bytes, timeout: float = 1.0) -> Optional[bytes]:
        if self._uart is None or not self._uart.is_open:
            print("UART port is not open.", file=sys.stderr)
            return None
        try:
            self._uart.reset_input_buffer()
            self._uart.write(command)
            self._uart.flush()
            deadline = time.monotonic() + timeout
            response = b""
            while time.monotonic() < deadline:
                if self._uart.in_waiting > 0:
                    chunk = self._uart.read(self._uart.in_waiting)
                    if chunk:
                        response += chunk
                        if expected_response in response:
                            return response
                time.sleep(0.01)
            print(f"Timeout waiting for response to: {command.decode(errors='replace')}", file=sys.stderr)
            return None
        except serial.SerialException as e:
            print(f"Serial communication error: {e}", file=sys.stderr)
            return None

    def test_connection(self) -> bool:
        return self._send_command(ESP_AT, ESP_OK) is not None

    def restart(self) -> bool:
        response = self._send_command(ESP_RST, ESP_READY, timeout=5.0)
        if response is None:
            return False
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid: str, password: str) -> bool:
        command = ESP_CWJAP % (ssid, password)
        response = self._send_command(command, ESP_OK, timeout=10.0)
        return response is not None

    def disconnect_wifi(self) -> bool:
        response = self._send_command(ESP_CWQAP, ESP_OK)
        return response is not None

    def get_ip(self) -> Optional[str]:
        response = self._send_command(ESP_CIFSR, ESP_OK)
        if response is None:
            return None
        try:
            lines = response.decode(errors='replace').split("\r\n")
            for line in lines:
                if "STAIP," in line:
                    ip = line.split("STAIP,")[1].split(",")[0]
                    return ip.strip()
            return None
        except Exception as e:
            print(f"Error parsing IP address: {e}", file=sys.stderr)
            return None

    def send_http_request(self, method: str, url: str, host: str, port: int = 80, headers: Optional[Dict[str, str]] = None, data: Optional[str] = None) -> Optional[bytes]:
        request = f"{method} {url} HTTP/1.1\r\nHost: {host}\r\n"
        if headers:
            for key, value in headers.items():
                request += f"{key}: {value}\r\n"
        if data:
            request += f"Content-Length: {len(data)}\r\n"
        request += "\r\n"
        if data:
            request += data

        start_response = self._send_command(ESP_CIPSTART % (host, port), ESP_OK, timeout=5.0)
        if start_response is None:
            return None

        send_response = self._send_command(ESP_CIPSEND % len(request.encode()), ESP_GOT_IP, timeout=5.0)
        if send_response is None:
            self._send_command(ESP_CIPCLOSE, ESP_OK)
            return None

        response = self._send_command(request.encode(), ESP_CLOSED, timeout=10.0)
        self._send_command(ESP_CIPCLOSE, ESP_OK)
        return response

    def receive_http_response(self, timeout: float = 5.0) -> Tuple[Optional[Dict[str, Any]], Optional[bytes]]:
        response = self._send_command(b"", ESP_GOT_IP, timeout=timeout)
        if response is None:
            return None, None
        try:
            data = response.decode(errors='replace')
            lines = data.split("\r\n")
            status_line = lines[0]
            status_code = int(status_line.split(" ")[1])
            headers = {}
            body = None
            for line in lines[1:]:
                if line == "":
                    body = "\r\n".join(lines[2:])
                    break
                key, value = line.split(":", 1)
                headers[key.strip()] = value.strip()
            return {"status_code": status_code, "headers": headers, "body": body}, response
        except Exception as e:
            print(f"Error parsing HTTP response: {e}", file=sys.stderr)
            return None, None

    def close(self):
        if self._uart is not None and self._uart.is_open:
            try:
                self._uart.close()
            except serial.SerialException as e:
                print(f"Error closing UART port: {e}", file=sys.stderr)


if __name__ == "__main__":
    esp = ESP8266()
    if esp.test_connection():
        print("ESP8266 connected.")
        esp.restart()
        esp.connect_wifi("SSID", "PASSWORD")
        ip = esp.get_ip()
        if ip:
            print(f"IP address: {ip}")
        esp.disconnect_wifi()
    else:
        print("ESP8266 not connected.")
    esp.close()

