import time
import logging

import serial
import serial.tools.list_ports

import RPi.GPIO as GPIO

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
READ_INTERVAL = 1.0
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("radiation_monitor")

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def open_serial_port() -> serial.Serial:
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        log.error("Failed to open serial port %s: %s", SERIAL_PORT, exc)
        raise
    except Exception as exc:
        log.error("Unexpected error opening %s: %s", SERIAL_PORT, exc)
        raise


def read_radiation_level(ser: serial.Serial) -> float | None:
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        log.error("Serial read error: %s", exc)
        return None
    except OSError as exc:
        log.error("OS-level read error: %s", exc)
        return None

    if not raw:
        return None

    try:
        line = raw.decode("ascii", errors="replace").strip()
    except Exception as exc:
        log.error("Decode error: %s", exc)
        return None

    if not line:
        return None

    try:
        return float(line)
    except ValueError:
        log.warning("Non-numeric data received: %r", line)
        return None


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(ALARM_PIN, GPIO.OUT, initial=GPIO.LOW)

    ser = None
    alarm_state = False

    try:
        ser = open_serial_port()
        log.info("Monitoring radiation on %s @ %d baud (timeout %.1fs).",
                 SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)

        while _running:
            level = read_radiation_level(ser)

            if level is not None:
                print(f"Radiation Level: {level:.2f} µSv/h")

                if level > RADIATION_THRESHOLD:
                    if not alarm_state:
                        GPIO.output(ALARM_PIN, GPIO.HIGH)
                        alarm_state = True
                        log.warning("Radiation level exceeded threshold! Alarm triggered.")
                else:
                    if alarm_state:
                        GPIO.output(ALARM_PIN, GPIO.LOW)
                        alarm_state = False
                        log.info("Radiation level returned to normal. Alarm deactivated.")

            time.sleep(READ_INTERVAL)

    except serial.SerialException:
        log.error("Serial port error. Exiting.")
        return 1
    except Exception as exc:
        log.exception("Unexpected error: %s", exc)
        return 1
    finally:
        if ser is not None and ser.is_open:
            try:
                ser.close()
                log.info("Serial port closed.")
            except Exception as exc:
                log.error("Error closing serial port: %s", exc)
        GPIO.cleanup()
        log.info("GPIO cleaned up. Exiting.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

