    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port with error handling."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        print(f"Serial port {port} initialized successfully.")
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing serial port: {e}")
        return None

def parse_gps_data(data):
    """Parses NMEA GPGGA sentences to extract latitude, longitude, and altitude."""
    if not data.startswith('$GPGGA'):
        return None, None, None

    parts = data.split(',')
    if len(parts) < 10:
        return None, None, None

    try:
        fix_quality = parts[6]
        if fix_quality != '1':
            return None, None, None

        latitude = parts[2]
        longitude = parts[4]
        altitude = parts[9]

        if not latitude or not longitude or not altitude:
            return None, None, None

        return latitude, longitude, altitude
    except (IndexError, ValueError) as e:
        print(f"Error parsing GPS data: {e}")
        return None, None, None

