    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        ser.reset_input_buffer()
        ser.reset_output_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_flow_rate(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print(f"Invalid data received (not a float): '{line}'", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def log_flow_rate(flow_rate, log_file):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp} - Flow Rate: {flow_rate} L/min\n"
    try:
        with open(log_file, 'a') as f:
            f.write(log_entry)
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        while _running:
            flow_rate = read_flow_rate(serial_connection)
            if flow_rate is not None:
                print(f"Flow Rate: {flow_rate} L/min")
                log_flow_rate(flow_rate, LOG_FILE)
            time.sleep(READ_INTERVAL)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

