import logging
import signal
import sys
import time
from dataclasses import dataclass
from typing import Optional

import serial

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


@dataclass
class GPS_readings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellites: Optional[int] = None


class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_port: Optional[serial.Serial] = None
        self._connected = False

    def connect(self) -> bool:
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            self._connected = True
            logger.info("Connected to GPS on %s at %d baud.", self.port, self.baudrate)
            return True
        except serial.SerialException as exc:
            logger.error("Failed to open serial port %s: %s", self.port, exc)
            self.serial_port = None
            self._connected = False
            return False

    def disconnect(self) -> None:
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
            except Exception as exc:  # noqa: BLE001
                logger.warning("Error while closing serial port: %s", exc)
            finally:
                self.serial_port = None
                self._connected = False
        logger.info("Disconnected from GPS.")

    def _nmea_to_signed(self, value: str, direction: str) -> Optional[float]:
        if not value or not direction:
            return None
        try:
            dot = value.index(".")
            deg_len = dot - 2
            degrees = float(value[:deg_len])
            minutes = float(value[deg_len:])
            decimal = degrees + minutes / 60.0
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError) as exc:
            logger.error("Invalid coordinate format: %s (%s)", value, exc)
            return None

    def _parse_gpgga(self, sentence: str) -> Optional[GPS_readings]:
        if not sentence.startswith("$GPGGA"):
            return None
        if "*" in sentence:
            sentence, _ = sentence.split("*", 1)
        fields = sentence.split(",")
        if len(fields) < 10:
            logger.error("GPGGA sentence too short: %s", sentence)
            return None
        try:
            fix_quality = int(fields[6])
            if fix_quality == 0:
                logger.warning("No GPS fix (GPGGA sentence).")
                return None
        except ValueError:
            logger.error("Invalid fix quality in GPGGA: %s", fields[6])
            return None
        lat = self._nmea_to_signed(fields[2], fields[3])
        lon = self._nmea_to_signed(fields[4], fields[5])
        if lat is None or lon is None:
            return None
        try:
            altitude = float(fields[9]) if fields[9] else None
        except ValueError:
            logger.error("Invalid altitude in GPGGA: %s", fields[9])
            altitude = None
        try:
            satellites = int(fields[7]) if fields[7] else None
        except ValueError:
            logger.error("Invalid satellite count in GPGGA: %s", fields[7])
            satellites = None
        return GPS_readings(latitude=lat, longitude=lon, altitude=altitude, satellites=satellites)

    def read_gps_data(self) -> Optional[GPS_readings]:
        if not self._connected or self.serial_port is None:
            logger.error("GPS not connected.")
            return None
        try:
            raw = self.serial_port.readline()
            if not raw:
                logger.warning("Read timeout: no data received.")
                return None
            sentence = raw.decode("ascii", errors="replace").strip()
            return self._parse_gpgga(sentence)
        except serial.SerialException as exc:
            logger.error("Serial communication error: %s", exc)
            return None
        except Exception as exc:  # noqa: BLE001
            logger.error("Unexpected error reading GPS: %s", exc)
            return None


_running = True


def _signal_handler(signum, _frame):
    global _running
    logger.info("Signal %s received, shutting down.", signum)
    _running = False


def main() -> int:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    gps = GPSReader()
    if not gps.connect():
        return 1
    try:
        while _running:
            reading = gps.read_gps_data()
            if reading is not None:
                logger.info(
                    "GPS: lat=%.6f lon=%.6f alt=%.2f m sat=%s",
                    reading.latitude,
                    reading.longitude,
                    reading.altitude if reading.altitude is not None else 0.0,
                    reading.satellites if reading.satellites is not None else 0,
                )
            time.sleep(1.0)
    except Exception as exc:  # noqa: BLE001
        logger.error("Fatal error in main loop: %s", exc)
        return 1
    finally:
        gps.disconnect()
    return 0


if __name__ == "__main__":
    sys.exit(main())

