import time
from typing import Optional

from serial import Serial, SerialException, SerialTimeoutException

UART_TX_PIN = 14
UART_RX_PIN = 15
UART_BAUDRATE = 115200
UART_TIMEOUT = 5
RESTART_DELAY = 2
WIFI_CONNECT_DELAY = 5
MAX_RETRIES = 3


class ESP8266:
    def __init__(self, port: str, baudrate: int = UART_BAUDRATE, timeout: int = UART_TIMEOUT):
        self._port = port
        self._uart: Optional[Serial] = None
        try:
            self._uart = Serial(
                port=port,
                baudrate=baudrate,
                bytesize=8,
                parity="N",
                stopbits=1,
                timeout=timeout,
                write_timeout=timeout,
            )
            self._uart.reset_input_buffer()
            self._uart.reset_output_buffer()
        except SerialException as e:
            raise RuntimeError(f"Failed to initialize UART on {port}: {e}") from e

    def _send_command(self, command: str, delay: int = 1, max_retries: int = MAX_RETRIES) -> Optional[str]:
        if not self._uart or not self._uart.is_open:
            raise RuntimeError("UART port is not open.")
        try:
            self._uart.reset_input_buffer()
            self._uart.write(command.encode("utf-8"))
            self._uart.flush()
            time.sleep(delay)
            return self._read_response(timeout=UART_TIMEOUT, max_retries=max_retries)
        except SerialTimeoutException as e:
            raise RuntimeError(f"Write timeout on command '{command}': {e}") from e
        except SerialException as e:
            raise RuntimeError(f"UART communication error on command '{command}': {e}") from e

    def _read_response(self, timeout: int = UART_TIMEOUT, max_retries: int = MAX_RETRIES) -> Optional[str]:
        if not self._uart or not self._uart.is_open:
            raise RuntimeError("UART port is not open.")
        response = ""
        start_time = time.time()
        while time.time() - start_time < timeout:
            try:
                if self._uart.in_waiting > 0:
                    chunk = self._uart.read(self._uart.in_waiting)
                    if chunk:
                        response += chunk.decode("utf-8", errors="ignore")
                        if "OK" in response or "ERROR" in response or "FAIL" in response:
                            return response
            except SerialException as e:
                raise RuntimeError(f"UART read error: {e}") from e
            time.sleep(0.01)
        return None

    def test_connection(self) -> bool:
        response = self._send_command("AT\r\n")
        return response is not None and "OK" in response

    def restart(self) -> bool:
        response = self._send_command("AT+RST\r\n", delay=RESTART_DELAY)
        return response is not None and "ready" in response.lower()

