import serial
import time
import signal
import sys
from typing import Optional, List, Tuple


class GPS:
    """Driver for a GPS module controlled via AT commands over a UART link."""

    def __init__(self, port: str = '/dev/ttyAMA0', baud: int = 9600) -> None:
        self.port = port
        self.baud = baud
        self.ser: Optional[serial.Serial] = None
        self._closed = False
        try:
            self.ser = serial.Serial(
                port=port,
                baudrate=baud,
                timeout=1.0,
                write_timeout=1.0,
            )
        except serial.SerialException as exc:
            raise RuntimeError(f"Failed to open {port}: {exc}") from exc

    # ------------------------------------------------------------------
    # Context-manager support
    # ------------------------------------------------------------------
    def __enter__(self) -> "GPS":
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()

    # ------------------------------------------------------------------
    # Resource management
    # ------------------------------------------------------------------
    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        if self.ser is not None:
            try:
                self.ser.close()
            except Exception:
                pass
            self.ser = None

    # ------------------------------------------------------------------
    # AT command helpers
    # ------------------------------------------------------------------
    def _send_at(self, command: str, wait: float = 1.0) -> bool:
        if self.ser is None or self.ser.is_open is False:
            return False
        try:
            self.ser.reset_input_buffer()
            self.ser.write(command.encode('ascii'))
            self.ser.flush()
        except serial.SerialException:
            return False
        time.sleep(wait)
        return True

    def attach(self) -> bool:
        """Power on the GNSS receiver and wait for it to settle."""
        return self._send_at('AT+CGNSPWR=1\r\n', wait=1.0)

    def detach(self) -> bool:
        """Power off the GNSS receiver."""
        return self._send_at('AT+CGNSPWR=0\r\n')

    # ------------------------------------------------------------------
    # Data parsing
    # ------------------------------------------------------------------
    @staticmethod
    def _parse_gprmc(line: str) -> Optional[List[str]]:
        if not line.startswith('$GPRMC'):
            return None
        parts = line.split(',')
        if len(parts) < 8:
            return None
        if parts[2] != 'A':
            return None
        return parts

    def get_data(self) -> Optional[List[str]]:
        """Return the parsed GPRMC fields, or None if unavailable."""
        if self.ser is None or self.ser.is_open is False:
            return None
        try:
            raw = self.ser.readline()
        except serial.SerialException:
            return None
        if not raw:
            return None
        try:
            line = raw.decode('ascii', errors='replace').strip()
        except Exception:
            return None
        return self._parse_gprmc(line)

    # ------------------------------------------------------------------
    # Signal handling for clean shutdown
    # ------------------------------------------------------------------
    def _install_signal_handlers(self) -> None:
        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                signal.signal(sig, self._signal_handler)
            except (ValueError, OSError):
                pass

    def _signal_handler(self, signum, frame) -> None:
        self.close()
        sys.exit(0)


# ----------------------------------------------------------------------
# Example usage
# ----------------------------------------------------------------------
if __name__ == '__main__':
    gps = GPS(port='/dev/ttyAMA0', baud=9600)
    gps._install_signal_handlers()
    try:
        if not gps.attach():
            print("Failed to power on GPS")
            sys.exit(1)
        while True:
            data = gps.get_data()
            if data is not None:
                print(data)
            time.sleep(0.5)
    except KeyboardInterrupt:
        pass
    finally:
        gps.close()

