import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'health_readings_log.txt'
LOOP_DELAY = 0.1

running = True
serial_connection = None


def signal_handler(signum, frame):
    global running
    running = False


def log_data(data_string):
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_entry = f'{timestamp}: {data_string}\n'
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(log_entry)
    except IOError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)
    print(log_entry, end='')


def process_reading(raw_data):
    try:
        parts = raw_data.split(',')
        if len(parts) != 2:
            raise ValueError('Expected exactly two comma-separated values')
        heart_rate, spo2 = parts
        heart_rate = int(heart_rate)
        spo2 = int(spo2)
        if not (0 <= heart_rate <= 100) or not (0 <= spo2 <= 100):
            raise ValueError('Values out of expected range')
        log_data(f'Heart Rate: {heart_rate}% SpO2: {spo2}%')
    except ValueError as e:
        print(f'Invalid data format: {e} | Raw: {raw_data}', file=sys.stderr)


def main():
    global serial_connection
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud.')
        while running:
            try:
                raw_bytes = serial_connection.readline()
                if not raw_bytes:
                    continue
                decoded_data = raw_bytes.decode('ascii', errors='replace').strip()
                if decoded_data:
                    process_reading(decoded_data)
                time.sleep(LOOP_DELAY)
            except serial.SerialException as e:
                print(f'Serial communication error: {e}', file=sys.stderr)
                time.sleep(LOOP_DELAY)
            except Exception as e:
                print(f'Unexpected error: {e}', file=sys.stderr)
                time.sleep(LOOP_DELAY)
    except serial.SerialException as e:
        print(f'Failed to open serial port: {e}', file=sys.stderr)
    except Exception as e:
        print(f'Initialization error: {e}', file=sys.stderr)
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print('Serial port closed.')
        print('Program terminated.')


if __name__ == '__main__':
    main()

