import logging
import signal
import sys

try:
    from serial import Serial, SerialException
except ImportError:
    Serial = None
    SerialException = Exception

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class SimpleGPS:
    """Minimal GPS NMEA parser for $GPGGA and $GNGGA sentences over UART."""

    def __init__(self, port="/dev/serial0", baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_conn = None
        self._closed = False

    def connect(self):
        """Open the UART port; return True on success, False on failure."""
        if Serial is None:
            logging.error("pyserial is not installed; cannot open UART.")
            return False
        try:
            self.serial_conn = Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=8,
                parity="N",
                stopbits=1,
                timeout=1.0,
            )
            logging.info(
                "Connected to GPS on %s at %d baud.", self.port, self.baudrate
            )
            return True
        except SerialException as exc:
            logging.error("Failed to open UART %s: %s", self.port, exc)
            self.serial_conn = None
            return False
        except OSError as exc:
            logging.error("OS error opening %s: %s", self.port, exc)
            self.serial_conn = None
            return False

    def read_data(self):
        """Read one line from the UART; return stripped UTF-8 string or None."""
        if self.serial_conn is None or self._closed:
            return None
        try:
            if not self.serial_conn.in_waiting:
                return None
            raw = self.serial_conn.readline()
            if not raw:
                return None
            return raw.decode("utf-8", errors="ignore").strip()
        except SerialException as exc:
            logging.error("UART read error: %s", exc)
            self.close()
            return None
        except OSError as exc:
            logging.error("OS read error: %s", exc)
            self.close()
            return None

    def parse_gga(self, gga_data):
        """Parse a $GPGGA or $GNGGA line; return dict or None on malformed data."""
        if not gga_data:
            return None
        if not (gga_data.startswith("$GPGGA") or gga_data.startswith("$GNGGA")):
            return None
        parts = gga_data.split(",")
        if len(parts) < 15:
            logging.warning("Malformed GGA sentence (too few fields): %r", gga_data)
            return None
        try:
            utc_time = parts[1]
            fix_quality = parts[6]
            num_satellites = parts[7]
            lat_raw = parts[2]
            lat_dir = parts[3]
            lon_raw = parts[4]
            lon_dir = parts[5]
        except IndexError:
            logging.error("Malformed GGA sentence (field index error): %r", gga_data)
            return None
        if not lat_raw or not lon_raw:
            return None
        latitude = self._decode_coordinate(lat_raw, lat_dir)
        longitude = self._decode_coordinate(lon_raw, lon_dir)
        return {
            "utc_time": utc_time,
            "latitude": latitude,
            "longitude": longitude,
            "fix_quality": fix_quality,
            "num_satellites": num_satellites,
        }

    @staticmethod
    def _decode_coordinate(raw, direction):
        """Convert NMEA coordinate (ddmm.mmmm) to decimal degrees."""
        if not raw:
            return None
        try:
            dot = raw.index(".")
            deg_len = dot - 2
            degrees = float(raw[:deg_len])
            minutes = float(raw[deg_len:])
            decimal = degrees + (minutes / 60.0)
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError):
            logging.warning("Could not decode coordinate %r", raw)
            return None

    def close(self):
        """Close the UART connection if open; safe to call multiple times."""
        if self.serial_conn is None or self._closed:
            return
        try:
            if self.serial_conn.is_open:
                self.serial_conn.close()
                logging.info("UART connection closed.")
        except SerialException as exc:
            logging.error("Error closing UART: %s", exc)
        except OSError as exc:
