import signal
import threading
import time
from typing import Optional, List, Dict, Any

from flask import Flask, Response, jsonify, request, abort
from serial import Serial, SerialException, SerialTimeoutException

app = Flask(__name__)

# Thread-safe state
_data: List[Dict[str, Any]] = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": True},
]
_next_id: int = 3
_lock = threading.Lock()
_uart: Optional[Serial] = None
_running = True


def _open_uart() -> Optional[Serial]:
    """Open the UART port, returning the Serial object or None on failure."""
    global _uart
    try:
        _uart = Serial(
            port="/dev/ttyUSB0",
            baudrate=9600,
            bytesize=8,
            parity="N",
            stopbits=1,
            timeout=1.0,
        )
        return _uart
    except SerialException as exc:
        print(f"[ERROR] Cannot open /dev/ttyUSB0: {exc}")
        _uart = None
        return None


def _close_uart() -> None:
    """Close the UART port if open; safe to call multiple times."""
    global _uart
    if _uart is not None:
        try:
            _uart.close()
        except SerialException as exc:
            print(f"[WARN] Error closing UART: {exc}")
        finally:
            _uart = None


def _send_command(cmd: str) -> Optional[str]:
    """Send *IDN? to the instrument and return the response line, or None."""
    if _uart is None:
        print("[ERROR] UART not open")
        return None
    try:
        _uart.reset_input_buffer()
        _uart.write(cmd.encode("ascii"))
        _uart.flush()
        raw = _uart.readline()
        if not raw:
            print("[ERROR] No response (timeout)")
            return None
        return raw.decode("ascii", errors="replace").strip()
    except SerialTimeoutException as exc:
        print(f"[ERROR] Write timeout: {exc}")
        return None
    except SerialException as exc:
        print(f"[ERROR] UART I/O error: {exc}")
        return None


@app.route("/version", methods=["GET"])
def version() -> Response:
    """Send *IDN? to the instrument and return its response."""
    resp = _send_command("*IDN?\n")
    if resp is None:
        return Response("No response from device\n", status=504, mimetype="text/plain")
    return Response(resp + "\n", mimetype="text/plain")


@app.route("/data", methods=["GET"])
def get_data() -> Response:
    """Return the in-memory list of items."""
    with _lock:
        return jsonify(_data)


@app.route("/data/<int:item_id>", methods=["GET"])
def get_item(item_id: int) -> Response:
    """Return a single item by id."""
    with _lock:
        item = next((it for it in _data if it["id"] == item_id), None)
    if item is None:
        abort(404, description="Item not found")
    return jsonify(item)


@app.route("/data", methods=["POST"])
def post_data() -> Response:
    """Create a new item with auto-incremented id."""
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        abort(400, description="Request body must be JSON")
    name = data.get("name")
    done = data.get("done")
    if not isinstance(name, str) or not name.strip():
        abort(400, description="name must be a non-empty string")
    if not isinstance(done, bool):
        abort(400, description="done must be a boolean")
    with _lock:
        new_id = _next_id
        _data.append({"id": new_id, "name": name, "done": done})
        _next_id += 1
    return jsonify({"id": new_id, "name": name, "done": done}), 201


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    print(f"\n[INFO] Signal {signum} received, shutting down...")
    _running = False
    _close_uart()


def main() -> None:
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Open UART once at startup
    if _open_uart() is None:
        print("[ERROR] Cannot start web service without UART")
        return

    try:
        app.run(host="0.0.0.0", port=5000, debug=False)
    finally:
        _close_uart()


if __name__ == "__main__":
    main()

