import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'access_log.txt'

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_access_event(tag_id):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - RFID Tag: {tag_id}\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as logfile:
            logfile.write(log_entry)
            logfile.flush()
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)

def process_rfid_tag(tag_id):
    print(f'Access granted for RFID Tag: {tag_id}')
    log_access_event(tag_id)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = None
    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            timeout=TIMEOUT
        )
        print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud.')

        while running:
            try:
                raw_line = serial_connection.readline()
                if not raw_line:
                    continue
                rfid_tag = raw_line.decode('ascii', errors='replace').strip()
                if rfid_tag:
                    process_rfid_tag(rfid_tag)
            except serial.SerialException as e:
                print(f'Serial communication error: {e}', file=sys.stderr)
                break
            except Exception as e:
                print(f'Unexpected error processing tag: {e}', file=sys.stderr)

    except serial.SerialException as e:
        print(f'Could not open serial port {SERIAL_PORT}: {e}', file=sys.stderr)
    except Exception as e:
        print(f'Unexpected initialization error: {e}', file=sys.stderr)
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print('Serial port closed.')

if __name__ == '__main__':
