from flask import Flask, Response, request, jsonify

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

app = Flask(__name__)

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1.0
READ_DELAY = 0.1

data = [{'id': 1, 'name': 'Task 1'}, {'id': 2, 'name': 'Task 2'}]

try:
    ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    logger.info(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
except serial.SerialException as e:
    logger.error(f"Failed to open serial port {SERIAL_PORT}: {e}")
    ser = None


def send_scpi_command(cmd: str) -> str | None:
    if ser is None:
        logger.error("Serial port not available.")
        return None
    try:
        ser.reset_input_buffer()
        ser.write(cmd.encode('ascii'))
        time.sleep(READ_DELAY)
        raw = ser.read(4096)
        if not raw:
            logger.warning("No response from device.")
            return None
        return raw.decode('ascii', errors='replace')
    except serial.SerialException as e:
        logger.error(f"Serial communication error: {e}")
        return None
    except Exception as e:
        logger.error(f"Unexpected error during SCPI command: {e}")
        return None


@app.route('/version', methods=['GET'])
def version():
    resp = send_scpi_command('*IDN?\n')
    if resp is None:
        return Response("Serial communication error.\n", status=503, mimetype='text/plain')
    return Response(resp.replace('\n', '<br>'), mimetype='text/html')


@app.route('/getdata', methods=['GET'])
def get_data():
    return jsonify(data)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set(item_id):
    item = next((it for it in data if it['id'] == item_id), None)
    if item is None:
        return jsonify({'error': 'Item not found'}), 404
    return jsonify(item)


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def get_post(item_id, name):
    new_item = {'id': item_id, 'name': name, 'done': False}
    data.append(new_item)
    return jsonify(data)


@app.route('/postjson', methods=['POST'])
def post_json():
    if request.is_json:
        new_item = request.get_json(silent=True)
    else:
        new_item = request.form.to_dict(flat=False)
    if not isinstance(new_item, dict):
        return jsonify({'error': 'Invalid JSON or form data'}), 400
    if 'id' not in new_item:
        new_item['id'] = max(item['id'] for item in data) + 1 if data else 1
    if 'name' not in new_item:
        new_item['name'] = ''
    if 'done' not in new_item:
        new_item['done'] = False
    else:
        val = new_item['done']
        if isinstance(val, str):
            new_item['done'] = val.lower() in ('true', '1', 'yes')
        elif isinstance(val, bool):
            new_item['done'] = val
        else:
            new_item['done'] = bool(val)
    data.append(new_item)
    return jsonify(data), 201


@app.route('/postjson', methods=['GET'])
def get_post_json():
    return jsonify(data)


if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', debug=False)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            logger.info("Serial port closed.")

